        [`\j:num. read (memory :> bytes64 (word_add z (word (8 * j)))) s16 : int64`;
         `word_subword (word_join (sum_s8:int64) (cwin:int64):int128) (3,64):int64`;
         `hfin:int64`; `i:num`; `pcode:num`] HF_STEP_G_NEG) THEN
      BETA_TAC THEN ANTS_TAC THENL
