          (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
            == a DIV 2 EXP (61 * ii)) (mod b) /\
          2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
          2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * (k + 1)) /\
