    UNDISCH_TAC `2 EXP 61 * zv + block < 2 EXP X17v` THEN ASM_REWRITE_TAC[]]);;

(* --- (6) WIN_INV2_FLAT_GEN_JJ : for block_flat_gen_304_win (window=0 flat, pcode>l, qh=0, b-FREE) --- *)
let FIELDSEL_CLOSE_WIN_INV2_FLAT_GEN_JJ = prove
 (`!p pc k z n x m a b zv block ii l X17v X19v X16v X21v.
    block = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 /\ zv < 2 EXP p /\ 2 <= l /\
    2 EXP (p - 1) <= b /\ 1 <= p /\
    2 EXP 61 * zv + block < 2 EXP (64 * l) /\
    2 EXP 61 * zv + block < 2 EXP X17v /\
    (zv == a DIV 2 EXP (61 * (ii + 1))) (mod b)
    ==> ensures arm
     (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x2e8) /\
          read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
          read X4 s = m /\ read X20 s = word p /\ read X21 s = word X21v /\
          read X16 s = word X16v /\ read X17 s = word X17v /\ read X19 s = word X19v /\
          read X12 s = word (p DIV 64 + 1) /\ read X23 s = word 0 /\
          read X13 s = word (bigdigit (2 EXP 61 * zv + block) ((p DIV 64 + 1) - 1)) /\
          read X14 s = word (bigdigit (2 EXP 61 * zv + block) (p DIV 64 + 1)) /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
          bignum_from_memory (z,k) s = 2 EXP 61 * zv + block)
     (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
          read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
          read X4 s = m /\ read X20 s = word p /\ read X21 s = word X21v /\
          read X16 s = word X16v /\ read X17 s = word X17v /\ read X19 s = word X19v /\
          read X12 s = word (p DIV 64 + 1) /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
          (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
            == a DIV 2 EXP (61 * ii)) (mod b) /\
          2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
          2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * l) /\
          2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP X17v /\
          read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                              DIV 2 EXP p) MOD 2 EXP 64))
     (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                 X16; X17; X19; X20; X21; X22; X23; X24] ,,
      MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`p:num`; `bigdigit (2 EXP 61 * zv + block) ((p DIV 64 + 1) - 1)`;
                 `bigdigit (2 EXP 61 * zv + block) (p DIV 64 + 1)`; `pc:num`; `k:num`;
                 `z:int64`; `n:num`; `x:int64`; `m:int64`; `a:num`; `b:num`; `0`;
                 `2 EXP 61 * zv + block`; `X17v:num`; `X19v:num`; `X16v:num`; `X21v:num`]
                BIGNUM_MOD_FIELDSEL_WIDE_X12) THEN
  REWRITE_TAC[BIGDIGIT_BOUND; SOME_FLAGS] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] ENSURES_POSTCONDITION_THM) THEN
  GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[VAL_WORD_0; MULT_CLAUSES; ADD_CLAUSES] THEN
  ASM_SIMP_TAC[WINDOW_FROM_LOGGED_PCODE] THEN
  REWRITE_TAC[CONJ_ASSOC] THEN CONJ_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zv:num`;
                     `2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
                     `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`] GROWING_VALUE_CLOSE_TIGHT) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
      FIRST_X_ASSUM(fun th -> if concl th = `2 EXP 61 * zv + block < 2 EXP (64 * l)`
         then MP_TAC th THEN ASM_REWRITE_TAC[] else NO_TAC)];
    UNDISCH_TAC `2 EXP 61 * zv + block < 2 EXP X17v` THEN ASM_REWRITE_TAC[]]);;

Printf.printf "\n=== jj_segc.ml: 5 early jj-aware seg-C variants (SAT,WIN_INV2,WIN_INV2_TIGHT,WIN_INV2_FLAT_GEN,DDK_SEGC); GROW_GEN_JJ in jj_segc_grow, L1_JJ in block_l1 ===\n%!";;


(* ======== inlined: block_b_grow_304_win.ml ======== *)
(* Stage 3f: WINDOW-carrying GROWING regime-B block 0x1a4 -> 0x304.  Like BIGNUM_MOD_BLOCK_B_GROW_
   304 but the post ALSO carries the invariant window X15 = word((Zf' DIV 2^p) MOD 2^64), matching
   the PDOWN body goal (body_lemma_inv2.tm).  Delta vs the cong+bound block:
   - 0x2e8 midpoint ALSO asserts the two FINALIZED logged digits X13=word(bigdigit Zf'(pcode-1)),
     X14=word(bigdigit Zf' pcode) [Zf'=2^61*zv+block, pcode=p DIV64+1];
   - seg C uses BIGNUM_MOD_FIELDSEL_CLOSE_WIN (produces the window);
   - seg-B post-impl additionally proves the finalized digits: bignum(z,k) s'=Zf' gives (via
     BIGDIGIT_BIGNUM_FROM_MEMORY) the tail stores = word(bigdigit Zf' dd/(dd+1)); TAIL_LOGIN_TO_ZPRE
     converts the prefix lfw/hfw to zpre-bridges; LOGDIGIT_FINALIZE_BRIDGE finalizes.
   Deps: everything BLOCK_B_GROW_304 uses + FIELDSEL_CLOSE_WIN, LOGDIGIT_FINALIZE_BRIDGE,
   TAIL_LOGIN_TO_ZPRE, ZF_BOUND_GROW, BIGDIGIT_AGREE_BELOW (win_block_helpers.ml). *)

let BIGNUM_MOD_BLOCK_B_GROW_304_WIN = prove
 (`!k z m x n a b pc p ii w l Zt zv X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= l /\ l < k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ X17v + 124 < 2 EXP 64 /\
     (X17v + 124) DIV 64 = l + 1 /\
     (2 EXP (64 * k) * Zt + zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Zt + zv < b * 2 EXP 64 /\
     2 EXP (64 * k) * Zt + zv < 2 EXP (64 * l) /\
     2 EXP (64 * k) * Zt + zv < 2 EXP X17v /\
     ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0 /\
     nonoverlapping (word pc,0x438) (z,8 * k) /\
     nonoverlapping (word pc,0x438) (m,8 * k) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word l /\ read X12 s = word (p DIV 64 + 1) /\
           read X23 s = word Zt /\ read X15 s = word 0 /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\
           read X17 s = word (X17v + 61) /\ read X19 s = word (l + 1) /\
           read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
             == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * (l + 1)) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                               DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zv:num`; `l:num`] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `zv < 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC WINDOW_ZERO_IMP_LT THEN ASM_REWRITE_TAC[] THEN
    (* bridge the tight incoming bound zv < b*2^64 to the loose zv < 2^(p+64) that
       WINDOW_ZERO_IMP_LT consumes (b < 2^p => b*2^64 <= 2^(p+64)); kept LOCAL so it
       does not perturb downstream ASM_REWRITE subgoal counts *)
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN
    ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* midpoint 0x2e8: assembled value + the two finalized logged digits *)
  ENSURES_SEQUENCE_TAC `pc + 0x2e8`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
        read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
        read X16 s = word (61 * ii) /\ read X17 s = word (X17v + 61) /\
        read X19 s = word (l + 1) /\ read X12 s = word (p DIV 64 + 1) /\
        read X23 s = word 0 /\
        read X13 s = word (bigdigit (2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61)
                                    ((p DIV 64 + 1) - 1)) /\
        read X14 s = word (bigdigit (2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61)
                                    (p DIV 64 + 1)) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
  CONJ_TAC THENL
   [ALL_TAC;
    (* seg C: FIELDSEL_CLOSE_WIN_INV2_TIGHT_JJ 0x2e8 -> 0x304 (cong + tight bound + INV2 + window + jj) *)
    MP_TAC(ISPECL [`p:num`; `pc:num`; `k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                   `a:num`; `b:num`; `zv:num`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
                   `ii:num`; `l:num`; `X17v + 61`; `l + 1`; `61 * ii`; `w:num`]
                  FIELDSEL_CLOSE_WIN_INV2_TIGHT_JJ) THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      (* jj-hyp: 2^61*zv+block < 2^(X17v+61) via JJ_STEP (zv<2^X17v, qh=0) *)
      MP_TAC(ISPECL [`zv:num`; `0`; `b:num`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `X17v:num`] JJ_STEP) THEN
      ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ; MULT_CLAUSES; SUB_0]; ALL_TAC] THEN
    MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] ENSURES_POSTCONDITION_THM) THEN
    GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]] THEN
  (* seg A: prefix 0x1a4 -> 0x23c *)
  ENSURES_SEQUENCE_TAC `pc + 0x23c`
   `\s. read X8 s = word (l - 1) /\
        read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
        read X11 s = word (l - 1) /\ read X12 s = word (p DIV 64 + 1) /\
        read X15 s = word (((w * 0) DIV 2 EXP 64 + 0) MOD 2 EXP 64) /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (word_add z (word (8 * (l - 1))), k - (l - 1)) s = highdigits zv (l - 1) /\
        (1 <= l - 1 ==> read X13 s =
            read (memory :> bytes64 (word_add z (word (8 * (MIN (l-1) (p DIV 64 + 1) - 1))))) s) /\
        (p DIV 64 + 1 < l - 1 ==> read X14 s =
            read (memory :> bytes64 (word_add z (word (8 * (p DIV 64 + 1))))) s) /\
        (~(p DIV 64 + 1 < l - 1) ==> read X14 s = word 0) /\
        read X2 s = word n /\ read X3 s = x /\ read X16 s = word (61 * ii) /\
        read X17 s = word X17v /\ read X19 s = word l /\ read X20 s = word p /\
        read X21 s = word w /\ read X23 s = word 0 /\
        bignum_from_memory (x,n) s = a /\
        bignum_from_memory (z,l-1) s +
        2 EXP (64 * (l-1)) * (val(read X22 s) DIV 8 + 2 EXP 61 * val(read X5 s)) +
        2 EXP 61 * (((w * 0) DIV 2 EXP 64 + 0) MOD 2 EXP 64 * lowdigits b (l-1)) =
        (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 + 2 EXP 61 * lowdigits zv (l-1) +
        2 EXP 61 * (((w * 0) DIV 2 EXP 64 + 0) MOD 2 EXP 64 * 2 EXP (64 * (l-1)))` THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`k:num`; `z:int64`; `m:int64`; `x:int64`; `n:num`; `a:num`; `b:num`;
                   `pc:num`; `p:num`; `ii:num`; `w:num`; `0`; `l:num`; `0`;
                   `zv:num`; `X17v:num`; `lfv:num`; `hfv:num`] BIGNUM_MOD_PREFIX_DDGE1) THEN
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; DIV_0; MOD_0] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `0 < 2 EXP 64`] THEN
      (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l < k` THEN ARITH_TAC);
      REWRITE_TAC[SOME_FLAGS] THEN DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* seg B: tail-B_X 0x23c -> 0x2e8, assemble value + finalize the two logged digits *)
  GHOST_INTRO_TAC `hiw:int64` `read X5` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read X22` THEN
  GHOST_INTRO_TAC `lfw:int64` `read X13` THEN
  GHOST_INTRO_TAC `hfw:int64` `read X14` THEN
  GHOST_INTRO_TAC `zpre:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(ISPECL
    [`k:num`; `((w * 0) DIV 2 EXP 64 + 0) MOD 2 EXP 64`; `val(hiw:int64)`;
     `val(cwinw:int64)`; `0`; `b:num`; `zpre:num`; `m:int64`; `z:int64`;
     `pc:num`; `X17v:num`; `p DIV 64 + 1`; `l - 1`; `val(lfw:int64)`; `val(hfw:int64)`;
     `x:int64`; `n:num`; `a:num`;
     `word n:int64`; `x:int64`; `word (61*ii):int64`; `word p:int64`; `word w:int64`]
    TAIL_DDLT_B_WIDE_LOG_X) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l < k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN
     UNDISCH_TAC `p < 2 EXP 64` THEN
     UNDISCH_TAC `(X17v + 124) DIV 64 = l + 1` THEN ARITH_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN `(l - 1) + 1 = l /\ (l - 1) + 2 = l + 1` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN
  REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL];
    SUBSUMED_MAYCHANGE_TAC;
    (* post-implication *)
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    (* the zpre-vs-zv link + bignum(z,l-1)@0x23c = lowdigits zpre *)
    SUBGOAL_THEN `highdigits zpre (l - 1) = highdigits zv (l - 1)` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th =
         `bignum_from_memory (word_add z (word (8 * (l - 1))),k - (l - 1)) s = highdigits zv (l - 1)`
       then MP_TAC th else NO_TAC) THEN
      GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM HIGHDIGITS_BIGNUM_FROM_MEMORY] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `bignum_from_memory (z,l-1) s = lowdigits zpre (l-1)` ASSUME_TAC THENL
     [EXPAND_TAC "zpre" THEN REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN UNDISCH_TAC `l < k` THEN ARITH_TAC;
      ALL_TAC] THEN
    (* the assembled value *)
    SUBGOAL_THEN `bignum_from_memory (z,k) s' = 2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`
      ASSUME_TAC THENL
     [MATCH_MP_TAC GROWING_ZK_FROM_STORES THEN
      MAP_EVERY EXISTS_TAC
       [`l:num`; `zpre:num`; `b:num`; `val(hiw:int64)`; `val(cwinw:int64)`;
        `bigdigit zpre (l - 1) + val(hiw:int64) +
         ((w * 0) DIV 2 EXP 64 + 0) MOD 2 EXP 64 * (2 EXP 64 - 1 - bigdigit b (l - 1))`] THEN
      ASM_REWRITE_TAC[VAL_BOUND_64] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `bignum_from_memory (z,l - 1) s = lowdigits zpre (l - 1)`]) THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
        RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES; DIV_0; MOD_0]) THEN
        REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; DIV_0; MOD_0] THEN FIRST_ASSUM ACCEPT_TAC;
        SUBGOAL_THEN `bigdigit zpre (l - 1) = bigdigit zv (l - 1)` MP_TAC THENL
         [MP_TAC(AP_TERM `\h. bigdigit h 0`
            (ASSUME `highdigits zpre (l - 1) = highdigits zv (l - 1)`)) THEN
          REWRITE_TAC[BIGDIGIT_HIGHDIGITS; ADD_CLAUSES];
          REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; DIV_0; MOD_0] THEN ARITH_TAC]];
      ALL_TAC] THEN
    (* the two tail stores = bigdigit Zf' at dd, dd+1 (via bignum(z,k) s' = Zf') *)
    ABBREV_TAC `Zf = 2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
    SUBGOAL_THEN `l - 1 < k /\ l < k` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `l < k` THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s' = word (bigdigit Zf (l - 1)) /\
      read (memory :> bytes64 (word_add z (word (8 * l)))) s' = word (bigdigit Zf l)`
      STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN MATCH_MP_TAC STORE_IS_BIGDIGIT THEN EXISTS_TAC `k:num` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* the two store-WORD forms (from the tail post) = word(bigdigit Zf dd/(dd+1)), by
       transitivity through the reads (STOREWORD_EQ_BIGDIGIT builds these from the assumptions). *)
    (fun (asl,w) ->
      let readL1 = `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s'` in
      let readL  = `read (memory :> bytes64 (word_add z (word (8 * l)))) s'` in
      let thms = map snd asl in
      let iseqL t = is_eq(concl t) in
      let isword t = is_comb t && fst(strip_comb t) = `word:num->int64` in
      let tailL1 = find (fun th -> iseqL th && lhs(concl th)=readL1 && not(isword(rand(concl th)))) thms in
      let idL1 = find (fun th -> iseqL th && lhs(concl th)=readL1 && isword(rand(concl th))) thms in
      let tailL = find (fun th -> iseqL th && lhs(concl th)=readL && not(isword(rand(concl th)))) thms in
      let idL = find (fun th -> iseqL th && lhs(concl th)=readL && isword(rand(concl th))) thms in
      (ASSUME_TAC(TRANS (SYM tailL1) idL1) THEN ASSUME_TAC(TRANS (SYM tailL) idL)) (asl,w)) THEN
    (* the zpre-bridges for lfw/hfw from the prefix logging, via TAIL_LOGIN_TO_ZPRE *)
    MP_TAC(ISPECL [`z:int64`; `k:num`; `zpre:num`; `l - 1`; `p DIV 64 + 1`;
                   `lfw:int64`; `hfw:int64`; `s:armstate`] TAIL_LOGIN_TO_ZPRE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`]; ALL_TAC] THEN
    STRIP_TAC THEN
    (* finalize both digits: LOGDIGIT_FINALIZE_BRIDGE.  ASM_REWRITE folds the storeword eqns so
       both the bridge instance and the goal's X13/X14 conditionals use word(bigdigit Zf ..). *)
    MP_TAC(ISPECL [`Zf:num`; `zpre:num`; `l - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`]
                  LOGDIGIT_FINALIZE_BRIDGE) THEN
    ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`] THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [SUBGOAL_THEN `lowdigits Zf (l - 1) = bignum_from_memory (z,l-1) s'` SUBST1_TAC THENL
         [FIRST_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `bignum_from_memory (z,k) s'`
            then MP_TAC th else NO_TAC) THEN
          DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
          AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN UNDISCH_TAC `l - 1 < k` THEN ARITH_TAC;
          FIRST_ASSUM ACCEPT_TAC];
        FIRST_ASSUM(fun th -> if concl th = `2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 = Zf`
          then MP_TAC th else NO_TAC) THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN
        SUBGOAL_THEN `(l - 1) + 2 = l + 1` SUBST1_TAC THENL
         [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
        MATCH_MP_TAC ZF_BOUND_GROW THEN ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]];
      ALL_TAC] THEN
    REWRITE_TAC[WORD_VAL] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    (* m-preservation *)
    FIRST_X_ASSUM(fun th -> if can (term_match [] `(f:armstate->armstate->bool) s s'`) (concl th)
      then LABEL_TAC "frame" th else NO_TAC) THEN
    MP_TAC(REWRITE_RULE[SOME_FLAGS]
      (ISPECL [`m:int64`; `k:num`; `z:int64`; `k:num`] MAINLOOP_FRAME_PRESERVES_X_MF)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "frame" (MP_TAC o MATCH_MP th)) THEN ASM_REWRITE_TAC[]]);;


(* ======== inlined: block_ddk_304_win.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_BLOCK_DDK_304_WIN -- the SATURATED (DDK) main-loop block.
   ----------------------------------------------------------------------------
   One full main-loop iteration (pc+0x1a4 -> pc+0x304) in the DDK regime, where the
   output length saturates: l = k+1 (so l-1 = k), and the top quotient/remainder word
   spills into register X23' rather than a new z-word.  This is the saturated analog
   of BIGNUM_MOD_BLOCK_B_GROW_304_WIN (growing regime).

   Structure (all seams validated interactively, cont23q-cc):
     setup: DDK_QHAT_LT (q<2^64) + SOME_FLAGS
     ENSURES_SEQUENCE 0x2e8 (=ddk_mid) + CONJ ->
       [ seg-AB : ENSURES_SEQUENCE 0x23c (=segAB_mid) + CONJ ->
                    [ seg-A : BIGNUM_MOD_PREFIX_DDGE1 (entry X15 = RAW window h)
                    ; seg-B : BIGNUM_MOD_TAIL_DDK_WIDE_LOG_X + ENSURES_SUBLEMMA + value bridge ]
       ; seg-C : BIGNUM_MOD_DDK_SEGC (state-referenced 0x2e8->0x304) ]

   The seg-B post-impl value bridge (the mathematical heart):
     - zc = bignum(z,k)@0x23c is the NEW z memory (inner loop stores z[0..k-1]);
       zc != zpre (orig incoming) -- so we use the SEPARATE-zorig/ZK lemmas throughout.
     - R<2^(p+2)          via DDK_R_LT           (standalone; avoids REAL_ARITH blowup)
     - no-borrow + t10<8  via DDK_NOBORROW_THREADED_GEN  (ZK=zc, zorig=zpre separated)
     - X23' funnel        via DDK_TOP_FUNNEL
     - cong + tight bound via DDK_VALUE_CLOSE
     - X13/X14 digits     via TAIL_LOGIN_TO_ZPRE_SAT (dd=k) + DDK_LOGDIGIT_FINALIZE_NC

   Deps (all in the RELOAD chain, all proven, 0 cheat, 0 axiom):
     DDK_QHAT_LT, BIGNUM_MOD_PREFIX_DDGE1, BIGNUM_MOD_DDK_SEGC, BIGNUM_MOD_TAIL_DDK_WIDE_LOG_X,
     DDK_R_LT, DDK_NOBORROW_THREADED_GEN, TAIL_CARRY_EQ_Q, DDK_TOP_FUNNEL, DDK_VALUE_CLOSE,
     TAIL_LOGIN_TO_ZPRE_SAT, BIGDIGIT_TOP_SAT, VAL_LT_TOP.
   ============================================================================ *)

(* --- DDK_LOGDIGIT_FINALIZE_NC: DDK_LOGDIGIT_FINALIZE without the (spurious, never used in the
   proof) `k = pcode ==> hfin = Ztp` conditional.  In the DDK block hfin := val hfw, and when
   k = pcode the tail leaves hfw = word 0 (so val hfw = 0 != Ztp) -- that conditional is not
   dischargeable there but is also never needed, so we drop it.  Same proof script as the
   original DDK_LOGDIGIT_FINALIZE (ddk_logdigit_finalize.ml).  Deps: BIGDIGIT_TOP_SAT, VAL_LT_TOP,
   BIGDIGIT_AGREE_BELOW. *)
let DDK_LOGDIGIT_FINALIZE_NC = prove
 (`!Ztp zpre k pcode lfin hfin.
    Ztp < 2 EXP 64 /\ zpre < 2 EXP (64 * k) /\ 1 <= pcode /\ pcode <= k + 1 /\
    (pcode <= k ==> lfin = bigdigit zpre (pcode - 1)) /\
    (pcode < k ==> hfin = bigdigit zpre pcode) /\
    (k + 1 = pcode ==> hfin = 0)
    ==> (if k = pcode then word Ztp:int64 else word hfin) =
        word (bigdigit (2 EXP (64 * k) * Ztp + zpre) pcode) /\
        (if k + 1 = pcode then word Ztp:int64
         else if pcode <= k + 1 then (if k < pcode then word Ztp else word lfin)
              else word 0) =
        word (bigdigit (2 EXP (64 * k) * Ztp + zpre) (pcode - 1))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `bigdigit (2 EXP (64 * k) * Ztp + zpre) k = Ztp` ASSUME_TAC THENL
   [MATCH_MP_TAC BIGDIGIT_TOP_SAT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!j. j < k ==> bigdigit (2 EXP (64 * k) * Ztp + zpre) j = bigdigit zpre j` ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC BIGDIGIT_AGREE_BELOW THEN EXISTS_TAC `k:num` THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[lowdigits] THEN
    SUBGOAL_THEN `(2 EXP (64 * k) * Ztp + zpre) MOD 2 EXP (64 * k) = zpre MOD 2 EXP (64 * k)`
      SUBST1_TAC THENL [REWRITE_TAC[MOD_MULT_ADD]; ALL_TAC] THEN
    ASM_SIMP_TAC[MOD_LT];
    ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit (2 EXP (64 * k) * Ztp + zpre) (k + 1) = 0` ASSUME_TAC THENL
   [REWRITE_TAC[bigdigit] THEN
    SUBGOAL_THEN `(2 EXP (64 * k) * Ztp + zpre) DIV 2 EXP (64 * (k + 1)) = 0`
      (fun th -> REWRITE_TAC[th; MULT_CLAUSES; ADD_CLAUSES; DIV_0; MOD_0]) THEN
    MATCH_MP_TAC DIV_LT THEN
    REWRITE_TAC[ARITH_RULE `64 * (k + 1) = 64 * k + 64`; EXP_ADD] THEN
    MATCH_MP_TAC VAL_LT_TOP THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  CONJ_TAC THENL
   [COND_CASES_TAC THENL
     [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
      FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
      ASM_CASES_TAC `k + 1 = pcode` THENL
       [SUBGOAL_THEN `hfin = 0` SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
        FIRST_X_ASSUM(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN `pcode < k` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
        ASM_SIMP_TAC[] THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
        FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC]];
    ASM_CASES_TAC `k + 1 = pcode` THENL
     [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN
      SUBGOAL_THEN `pcode - 1 = k` SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
      CONV_TAC SYM_CONV THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `pcode <= k + 1 /\ ~(k < pcode)` STRIP_ASSUME_TAC THENL
       [ASM_ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN
      SUBGOAL_THEN `lfin = bigdigit zpre (pcode - 1)` SUBST1_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
      CONV_TAC SYM_CONV THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC]]);;

(* --- midpoint predicates (0x23c = segAB_mid, 0x2e8 = ddk_mid), built by FILTERING the
   aligned_bytes_loaded/read-PC conjuncts out of the reference lemmas' pre/post so
   ENSURES_SEQUENCE_TAC (which re-prepends them) sees a clean state assertion. *)
let h_raw = `((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64`;;

let ddk_mid =
  let segc_pre = el 1 (snd(strip_comb(snd(dest_imp(concl(ISPECL
    [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;`X17v:num`]
    BIGNUM_MOD_DDK_SEGC_JJ)))))) in
  let sv,body = dest_abs segc_pre in
  let keep c = not(is_comb c && fst(strip_comb c)=`aligned_bytes_loaded`) && not(is_eq c && lhs c=`read PC s`) in
  mk_abs(sv, list_mk_conj(filter keep (conjuncts body)));;

let segc_ens = UNDISCH(REWRITE_RULE[SOME_FLAGS](ISPECL
     [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;`X17v:num`]
     BIGNUM_MOD_DDK_SEGC_JJ));;

let segAB_mid =
  let pp = el 2 (snd(strip_comb(snd(dest_imp(concl(ISPECL
    [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
     h_raw; `k + 1`; `Ztin:num`; `zpre:num`; `X17v:num`; `lfv:num`; `hfv:num`] BIGNUM_MOD_PREFIX_DDGE1)))))) in
  let sv,body = dest_abs pp in
  let keep c = not(is_comb c && fst(strip_comb c)=`aligned_bytes_loaded`) && not(is_eq c && lhs c=`read PC s`) in
  (REWRITE_CONV[ARITH_RULE `(k + 1) - 1 = k`] (mk_abs(sv, list_mk_conj(filter keep (conjuncts body)))) |> concl |> rand);;

let BIGNUM_MOD_BLOCK_DDK_304_WIN = prove
 (`!k z m x n a b pc p ii w d Ztin zpre X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ k + 1 <= (X17v + 63) DIV 64 /\
     zpre < 2 EXP (64 * k) /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Ztin + zpre == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Ztin + zpre < b * 2 EXP 64 /\
     2 EXP (64 * k) * Ztin + zpre < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Ztin + zpre /\
     nonoverlapping (word pc,0x438) (z,8 * k) /\ nonoverlapping (word pc,0x438) (m,8 * k) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word (k + 1) /\ read X12 s = word (p DIV 64 + 1) /\ read X23 s = word Ztin /\
           read X15 s = word (((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zpre)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\
           read X17 s = word (X17v + 61) /\ read X19 s = word (k + 1) /\ read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * (k + 1)) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  (* ==== scaffold + prefix + seg-B setup + funnel (was the OCaml tactic SEGB_PREFIX) ==== *)
  (* NB: strip conjuncts with CONJUNCTS_THEN ASSUME_TAC (NOT STRIP_TAC) so the roundup
     disjunction (d=t0+1 \/ ...) stays a single bundled hyp -- STRIP_TAC would DISJ_CASES it
     and double the whole block proof. *)
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  (* recip-of-t0 LOWER bracket (real form) from recip-of-d LOWER (t0<=d), for DDK_QHAT_LT. *)
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
    ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`2 EXP (64 * k) * Ztin + zpre`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2e8` ddk_mid THEN CONJ_TAC THENL
   [ENSURES_SEQUENCE_TAC `pc + 0x23c` segAB_mid THEN CONJ_TAC THENL
     [MP_TAC(REWRITE_RULE[SOME_FLAGS](ISPECL
        [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
         h_raw; `k + 1`; `Ztin:num`; `zpre:num`; `X17v:num`; `lfv:num`; `hfv:num`] BIGNUM_MOD_PREFIX_DDGE1)) THEN
      REWRITE_TAC[ARITH_RULE `(k + 1) - 1 = k`] THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REPEAT CONJ_TAC THEN
        TRY(FIRST_ASSUM ACCEPT_TAC) THEN (UNDISCH_TAC `1 <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC];
    MP_TAC segc_ens THEN MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] ENSURES_PRECONDITION_THM) THEN
    GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]] THEN
  GHOST_INTRO_TAC `hiw:int64` `read X5` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read X22` THEN
  GHOST_INTRO_TAC `lfw:int64` `read X13` THEN
  GHOST_INTRO_TAC `hfw:int64` `read X14` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(ISPECL
    [`k:num`;
     `((w * ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
       ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64) MOD 2 EXP 64`;
     `val(hiw:int64)`; `val(cwinw:int64)`; `Ztin:num`; `b:num`; `zc:num`; `m:int64`; `z:int64`;
     `pc:num`; `X17v:num`; `p DIV 64 + 1`; `val(lfw:int64)`; `val(hfw:int64)`;
     `x:int64`; `n:num`; `a:num`;
     `word n:int64`; `x:int64`; `word (61 * ii):int64`; `word p:int64`; `word w:int64`]
    BIGNUM_MOD_TAIL_DDK_WIDE_LOG_X) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    (UNDISCH_TAC `1 <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN UNDISCH_TAC `p < 2 EXP 64` THEN
     UNDISCH_TAC `k + 1 <= (X17v + 63) DIV 64` THEN UNDISCH_TAC `X17v + 124 < 2 EXP 64` THEN ARITH_TAC);
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL];
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `bignum_from_memory (z,k) s`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
  ABBREV_TAC `h = ((2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p) MOD 2 EXP 64` THEN
  ABBREV_TAC `q = (w * h) DIV 2 EXP 64 + h` THEN
  SUBGOAL_THEN `lowdigits b k = b /\ lowdigits zpre k = zpre /\ q MOD 2 EXP 64 = q` STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC LOWDIGITS_SELF THEN ASM_REWRITE_TAC[];
      MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME `q MOD 2 EXP 64 = q`; ASSUME `lowdigits b k = b`;
                              ASSUME `lowdigits zpre k = zpre`]) THEN
  SUBGOAL_THEN `(2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p < 2 EXP 64` ASSUME_TAC THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
    ONCE_REWRITE_TAC[MULT_SYM] THEN REWRITE_TAC[GSYM MULT_ASSOC; LE_MULT_LCANCEL] THEN
    DISJ2_TAC THEN ASM_SIMP_TAC[LT_IMP_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `h = (2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p` ASSUME_TAC THENL
   [EXPAND_TAC "h" THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `zr = (2 EXP (64 * k) * Ztin + zpre) MOD 2 EXP p` THEN
  SUBGOAL_THEN `2 EXP (64 * k) * Ztin + zpre = h * 2 EXP p + zr /\ zr < 2 EXP p` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXPAND_TAC "zr" THEN
    MP_TAC(SPECL [`2 EXP (64 * k) * Ztin + zpre`; `2 EXP p`] DIVISION) THEN
    REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `p <= 64 * k` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (p-1) < 2 EXP (64*k)` MP_TAC THENL
     [TRANS_TAC LET_TRANS `b:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[LT_EXP; ARITH_EQ] THEN UNDISCH_TAC `1 <= p` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(b = 0)` ASSUME_TAC THENL
   [UNDISCH_TAC `2 EXP (p - 1) <= b` THEN
    MP_TAC(SPECL [`2`; `p - 1`] EXP_EQ_0) THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `h < 2 EXP 64` ASSUME_TAC THENL
   [EXPAND_TAC "h" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN `(2 EXP (64 * k) * Ztin + zpre) - q * b < 2 EXP (p + 2)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`b:num`; `p:num`; `d:num`; `2 EXP (64 * k) * Ztin + zpre`;
                  `h:num`; `q:num`; `w:num`; `zr:num`] DDK_R_LT_D) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN TRY(ASM_REWRITE_TAC[] THEN NO_TAC) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`Ztin:num`; `zpre:num`; `zc:num`; `b:num`; `q:num`; `val(hiw:int64)`;
                 `val(cwinw:int64)`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `k:num`; `p:num`]
                DDK_NOBORROW_THREADED_GEN) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
      MP_TAC(ISPEC `cwinw:int64` VAL_BOUND) THEN REWRITE_TAC[DIMINDEX_64] THEN ARITH_TAC;
      FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC; FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `2 EXP 64 * q + ((Ztin + val(hiw:int64)) - q) = Ztin + val(hiw:int64) + q * (2 EXP 64 - 1)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`Ztin:num`; `val(hiw:int64)`; `q:num`] TAIL_CARRY_EQ_Q) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `(Ztin + val(hiw:int64)) - q < 8` THEN ARITH_TAC; ALL_TAC] THEN
    STRIP_TAC THEN
    MP_TAC(SPECL [`Ztin + val(hiw:int64) + q * (2 EXP 64 - 1)`; `2 EXP 64`] DIVISION) THEN
    REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
    FIRST_X_ASSUM(fun th -> if lhs(concl th) = `(Ztin + val(hiw:int64) + q * (2 EXP 64 - 1)) DIV 2 EXP 64`
       then REWRITE_TAC[th] else NO_TAC) THEN
    FIRST_X_ASSUM(fun th -> if lhs(concl th) = `(Ztin + val(hiw:int64) + q * (2 EXP 64 - 1)) MOD 2 EXP 64`
       then REWRITE_TAC[th] else NO_TAC) THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `read X23 s' = word (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8):int64`
   ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `read X23 s'` then MP_TAC th else NO_TAC) THEN
    MP_TAC(ISPECL [`q:num`; `(Ztin + val(hiw:int64)) - q`; `val(cwinw:int64)`; `Ztin:num`; `val(hiw:int64)`]
                  DDK_TOP_FUNNEL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[VAL_BOUND_64] THEN UNDISCH_TAC `(Ztin + val(hiw:int64)) - q < 8` THEN ARITH_TAC;
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `val(read X23 s':int64) = 2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8`
   ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th =
       `read X23 s' = word (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8):int64`
      then REWRITE_TAC[th] else NO_TAC) THEN
    MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    MP_TAC(ISPEC `cwinw:int64` VAL_BOUND) THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `(Ztin + val(hiw:int64)) - q < 8` THEN ARITH_TAC; ALL_TAC] THEN
  (* ==== cong + tight bound via DDK_VALUE_CLOSE_D (recip-of-d, cont108) ==== *)
  MP_TAC(ISPECL
   [`a:num`; `b:num`; `ii:num`; `p:num`; `d:num`;
    `w:num`; `h:num`; `zr:num`; `q:num`; `val(hiw:int64)`; `val(cwinw:int64)`; `Ztin:num`;
    `zpre:num`; `zc:num`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `(Ztin + val(hiw:int64)) - q`; `k:num`]
   DDK_VALUE_CLOSE_D) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC) THEN
    TRY REFL_TAC THEN
    TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]) THEN
    TRY(FIRST_ASSUM(fun th -> if concl th = `h = (2 EXP (64 * k) * Ztin + zpre) DIV 2 EXP p`
          then REWRITE_TAC[th] THEN FIRST_ASSUM ACCEPT_TAC else NO_TAC)) THEN
    TRY(UNDISCH_TAC `(Ztin + val(hiw:int64)) - q < 8` THEN ARITH_TAC) THEN
    ALL_TAC;
    ALL_TAC] THEN
  (* relate V = zc + 2^(64k)*(2^61*t10+cwin DIV8) to the goal's 2^(64k)*val(X23 s')+bignum(z,k)s' *)
  SUBGOAL_THEN
   `zc + 2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8) =
    2 EXP (64 * k) * val(read X23 s':int64) + bignum_from_memory (z,k) s'`
   (fun th -> REWRITE_TAC[th]) THENL
   [FIRST_ASSUM(fun th -> if concl th = `val(read X23 s':int64) =
        2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8`
      then REWRITE_TAC[th] else NO_TAC) THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s' = zc`
      then REWRITE_TAC[th] else NO_TAC) THEN ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  (* jj-bound: Vclose < 2^(X17v+61) via DDK_VALUE_JJ (from R1 additive relation + R2 carry).
     State in the GOAL's term order (2^(64k)*(...) + zc, NOT zc + ...) so the final digit-finalize
     ASM_REWRITE closes the ddk_mid jj-conjunct by this assumption directly. *)
  SUBGOAL_THEN
   `2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8) + zc
      < 2 EXP (X17v + 61)`
   ASSUME_TAC THENL
   [SUBGOAL_THEN
     `2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8) + zc =
      zc + 2 EXP (64 * k) * (2 EXP 61 * ((Ztin + val(hiw:int64)) - q) + val(cwinw:int64) DIV 8)`
     (fun th -> REWRITE_TAC[th]) THENL [ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`Ztin:num`; `zpre:num`; `zc:num`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
                   `q:num`; `val(hiw:int64)`; `val(cwinw:int64)`; `(Ztin + val(hiw:int64)) - q`;
                   `b:num`; `k:num`; `X17v:num`] DDK_VALUE_JJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; REWRITE_TAC[]]; ALL_TAC] THEN
  (* ==== X13'/X14' digit-finalize (cont23cc) ==== *)
  (* entry logging -> lfw/hfw = bigdigit zc via the dd=k saturated variant *)
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`; `s:armstate`]
        TAIL_LOGIN_TO_ZPRE_SAT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`]; ALL_TAC] THEN
  STRIP_TAC THEN
  (* pcode = p DIV 64 + 1 <= k + 1 *)
  SUBGOAL_THEN `p DIV 64 + 1 <= k + 1` ASSUME_TAC THENL
   [REWRITE_TAC[LE_ADD_RCANCEL] THEN
    TRANS_TAC LE_TRANS `(64 * k) DIV 64` THEN CONJ_TAC THENL
     [MATCH_MP_TAC DIV_MONO THEN ASM_REWRITE_TAC[ARITH_EQ];
      SIMP_TAC[DIV_MULT; ARITH_EQ] THEN REWRITE_TAC[LE_REFL]]; ALL_TAC] THEN
  (* the tail's word_subword funnel = word(val(X23 s')) : lets X13'/X14' match the finalize LHS *)
  SUBGOAL_THEN
   `word_subword (word_join (word (Ztin + val(hiw:int64) + q * (2 EXP 64 - 1)):int64)
      (word (val(cwinw:int64)):int64):int128) (3,64):int64 = word (val(read X23 s':int64))`
   ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `read X23 s':int64` &&
        (let r = rand(concl th) in is_comb r && fst(strip_comb r) = `word_subword:(128)word->num#num->int64`)
      then GEN_REWRITE_TAC LAND_CONV [SYM th] else NO_TAC) THEN
    CONV_TAC SYM_CONV THEN REWRITE_TAC[WORD_VAL]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ASSUME
   `word_subword (word_join (word (Ztin + val(hiw:int64) + q * (2 EXP 64 - 1)):int64)
      (word (val(cwinw:int64)):int64):int128) (3,64):int64 = word (val(read X23 s':int64))`]) THEN
  (* the 3 val-form logging conditionals DDK_LOGDIGIT_FINALIZE_NC consumes *)
  SUBGOAL_THEN
   `(p DIV 64 + 1 <= k ==> val(lfw:int64) = bigdigit zc ((p DIV 64 + 1) - 1)) /\
    (p DIV 64 + 1 < k ==> val(hfw:int64) = bigdigit zc (p DIV 64 + 1)) /\
    (k + 1 = p DIV 64 + 1 ==> val(hfw:int64) = 0)`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [DISCH_TAC THEN
      FIRST_X_ASSUM(fun th -> if concl th = `p DIV 64 + 1 <= k ==> lfw = word (bigdigit zc ((p DIV 64 + 1) - 1)):int64`
        then MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND];
      DISCH_TAC THEN
      FIRST_X_ASSUM(fun th -> if concl th = `p DIV 64 + 1 < k ==> hfw = word (bigdigit zc (p DIV 64 + 1)):int64`
        then MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64; BIGDIGIT_BOUND];
      DISCH_TAC THEN
      FIRST_X_ASSUM(fun th -> if concl th = `~(p DIV 64 + 1 < k) ==> hfw = word 0:int64`
        then MP_TAC th else NO_TAC) THEN
      ANTS_TAC THENL [UNDISCH_TAC `k + 1 = p DIV 64 + 1` THEN ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th; VAL_WORD_0])];
    ALL_TAC] THEN
  (* apply the finalize: Ztp:=val(X23 s'), zpre:=zc, pcode:=p DIV64+1, lfin:=val lfw, hfin:=val hfw.
     Discharge the finalize's 4 side-conds + 3 logging conditionals (ALL now in asl) via ASM_REWRITE
     so its conclusion B (the two X13'/X14' digit equalities) lands as an antecedent; then DISCH it
     into the assumptions and ASM_REWRITE closes the goal C (= B, reordered).  Robust to whether the
     3 conditionals are auto-discharged by ASM_REWRITE (leaving B==>C) or not (leaving (A==>B)==>C):
     ASM_REWRITE handles the A-discharge either way, DISCH_THEN + ASM_REWRITE finishes. *)
  MP_TAC(ISPECL [`val(read X23 s':int64)`; `zc:num`; `k:num`; `p DIV 64 + 1`;
                 `val(lfw:int64)`; `val(hfw:int64)`] DDK_LOGDIGIT_FINALIZE_NC) THEN
  ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`; VAL_BOUND_64] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;

