(* ======== inlined: block_c_304_win.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_BLOCK_C_304_WIN -- the C-regime (l=k, dd=k-1) main-loop block, 0x1a4->0x304.
   ----------------------------------------------------------------------------
   C is the TRANSITION between growing-B (l<k, X23'=0) and saturated-DDK (l=k+1, z untouched).
   At l=k: entry X23=0, window X15=0 -> qhat=0, hi=0 (growing entry, like B).  The tail
   (TAIL_DDLT_C_WIDE_LOG_X, dd+1=k) writes the top MEMORY word z[k-1] AND spills the carry into
   X23'.  So the new full value Zf' = 2^61*zv + block lives split across bignum(z,k) (its low k
   words) and X23' (its top digit): Zf' = 2^(64k)*val(X23') + bignum(z,k).

   Structure:  setup (Zt=0, zv<2^p, Zf'<2^(64(k+1)))
     -> ENSURES_SEQUENCE 0x2e8 [C midpoint: X23=word(bigdigit Zf' k), z=lowdigits Zf' k, X13/X14 digits]
        -> CONJ [ seg-AB ; seg-C ]
     seg-C : BIGNUM_MOD_FIELDSEL_CLOSE_SAT (general X23'=word Ztp) + CBLK_SPLIT + GROWING_VALUE_CLOSE_TIGHT
             + ENSURES_POSTCONDITION (SAT post preserves more regs than the C block post)
     seg-AB: ENSURES_SEQUENCE 0x23c [prefix midpoint] -> CONJ [ seg-A (PREFIX_DDGE1) ; seg-B ]
     seg-B : TAIL_DDLT_C_WIDE_LOG_X + ENSURES_SUBLEMMA + value bridge:
             val hiw=0 (HI_ZERO); bigdigit zpre(k-1)=bigdigit zv(k-1); full-value identity
             2^(64k)*val(X23')+bignum(z,k)s'=Zf' (C_ZK_FROM_STORES); CBLK_UNIQ split ->
             val(X23')=bigdigit Zf' k, bignum(z,k)s'=lowdigits Zf' k; X23' digit; funnel=bigdigit Zf'(k-1);
             X13/X14 digit-finalize (LOGDIGIT_FINALIZE_BRIDGE dd:=k-1 + TAIL_LOGIN_TO_ZPRE).

   NB: relies on TAIL_DDLT_C_WIDE_LOG(_X) carrying the z-preservation (bignum(z,dd)s=lowdigits zpre dd)
   and X0/X1/X4/X12/bignum(m,k) preservation clauses -- added to tail_ddlt_wide.ml (2026-07-30) to match
   the B-tail; the C-block requires them for the value assembly + register matching.

   Deps: CBLK_SPLIT/C_ZK_FROM_STORES/CBLK_UNIQ (below); INV2_TOP_ZERO, WINDOW_ZERO_IMP_LT, ZF_BOUND_GROW,
   BIGNUM_MOD_FIELDSEL_CLOSE_SAT, GROWING_VALUE_CLOSE_TIGHT, BIGNUM_MOD_PREFIX_DDGE1,
   TAIL_DDLT_C_WIDE_LOG_X, HI_ZERO, LOWDIGITS_BOUND, VALUE_GROW_STEP, EXTR_FUNNEL_VAL,
   TAIL_LOGIN_TO_ZPRE, LOGDIGIT_FINALIZE_BRIDGE, STORE_IS_BIGDIGIT, BIGDIGIT_LOWDIGITS.
   ============================================================================ *)

(* CBLK_SPLIT: top-word split.  2^(64k)*bigdigit Zf k + lowdigits Zf k = Zf (Zf<2^(64(k+1))). *)
let CBLK_SPLIT = prove
 (`!Zf k. Zf < 2 EXP (64 * (k + 1))
    ==> 2 EXP (64 * k) * bigdigit Zf k + lowdigits Zf k = Zf`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `highdigits Zf k < 2 EXP 64` ASSUME_TAC THENL
   [REWRITE_TAC[highdigits] THEN SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
    UNDISCH_TAC `Zf < 2 EXP (64 * (k + 1))` THEN
    REWRITE_TAC[GSYM EXP_ADD; ARITH_RULE `64 * (k + 1) = 64 * k + 64`] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `bigdigit Zf k = highdigits Zf k` SUBST1_TAC THENL
   [REWRITE_TAC[bigdigit; GSYM highdigits] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`Zf:num`; `k:num`] (CONJUNCT1 HIGH_LOW_DIGITS)) THEN ARITH_TAC]);;

(* CBLK_UNIQ: digit-uniqueness for splitting the full value into (X23', bignum(z,k)). *)
let CBLK_UNIQ = prove
 (`!M A B C D. 0 < M /\ M * A + B = M * C + D /\ B < M /\ D < M ==> A = C /\ B = D`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(M * A + B) DIV M = A /\ (M * A + B) MOD M = B` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC DIVMOD_UNIQ THEN CONJ_TAC THENL
     [REWRITE_TAC[MULT_AC]; FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `(M * C + D) DIV M = C /\ (M * C + D) MOD M = D` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC DIVMOD_UNIQ THEN CONJ_TAC THENL
     [REWRITE_TAC[MULT_AC]; FIRST_ASSUM ACCEPT_TAC]; ALL_TAC] THEN
  CONJ_TAC THEN ASM_MESON_TAC[]);;

(* C_ZK_FROM_STORES: the C-regime value assembly -- top word spills into Xtop (=val X23'). *)
let C_ZK_FROM_STORES = prove
 (`!z k zpre zv b block cwinw W Xtop s.
    2 <= k /\ zv < 2 EXP (64 * k) /\ block < 2 EXP 61 /\ cwinw < 2 EXP 64 /\
    lowdigits zpre (k-1) + 2 EXP (64 * (k-1)) * (cwinw DIV 8 + 2 EXP 61 * 0) +
      2 EXP 61 * (0 * lowdigits b (k-1)) =
      block + 2 EXP 61 * lowdigits zv (k-1) + 2 EXP 61 * (0 * 2 EXP (64 * (k-1))) /\
    2 EXP 64 * 0 + W = bigdigit zv (k-1) + 0 + 0 * (2 EXP 64 - 1 - bigdigit b (k-1)) /\
    bignum_from_memory (z,k-1) s = lowdigits zpre (k-1) /\
    read (memory :> bytes64 (word_add z (word (8 * (k-1))))) s =
      word_subword (word_join (word W:int64) (word (cwinw):int64):int128) (3,64) /\
    Xtop = val(word_ushr (word W:int64) 3)
    ==> 2 EXP (64 * k) * Xtop + bignum_from_memory (z,k) s = 2 EXP 61 * zv + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `val(word cwinw:int64) = cwinw` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  SUBGOAL_THEN
   `bignum_from_memory (z,k) s =
      bignum_from_memory (z,k-1) s +
      2 EXP (64 * (k-1)) * val(read (memory :> bytes64 (word_add z (word (8 * (k-1))))) s)`
    SUBST1_TAC THENL
   [MP_TAC(ISPECL [`k - 1`; `z:int64`; `s:armstate`] BIGNUM_FROM_MEMORY_STEP) THEN
    SUBGOAL_THEN `(k - 1) + 1 = k` SUBST1_TAC THENL
     [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ARITH_TAC;
    ALL_TAC] THEN
  ASM_REWRITE_TAC[EXTR_FUNNEL_VAL; VAL_WORD_USHR] THEN
  SUBGOAL_THEN `val(word W:int64) = W` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `2 EXP 64 * 0 + W = bigdigit zv (k-1) + 0 + 0 * (2 EXP 64 - 1 - bigdigit b (k-1))` THEN
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[BIGDIGIT_BOUND]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(ISPECL [`k:num`; `k - 1`; `0`; `block:num`; `zv:num`; `b:num`; `cwinw:num`;
                 `0`; `W:num`; `0`; `lowdigits zpre (k-1)`] VALUE_GROW_STEP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[BIGDIGIT_BOUND] THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(k - 1) + 1 = k` SUBST1_TAC THENL [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `lowdigits zv k = zv` SUBST1_TAC THENL
   [REWRITE_TAC[lowdigits] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN ARITH_TAC);;

let BIGNUM_MOD_BLOCK_C_304_WIN = prove
 (`!k z m x n a b pc p ii w Zt zv X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ X17v + 124 < 2 EXP 64 /\
     (X17v + 124) DIV 64 = k + 1 /\
     (2 EXP (64 * k) * Zt + zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Zt + zv < b * 2 EXP 64 /\
     2 EXP (64 * k) * Zt + zv < 2 EXP (64 * k) /\
     2 EXP (64 * k) * Zt + zv < 2 EXP X17v /\
     ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0 /\
     nonoverlapping (word pc,0x438) (z,8 * k) /\
     nonoverlapping (word pc,0x438) (m,8 * k) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word k /\ read X12 s = word (p DIV 64 + 1) /\
           read X23 s = word Zt /\ read X15 s = word 0 /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
