(* ======== inlined: block_flat_304_win.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_BLOCK_FLAT_304_WIN -- the FLAT-regime (dd+1<k, (jj+124)DIV64=dd+1) block.
   ----------------------------------------------------------------------------
   FLAT = the growing-regime variant where the 61-bit shift stays within dd+1 words (p<=64dd+2),
   so the OUTPUT length l_out = l = dd+1 (UNCHANGED, unlike B where l_out=l+1).  Entry like B:
   X23=0, window X15=0 -> qhat=0, hi=0.  The tail (TAIL_FLAT_WIDE_LOG_X) writes ONLY z[dd] (the
   funnel), leaves X23'=word ztin (=0) PRESERVED, preserves z[0..dd-1] and z[dd+1..k-1], and sets
   X8'=X19'=word(dd+1)=word l.  No top-word spill, no X23' change: bignum(z,k)' = 2^61*zv+block
   directly (the full value, since X23'=0), fitting in dd+1<=k words.

   Structure:  setup (Zt=0, zv<2^p, Zf'<2^(64*l)) -> ENSURES_SEQUENCE 0x2e8 (FLAT midpoint: X23=word 0,
     z=2^61*zv+block, X13/X14 digits) -> CONJ [seg-AB ; seg-C].
     seg-C : BIGNUM_MOD_FIELDSEL_CLOSE_WIN_INV2_FLAT (X23'=0; INV2 < 2^(64*l) via ZF_BOUND_FLAT).
     seg-AB: ENSURES_SEQUENCE 0x23c [prefix midpoint] -> CONJ [seg-A (PREFIX_DDGE1) ; seg-B].
     seg-B : TAIL_FLAT_WIDE_LOG_X + ENSURES_SUBLEMMA + value bridge:
             val hiw=0 (HI_ZERO); bigdigit zpre(dd)=bigdigit zv(dd); highdigits zpre(dd+1)=0 (HIGHZ);
             bignum(z,k)'=2^61*zv+block (FLAT_ZK_FROM_STORES); X13/X14 via LOGDIGIT_FINALIZE_BRIDGE.

   Deps: FLAT helper lemmas (block_flat_304_win.wip / inlined below): BIGNUM_MOD_FIELDSEL_CLOSE_WIN_INV2_FLAT,
   FLAT_ZK_FROM_STORES; plus INV2_TOP_ZERO, WINDOW_ZERO_IMP_LT, ZF_BOUND_FLAT, BIGNUM_MOD_PREFIX_DDGE1,
   TAIL_FLAT_WIDE_LOG_X (strengthened z-high/m preservation), HI_ZERO, HIGHZ_VANISH, LOGDIGIT_FINALIZE_BRIDGE,
   TAIL_LOGIN_TO_ZPRE.
   ============================================================================ *)

let BIGNUM_MOD_FIELDSEL_CLOSE_WIN_INV2_FLAT = prove
 (`!p pc k z n x m a b zv block ii l X17v X19v X16v X21v.
    block = (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 /\ zv < 2 EXP p /\ p <= 64 * (l - 1) + 2 /\ 2 <= l /\
    2 EXP (p - 1) <= b /\ 1 <= p /\
    (zv == a DIV 2 EXP (61 * (ii + 1))) (mod b)
    ==> ensures arm
     (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x2e8) /\
          read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
          read X4 s = m /\ read X20 s = word p /\ read X21 s = word X21v /\
          read X16 s = word X16v /\ read X17 s = word X17v /\ read X19 s = word X19v /\
          read X12 s = word (p DIV 64 + 1) /\ read X23 s = word 0 /\
          read X13 s = word (bigdigit (2 EXP 61 * zv + block) ((p DIV 64 + 1) - 1)) /\
          read X14 s = word (bigdigit (2 EXP 61 * zv + block) (p DIV 64 + 1)) /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
          bignum_from_memory (z,k) s = 2 EXP 61 * zv + block)
     (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
          read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
          read X4 s = m /\ read X20 s = word p /\ read X21 s = word X21v /\
          read X16 s = word X16v /\ read X17 s = word X17v /\ read X19 s = word X19v /\
          read X12 s = word (p DIV 64 + 1) /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
          (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
            == a DIV 2 EXP (61 * ii)) (mod b) /\
          2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
          2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * l) /\
          read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                              DIV 2 EXP p) MOD 2 EXP 64))
     (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                 X16; X17; X19; X20; X21; X22; X23; X24] ,,
      MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`p:num`; `bigdigit (2 EXP 61 * zv + block) ((p DIV 64 + 1) - 1)`;
                 `bigdigit (2 EXP 61 * zv + block) (p DIV 64 + 1)`; `pc:num`; `k:num`;
                 `z:int64`; `n:num`; `x:int64`; `m:int64`; `a:num`; `b:num`; `0`;
                 `2 EXP 61 * zv + block`; `X17v:num`; `X19v:num`; `X16v:num`; `X21v:num`]
                BIGNUM_MOD_FIELDSEL_WIDE_X12) THEN
  REWRITE_TAC[BIGDIGIT_BOUND; SOME_FLAGS] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] ENSURES_POSTCONDITION_THM) THEN
  GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[VAL_WORD_0; MULT_CLAUSES; ADD_CLAUSES] THEN
  ASM_SIMP_TAC[WINDOW_FROM_LOGGED_PCODE] THEN
  REWRITE_TAC[CONJ_ASSOC] THEN CONJ_TAC THENL
   [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zv:num`;
                   `2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
                   `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`] GROWING_VALUE_CLOSE_TIGHT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
    SUBGOAL_THEN `64 * l = 64 * ((l - 1) + 1)` SUBST1_TAC THENL
     [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`zv:num`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `p:num`; `l - 1`] ZF_BOUND_FLAT) THEN
    ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]]);;

(* dd+1 <= k (was <k): covers FLAT@k (dd+1=k) too.  At dd+1=k the high segment
   bignum(z@8(dd+1),k-(dd+1)) is the empty range (k-(dd+1)=0) so highdigits zpre(dd+1)=0 is the whole
   tail; the SPLIT-at-(dd+1) step (line ~118) uses (dd+1)+(k-(dd+1))=k which holds for dd+1<=k. *)
let FLAT_ZK_FROM_STORES = prove
 (`!z k zpre zv b block cwinw W dd s.
    dd + 1 <= k /\ zv < 2 EXP (64 * (dd + 1)) /\ block < 2 EXP 61 /\ cwinw < 2 EXP 64 /\
    2 EXP 61 * zv + block < 2 EXP (64 * (dd + 1)) /\
    highdigits zpre (dd + 1) = 0 /\
    lowdigits zpre dd + 2 EXP (64 * dd) * (cwinw DIV 8 + 2 EXP 61 * 0) +
      2 EXP 61 * (0 * lowdigits b dd) =
      block + 2 EXP 61 * lowdigits zv dd + 2 EXP 61 * (0 * 2 EXP (64 * dd)) /\
    2 EXP 64 * 0 + W = bigdigit zv dd + 0 + 0 * (2 EXP 64 - 1 - bigdigit b dd) /\
    bignum_from_memory (z,dd) s = lowdigits zpre dd /\
    bignum_from_memory (word_add z (word (8 * (dd + 1))), k - (dd + 1)) s = highdigits zpre (dd + 1) /\
    read (memory :> bytes64 (word_add z (word (8 * dd)))) s =
      word_subword (word_join (word W:int64) (word (cwinw):int64):int128) (3,64)
    ==> bignum_from_memory (z,k) s = 2 EXP 61 * zv + block`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `val(word cwinw:int64) = cwinw /\ val(word W:int64) = W` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    ASM_REWRITE_TAC[] THEN
    (UNDISCH_TAC `2 EXP 64 * 0 + W = bigdigit zv dd + 0 + 0 * (2 EXP 64 - 1 - bigdigit b dd)` THEN
     REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[BIGDIGIT_BOUND]);
    ALL_TAC] THEN
  MP_TAC(ISPECL [`dd + 1`; `dd:num`; `0`; `block:num`; `zv:num`; `b:num`; `cwinw:num`;
                 `0`; `W:num`; `0`; `lowdigits zpre dd`] VALUE_GROW_STEP) THEN
  ASM_REWRITE_TAC[ARITH_RULE `dd < dd + 1`; BIGDIGIT_BOUND] THEN
  SUBGOAL_THEN `lowdigits zv (dd + 1) = zv` SUBST1_TAC THENL
   [REWRITE_TAC[lowdigits] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN DISCH_TAC THEN
  SUBGOAL_THEN `W DIV 2 EXP 3 = 0` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (64 * (dd + 1)) * (W DIV 2 EXP 3) < 2 EXP (64 * (dd + 1)) * 1` MP_TAC THENL
     [REWRITE_TAC[MULT_CLAUSES] THEN
      TRANS_TAC LET_TRANS `2 EXP 61 * zv + block` THEN CONJ_TAC THENL
       [FIRST_X_ASSUM(fun th -> if is_eq(concl th) &&
           can (find_term (fun t -> t = `W DIV 2 EXP 3`)) (concl th) &&
           can (find_term (fun t -> t = `2 EXP 61 * zv`)) (concl th)
          then MP_TAC th else NO_TAC) THEN ARITH_TAC;
        ASM_REWRITE_TAC[]];
      SIMP_TAC[LT_MULT_LCANCEL; EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `bignum_from_memory (z,k) s = bignum_from_memory (z,dd+1) s` SUBST1_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `dd + 1`; `k - (dd + 1)`; `s:armstate`] BIGNUM_FROM_MEMORY_SPLIT) THEN
    SUBGOAL_THEN `(dd + 1) + (k - (dd + 1)) = k` SUBST1_TAC THENL
     [UNDISCH_TAC `dd + 1 <= k` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES];
    ALL_TAC] THEN
  MP_TAC(ISPECL [`dd:num`; `z:int64`; `s:armstate`] BIGNUM_FROM_MEMORY_STEP) THEN
  DISCH_THEN SUBST1_TAC THEN
  ASM_REWRITE_TAC[EXTR_FUNNEL_VAL] THEN
  UNDISCH_TAC `(lowdigits zpre dd +
               2 EXP (64 * dd) * (2 EXP 61 * W MOD 2 EXP 3 + cwinw DIV 8)) +
               2 EXP (64 * (dd + 1)) * W DIV 2 EXP 3 = block + 2 EXP 61 * zv` THEN
  ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN ARITH_TAC);;

let BIGNUM_MOD_BLOCK_FLAT_304_WIN = prove
 (`!k z m x n a b pc p ii w l Zt zv X17v lfv hfv.
