    (UNDISCH_TAC `2 <= l` THEN UNDISCH_TAC `l <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN
     UNDISCH_TAC `p < 2 EXP 64` THEN
     UNDISCH_TAC `(X17v + 124) DIV 64 = l` THEN ARITH_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN `(l - 1) + 1 = l` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN
  REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL];
    SUBSUMED_MAYCHANGE_TAC;
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `highdigits zpre (l - 1) = highdigits zv (l - 1)` ASSUME_TAC THENL
