      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word l /\ read X12 s = word (p DIV 64 + 1) /\
           read X23 s = word Zt /\ read X15 s = word 0 /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\
           read X17 s = word (X17v + 61) /\ read X19 s = word l /\
           read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * l) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zv:num`; `l:num`] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l <= k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  SUBGOAL_THEN `zv < 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC WINDOW_ZERO_IMP_LT THEN ASM_REWRITE_TAC[] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]; ALL_TAC] THEN
  SUBGOAL_THEN `2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l)` ASSUME_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  (* jj-bound: 2^61*zv+block < 2^(X17v+61) via JJ_STEP (qh=0, zv<2^X17v [Zt=0 folded]) *)
  SUBGOAL_THEN `2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (X17v + 61)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zv:num`; `0`; `b:num`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `X17v:num`] JJ_STEP) THEN
    ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ; MULT_CLAUSES; SUB_0]; ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2e8`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
        read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
        read X16 s = word (61 * ii) /\ read X17 s = word (X17v + 61) /\
        read X19 s = word l /\ read X12 s = word (p DIV 64 + 1) /\
        read X23 s = word 0 /\
        read X13 s = word (bigdigit (2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61)
                                    ((p DIV 64 + 1) - 1)) /\
        read X14 s = word (bigdigit (2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61)
                                    (p DIV 64 + 1)) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
  CONJ_TAC THENL
