(* ======== inlined: block_flatgen_all_304_win.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_BLOCK_FLATGEN_ALL_304_WIN -- the UNIFIED general-qhat FLAT-regime block, 0x1a4->0x304.
   ----------------------------------------------------------------------------
   Covers ALL reachable FLAT iterations (index l STAYS: l->l), 2<=l<=k, ARBITRARY window, ARBITRARY p.
   Value Zf' = 2^61*(zv - qh*b) + block  (qh=(w*h)/2^64+h, h=window) FITS l words (witness Zf'<2^(64*l)).
   Subsumes: original FLAT (window=0, pcode<=l) + block_flat_gen (window=0, pcode>l) + flat-window!=0
   (capflatw oracle: reachable for small b, k>=21).

   = block_bgen_304_win.ml (general qhat, 2<=l) BUT:
     - TAIL = TAIL_FLAT_WIDE_LOG_X (SINGLE store z[l-1], X8->word l, X19->word l), not TAIL_DDLT_B (two stores);
     - exit X19 = word l (unchanged), exit bound < 2^(64*l) (not 2^(64(l+1)));
     - seg-C = FIELDSEL_CLOSE_GROW_GEN with its l-param := l-1 so its `V<2^(64((l-1)+1))` = V<2^(64*l);
     - value bridge = FLAT_ZK_FROM_STORES_GEN (single store, value fits l words) not GROWING_ZK_FROM_STORES_GEN;
     - X13/X14 digit finalize: ASM_CASES `l < p DIV 64 + 1`:
         pcode>l  -> both word 0 (positions >= l beyond Zf', BIGDIGIT_ZERO) [block_flat_gen pattern]
         pcode<=l -> the funnel/logged digits via TAIL_LOGIN_TO_ZPRE + LOGDIGIT_FINALIZE_BRIDGE [BGEN pattern].
   Hyps: window!=0 machinery (recip bracket) present for the general qhat; b<2^(64*l) (from window!=0 => p<64l,
   OR just a hyp -- dispatch supplies).  Deps: cgen_helpers + flat_gen_helpers + block_flat_304_win + block_bgen
   deps.  Load AFTER those.  Post carries X2/X3/X16=word(61*ii)/X20/X21.
   ============================================================================ *)

let BIGNUM_MOD_BLOCK_FLATGEN_ALL_304_WIN = prove
 (`!k z m x n a b pc p ii w d l Zt zv X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= l /\ l <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ b < 2 EXP (64 * l) /\
     p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ X17v + 124 < 2 EXP 64 /\
     (X17v + 124) DIV 64 = l /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Zt + zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Zt + zv < b * 2 EXP 64 /\
     2 EXP (64 * k) * Zt + zv < 2 EXP (64 * l) /\
     2 EXP 61 * (zv - ((w * ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
       ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) * b) +
       (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l) /\
     2 EXP (64 * k) * Zt + zv < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Zt + zv /\
     nonoverlapping (word pc,0x438) (z,8 * k) /\
     nonoverlapping (word pc,0x438) (m,8 * k) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word l /\ read X12 s = word (p DIV 64 + 1) /\
           read X23 s = word Zt /\
           read X15 s = word (((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\
           read X17 s = word (X17v + 61) /\ read X19 s = word l /\
           read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
             == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * l) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                               DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zv:num`; `l:num`] THEN
    ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l <= k` THEN ARITH_TAC; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  (* recip-of-t0 LOWER (real form) from recip-of-d LOWER, for DDK_QHAT_LT / DDK_R_LT. *)
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zv:num`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(zv DIV 2 EXP p) MOD 2 EXP 64 = zv DIV 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]]; ALL_TAC] THEN
  ABBREV_TAC `h = (zv DIV 2 EXP p) MOD 2 EXP 64` THEN
  ABBREV_TAC `qh = (w * h) DIV 2 EXP 64 + h` THEN
  SUBGOAL_THEN `zv = h * 2 EXP p + zv MOD 2 EXP p /\ zv MOD 2 EXP p < 2 EXP p` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`zv:num`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `p <= 64 * k` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (p-1) < 2 EXP (64*k)` MP_TAC THENL
     [TRANS_TAC LET_TRANS `b:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[LT_EXP; ARITH_EQ] THEN UNDISCH_TAC `1 <= p` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `zv - qh * b < 2 EXP (p + 2)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`b:num`; `p:num`; `d:num`; `zv:num`; `h:num`; `qh:num`; `w:num`;
                  `zv MOD 2 EXP p`] DDK_R_LT_D) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
