     [(* cont88 BUG1 fix: use the FOLDED `Zf < 2^(64l)` asm directly (ASM_REWRITE); the .wip's
         EXPAND_TAC "Zf" THEN FIRST_ASSUM ACCEPT_TAC broke the match (asm survives ABBREV folded) *)
      CONJ_TAC THEN MATCH_MP_TAC BIGDIGIT_ZERO THEN
      TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN
      ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
      UNDISCH_TAC `l < p DIV 64 + 1` THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    (* the tail's X13 (pcode>l => word 0) and X14 (=hfw=word 0) must match word 0 *)
    SUBGOAL_THEN `~(l = p DIV 64 + 1) /\ ~(p DIV 64 + 1 <= l) /\ ~(l - 1 = p DIV 64 + 1)` STRIP_ASSUME_TAC THENL
     [REPEAT CONJ_TAC THEN UNDISCH_TAC `l < p DIV 64 + 1` THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[VAL_WORD_0] THEN
    (* m-preservation *)
    FIRST_X_ASSUM(fun th -> if can (term_match [] `(f:armstate->armstate->bool) s s'`) (concl th)
      then LABEL_TAC "frame" th else NO_TAC) THEN
    MP_TAC(REWRITE_RULE[SOME_FLAGS]
      (ISPECL [`m:int64`; `k:num`; `z:int64`; `k:num`] MAINLOOP_FRAME_PRESERVES_X_MF)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "frame" (MP_TAC o MATCH_MP th)) THEN ASM_REWRITE_TAC[VAL_WORD_0];
    (* pcode <= l: rewrite the funnel word_subword(join(word LOW)..)=word(bigdigit Zf(l-1)), then
       direct FLAT finalize (LOGDIGIT_FINALIZE_BRIDGE does NOT fit the FLAT single-store X14 shape). *)
    (* cont88 BUG2 fix: state the store-identity in terms of W (not LOW).  `word W = word LOW`
       is NOT an assumption here (was local to the FLAT_ZK subgoal); using ASSUME would inject an
       undischarged hyp.  The funnel-EXPRESSION store-identity rewritten by ONLY the W abbrev suffices. *)
    SUBGOAL_THEN
     `word_subword (word_join (word W:int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 =
      word (bigdigit Zf (l - 1)):int64`
     ASSUME_TAC THENL
     [FIRST_ASSUM(fun th -> if concl th =
        `word_subword (word_join (word (bigdigit zv (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1))):int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 = word (bigdigit Zf (l - 1)):int64`
       then MP_TAC th else NO_TAC) THEN
      REWRITE_TAC[ASSUME `bigdigit zv (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1)) = W`];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[WORD_VAL] THEN
    SUBGOAL_THEN `p DIV 64 + 1 <= l` ASSUME_TAC THENL
     [UNDISCH_TAC `~(l < p DIV 64 + 1)` THEN ARITH_TAC; ALL_TAC] THEN
    (* m-preservation FIRST (frame is consumed once), then the two digit conjuncts *)
    FIRST_X_ASSUM(fun th -> if can (term_match [] `(f:armstate->armstate->bool) s s'`) (concl th)
      then LABEL_TAC "frame" th else NO_TAC) THEN
    MP_TAC(REWRITE_RULE[SOME_FLAGS]
      (ISPECL [`m:int64`; `k:num`; `z:int64`; `k:num`] MAINLOOP_FRAME_PRESERVES_X_MF)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "frame" (ASSUME_TAC o MATCH_MP th)) THEN
    ASM_REWRITE_TAC[] THEN
    (* X13 (pcode-1 RHS) and X14 (pcode RHS) directly *)
    CONJ_TAC THENL
     [(* X13 *)
      ASM_CASES_TAC `l:num = p DIV 64 + 1` THENL
       [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
        UNDISCH_TAC `l:num = p DIV 64 + 1` THEN ARITH_TAC;
        ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `~(l - 1 < p DIV 64 + 1)` (fun th -> REWRITE_TAC[th]) THENL
         [UNDISCH_TAC `~(l:num = p DIV 64 + 1)` THEN UNDISCH_TAC `p DIV 64 + 1 <= l` THEN
          UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
        (* cont88: matcher literal MUST be type-annotated (lfw:int64, bigdigit(zc:num)) or
           `concl th = <lit>` invents type vars -> never matches -> tryfind *)
        FIRST_X_ASSUM(fun th -> if concl th = `p DIV 64 + 1 <= l - 1 ==> lfw:int64 = word (bigdigit (zc:num) ((p DIV 64 + 1) - 1))`
          then MP_TAC th else NO_TAC) THEN
        ANTS_TAC THENL
         [UNDISCH_TAC `~(l:num = p DIV 64 + 1)` THEN UNDISCH_TAC `p DIV 64 + 1 <= l` THEN
          UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
        DISCH_THEN SUBST1_TAC THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
        MATCH_MP_TAC BIGDIGIT_AGREE_BELOW THEN EXISTS_TAC `l - 1` THEN
        ASM_REWRITE_TAC[] THEN
        UNDISCH_TAC `~(l:num = p DIV 64 + 1)` THEN UNDISCH_TAC `p DIV 64 + 1 <= l` THEN
        UNDISCH_TAC `1 <= p` THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC];
      (* X14.  cont88 BUG3 fix: the .wip claimed hfw=word 0 unconditionally in the l-1<>pcode
         case -- WRONG: X14=hfw there, and hfw=word 0 only when ~(pcode<l-1); the case pcode<l-1
         has hfw = a LOGGED digit (bigdigit zc pcode).  Split on `pcode < l-1`. *)
      ASM_CASES_TAC `l - 1 = p DIV 64 + 1` THENL
       [ASM_REWRITE_TAC[] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
        UNDISCH_TAC `l - 1 = p DIV 64 + 1` THEN ARITH_TAC;
        ASM_REWRITE_TAC[] THEN
        ASM_CASES_TAC `p DIV 64 + 1 < l - 1` THENL
         [(* pcode < l-1: hfw = logged digit bigdigit zc pcode = bigdigit Zf pcode *)
          FIRST_X_ASSUM(fun th -> if concl th = `p DIV 64 + 1 < l - 1 ==> hfw:int64 = word (bigdigit (zc:num) (p DIV 64 + 1))`
             then MP_TAC th else NO_TAC) THEN
          ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN AP_TERM_TAC THEN CONV_TAC SYM_CONV THEN
          MATCH_MP_TAC BIGDIGIT_AGREE_BELOW THEN EXISTS_TAC `l - 1` THEN ASM_REWRITE_TAC[];
          (* ~(pcode < l-1): hfw = word 0, and pcode >= l so bigdigit Zf pcode = 0 *)
          SUBGOAL_THEN `hfw:int64 = word 0` SUBST1_TAC THENL
           [FIRST_X_ASSUM(fun th -> if concl th = `~(p DIV 64 + 1 < l - 1) ==> hfw:int64 = word 0`
               then MATCH_MP_TAC th else NO_TAC) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
          CONV_TAC SYM_CONV THEN AP_TERM_TAC THEN MATCH_MP_TAC BIGDIGIT_ZERO THEN
          TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
          UNDISCH_TAC `~(p DIV 64 + 1 < l - 1)` THEN UNDISCH_TAC `~(l - 1 = p DIV 64 + 1)` THEN
          UNDISCH_TAC `2 <= l` THEN ARITH_TAC]]]]);;

