(* ======== inlined: block_l1k1_304_win.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_BLOCK_L1K1_304_WIN -- the k=1 saturated l=1 variant main-loop block,
   0x1a4->0x304.  This is the l=1 base case (first iteration, dd=0, general window/qhat) at k=1,
   where l = word_min(k+1, (j+63)/64) SATURATES to 2=k+1 on the very first iteration: the single
   new word cannot grow into z[1] (out of bounds), so its top spills into X23'.  Distinct from:
     - l=1-B (block_l1_304_win.ml): 1<k, grows 1->2 into z (X23'=word 0);
     - C-block (block_c_304_win.ml): l=k->k+1 but GROWING entry (window=0/qhat=0 at l=k), 2<=k.
   The k=1 entry is the l=1 GENERAL entry (arbitrary window, qhat=(w*hwin)/2^64+hwin), and the
   tail is the C-SPILL (top word -> X23', low word -> z[0]).

   Structure (mirrors block_l1_304_win.ml, 2 ENSURES_SEQUENCE splits @0x2e8, @0x23c):
     outer 0x2e8 midpoint = SATURATED form (X23'=word(bigdigit Zf 1), z=lowdigits Zf 1,
       X13/X14 = window digits of Zf), Zf = 2^61*(zv-qh*b)+block, block=(a DIV 2^(61 ii)) MOD 2^61.
     seg-A (0x1a4->0x23c): BIGNUM_MOD_L1_PREFIX (k:=1, hwin:=(zv DIV 2^p) MOD 2^64) -- SHARED with l=1-B.
     seg-B (0x23c->0x2e8): BIGNUM_MOD_L1K1_SEGB (below) -- l=1 general entry + C-tail spill.
     seg-C (0x2e8->0x304): BIGNUM_MOD_L1K1_SEGC (below) -- FIELDSEL_CLOSE_SAT at k:=1;
       dispatched with Ztp:=bigdigit Zf 1, zpre:=lowdigits Zf 1, split premise via CBLK_SPLIT.

   Deps: L1_VALUE_BRIDGE_GEN, L1_TAILMUL_DISJ, BIGNUM_MOD_L1_PREFIX, L1_VALUE_CLOSE (block_l1_304_win.ml);
   TAIL_DDLT_C_WIDE_LOG_X (xinvariant_glue.ml); CBLK_SPLIT, CBLK_UNIQ (block_c_304_win.ml);
   BIGNUM_MOD_FIELDSEL_CLOSE_SAT (fieldsel_close_sat.ml); STORE_IS_BIGDIGIT (win_block_helpers.ml);
   LOGDIGIT_FINALIZE_BRIDGE (logdigit_finalize_bridge.ml); DDK_QHAT_LT.
   MUST load AFTER block_l1_304_win.ml and block_c_304_win.ml.
   ============================================================================ *)

(* L1K1_ZK: k=1 value assembly (general qhat q; top spills into X23', low word into z[0]).
   Re-partitions the SAME two funnel terms L1_VALUE_BRIDGE_GEN produces as (2^64*val(X23'), z[0]). *)
let L1K1_ZK = prove
 (`!z zv q b block cwin s.
    q * b <= zv /\ zv < 2 EXP 64 /\ (q = 0 \/ highdigits b 1 = 0) /\
    val(word cwin:int64) DIV 8 = block /\
    read (memory :> bytes64 (word_add z (word (8 * 0)))) s =
      word_subword (word_join (word (bigdigit zv 0 + q + q * (2 EXP 64 - 1 - bigdigit b 0)):int64) (word cwin:int64):int128) (3,64)
    ==> 2 EXP 64 * val(word_ushr (word (bigdigit zv 0 + q + q * (2 EXP 64 - 1 - bigdigit b 0)):int64) 3) +
        bignum_from_memory (z,1) s = 2 EXP 61 * (zv - q * b) + block`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  MP_TAC(ISPECL [`zv:num`; `q:num`; `b:num`; `block:num`; `cwin:num`] L1_VALUE_BRIDGE_GEN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `8 * 0 = 0`; WORD_ADD_0]) THEN
  REWRITE_TAC[BIGNUM_FROM_MEMORY_SING] THEN ASM_REWRITE_TAC[] THEN ARITH_TAC);;

(* BIGNUM_MOD_L1K1_SEGC: the k=1 saturated seg-C, 0x2e8->0x304, via FIELDSEL_CLOSE_SAT at k:=1
   (l:=2).  Takes abstract Ztp/zpre with the reduced split value 2^64*Ztp+zpre = 2^61*(zv-qh*b)+block. *)
let BIGNUM_MOD_L1K1_SEGC = prove
 (`!z m x n a b pc p ii w d zv Ztp zpre X17v.
    2 EXP (p - 1) <= b /\ 1 <= p /\ p < 2 EXP 64 /\ zv < 2 EXP 64 /\ ~(b = 0) /\ b < 2 EXP p /\ b < 2 EXP (64 * 1) /\
    0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
    (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
    d < 2 EXP 64 /\
    (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
     ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
    (2 EXP 64 + w) * d <= 2 EXP 128 /\
    2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
    (zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
    ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b <= zv /\
    2 EXP 64 * Ztp + zpre < 2 EXP (X17v + 61) /\
    2 EXP 64 * Ztp + zpre = 2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61
    ==> ensures arm
     (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x2e8) /\
          read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
          read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
          read X16 s = word (61 * ii) /\ read X17 s = word (X17v + 61) /\
          read X19 s = word 2 /\ read X12 s = word (p DIV 64 + 1) /\ read X23 s = word Ztp /\
          read X13 s = word (bigdigit (2 EXP 64 * Ztp + zpre) ((p DIV 64 + 1) - 1)) /\
          read X14 s = word (bigdigit (2 EXP 64 * Ztp + zpre) (p DIV 64 + 1)) /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
          bignum_from_memory (z,1) s = zpre)
     (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
          read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
          read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
          read X16 s = word (61 * ii) /\
          read X17 s = word (X17v + 61) /\ read X19 s = word 2 /\ read X12 s = word (p DIV 64 + 1) /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
          (2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s == a DIV 2 EXP (61 * ii)) (mod b) /\
          2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s < b * 2 EXP 64 /\
          2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s < 2 EXP (64 * 2) /\
          2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s < 2 EXP (X17v + 61) /\
          read X15 s = word (((2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s) DIV 2 EXP p) MOD 2 EXP 64))
     (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                 X16; X17; X19; X20; X21; X22; X23; X24] ,,
      MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,1)])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `zv = (zv DIV 2 EXP p) MOD 2 EXP 64 * 2 EXP p + zv MOD 2 EXP p` ASSUME_TAC THENL
   [SUBGOAL_THEN `(zv DIV 2 EXP p) MOD 2 EXP 64 = zv DIV 2 EXP p` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN TRANS_TAC LET_TRANS `zv:num` THEN ASM_REWRITE_TAC[DIV_LE];
      MP_TAC(SPECL [`zv:num`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(2 EXP 64 * Ztp + zpre == a DIV 2 EXP (61 * ii)) (mod b) /\ 2 EXP 64 * Ztp + zpre < b * 2 EXP 64`
   STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_eq(concl th) && lhs(concl th) = `2 EXP 64 * Ztp + zpre` then REWRITE_TAC[th] else NO_TAC) THEN
    MP_TAC(ISPECL
      [`a:num`; `b:num`; `ii:num`; `p:num`; `w:num`; `d:num`; `(zv DIV 2 EXP p) MOD 2 EXP 64`; `zv:num`;
       `(w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64`;
       `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
       `2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
       `zv MOD 2 EXP p`; `1`]
      L1_VALUE_CLOSE_D) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
      ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
      REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(REWRITE_RULE[ARITH_RULE `64 * 1 = 64`; ARITH_RULE `64 * (1 + 1) = 64 * 2`; SOME_FLAGS]
   (ISPECL
    [`p:num`;`pc:num`;`1`;`z:int64`;`n:num`;`x:int64`;`m:int64`;`a:num`;`b:num`;
     `Ztp:num`;`zpre:num`;`ii:num`;`2`;`X17v + 61:num`;`2`;`61 * ii:num`;`w:num`] FIELDSEL_CLOSE_SAT_JJ)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `b < 2 EXP (64 * 1)` THEN REWRITE_TAC[ARITH_RULE `64 * 1 = 64`];
    ALL_TAC] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] ENSURES_POSTCONDITION_THM) THEN
  GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[ARITH_RULE `64 * 1 = 64`]);;

(* BIGNUM_MOD_L1K1_SEGB: the k=1 saturated l=1 seg-B, 0x23c->0x2e8.  Entry = l=1-B seg-B pre
   (general qhat qh=(w*hwin)/2^64+hwin, X5=X15=qh, X23=0, X19=1); tail = C-spill (dd=0, k=1). *)
let BIGNUM_MOD_L1K1_SEGB = prove
 (`!z m x n a b pc p ii w zv X17v lfv.
     b < 2 EXP (64 * 1) /\ X17v + 124 < 2 EXP 64 /\ p < 2 EXP 64 /\
     (X17v + 124) DIV 64 = 2 /\ zv < 2 EXP 64 /\ 2 EXP (p - 1) <= b /\ b < 2 EXP p /\ 1 <= p /\
     (w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64 /\
     ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b <= zv /\
     nonoverlapping (word pc,0x438) (z,8 * 1) /\ nonoverlapping (word pc,0x438) (m,8 * 1) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * 1) (m,8 * 1) /\ nonoverlapping (z,8 * 1) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x23c) /\
           read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\ read X17 s = word X17v /\
           read X19 s = word 1 /\ read X12 s = word (p DIV 64 + 1) /\ read X23 s = word 0 /\
           read X15 s = word ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) /\
           read X5 s = word ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) /\
           read X14 s = word 0 /\ read X22 s = word (2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) /\
           read X8 s = word 0 /\ read X11 s = word 0 /\ read X13 s = word lfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
           bignum_from_memory (z,1) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x2e8) /\
           read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\ read X17 s = word (X17v + 61) /\
           read X19 s = word 2 /\ read X12 s = word (p DIV 64 + 1) /\
           read X23 s = word (bigdigit (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) 1) /\
           read X13 s = word (bigdigit (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) ((p DIV 64 + 1) - 1)) /\
           read X14 s = word (bigdigit (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) (p DIV 64 + 1)) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
           bignum_from_memory (z,1) s = lowdigits (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) 1)
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,1)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  MP_TAC(ISPECL
    [`1`;
     `(w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64`;
     `(w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64`;
     `2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `0`;
     `b:num`; `zv:num`; `m:int64`; `z:int64`; `pc:num`; `X17v:num`; `p DIV 64 + 1`; `0`;
     `lfv:num`; `0`; `x:int64`; `n:num`; `a:num`;
     `word n:int64`; `x:int64`; `word (61 * ii):int64`; `word p:int64`; `word w:int64`]
    TAIL_DDLT_C_WIDE_LOG_X) THEN
