   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`z:int64`; `zv:num`; `qh:num`; `b:num`;
                   `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;
                   `2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `s':armstate`] L1K1_ZK) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `val(word (2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61):int64) =
                    2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` SUBST1_TAC THENL
       [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
        MP_TAC(SPECL [`a DIV 2 EXP (61 * ii)`; `61`] MOD_LT_EQ) THEN
