      then SUBST1_TAC(SYM th) else NO_TAC) THEN
    REWRITE_TAC[ARITH_RULE `64 * (1 + 1) = 128`] THEN
    MP_TAC(SPECL [`a DIV 2 EXP (61 * ii)`; `2 EXP 61`] MOD_LT_EQ) THEN
    REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
    UNDISCH_TAC `zv < 2 EXP 64` THEN UNDISCH_TAC `qh * b <= zv` THEN ARITH_TAC;
    ALL_TAC] THEN
