(* BIGNUM_MOD_BLOCK_L1K1_304_WIN: full k=1 saturated l=1 block, 0x1a4->0x304, l:1->2 (saturated). *)
let BIGNUM_MOD_BLOCK_L1K1_304_WIN = prove
 (`!z m x n a b pc p ii w d zv X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\
     b < 2 EXP (64 * 1) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ (X17v + 124) DIV 64 = 2 /\ zv < 2 EXP 64 /\ zv < 2 EXP X17v /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b <= zv /\
     nonoverlapping (word pc,0x438) (z,8 * 1) /\ nonoverlapping (word pc,0x438) (m,8 * 1) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * 1) (m,8 * 1) /\ nonoverlapping (z,8 * 1) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word 1 /\ read X12 s = word (p DIV 64 + 1) /\ read X23 s = word 0 /\
           read X15 s = word ((zv DIV 2 EXP p) MOD 2 EXP 64) /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
           bignum_from_memory (z,1) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\
           read X17 s = word (X17v + 61) /\ read X19 s = word 2 /\ read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
           (2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s < b * 2 EXP 64 /\
           2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s < 2 EXP (64 * 2) /\
           2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s < 2 EXP (X17v + 61) /\
           read X15 s = word (((2 EXP (64 * 1) * val(read X23 s) + bignum_from_memory (z,1) s)
                               DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,1)])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `~(b = 0)` ASSUME_TAC THENL
   [UNDISCH_TAC `2 EXP (p - 1) <= b` THEN MP_TAC(SPECL [`2`; `p - 1`] EXP_EQ_0) THEN ARITH_TAC;
    ALL_TAC] THEN
  (* recip-of-t0 LOWER (real form) from recip-of-d LOWER, for DDK_QHAT_LT. *)
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zv:num`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [TRANS_TAC LTE_TRANS `2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
      GEN_REWRITE_TAC LAND_CONV [ARITH_RULE `2 EXP 64 = 1 * 2 EXP 64`] THEN
      REWRITE_TAC[LE_MULT_RCANCEL] THEN DISJ1_TAC THEN
      TRANS_TAC LE_TRANS `2 EXP (p - 1)` THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ARITH_RULE `1 = 2 EXP 0`; LE_EXP] THEN ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2e8`
   `\s. read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\ read X4 s = m /\
        read X20 s = word p /\ read X21 s = word w /\ read X16 s = word (61 * ii) /\
        read X17 s = word (X17v + 61) /\ read X19 s = word 2 /\ read X12 s = word (p DIV 64 + 1) /\
        read X23 s = word (bigdigit (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) 1) /\
        read X13 s = word (bigdigit (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) ((p DIV 64 + 1) - 1)) /\
        read X14 s = word (bigdigit (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) (p DIV 64 + 1)) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
        bignum_from_memory (z,1) s = lowdigits (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) 1` THEN
  CONJ_TAC THENL
   [ENSURES_SEQUENCE_TAC `pc + 0x23c`
     `\s. read X0 s = word 1 /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\ read X4 s = m /\
          read X20 s = word p /\ read X21 s = word w /\ read X16 s = word (61 * ii) /\
          read X17 s = word X17v /\ read X19 s = word 1 /\ read X12 s = word (p DIV 64 + 1) /\
          read X23 s = word 0 /\
          read X15 s = word ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) /\
          read X5 s = word ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) /\
          read X14 s = word 0 /\ read X22 s = word (2 EXP 3 * (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) /\
          read X8 s = word 0 /\ read X11 s = word 0 /\ read X13 s = word lfv /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,1) s = b /\
          bignum_from_memory (z,1) s = zv` THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`1`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
                     `(zv DIV 2 EXP p) MOD 2 EXP 64`; `zv:num`; `lfv:num`; `hfv:num`; `X17v:num`] BIGNUM_MOD_L1_PREFIX) THEN
      ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ; SOME_FLAGS] THEN DISCH_THEN ACCEPT_TAC;
      MP_TAC(ISPECL [`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;
                     `zv:num`; `X17v:num`; `lfv:num`] BIGNUM_MOD_L1K1_SEGB) THEN
      ASM_REWRITE_TAC[SOME_FLAGS] THEN DISCH_THEN ACCEPT_TAC];
    MP_TAC(ISPECL
      [`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;`p:num`;`ii:num`;`w:num`;`d:num`;`zv:num`;
       `bigdigit (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) 1`;
       `lowdigits (2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) 1`;
       `X17v:num`]
      BIGNUM_MOD_L1K1_SEGC) THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ABBREV_TAC `Zf = 2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
    SUBGOAL_THEN `Zf < 2 EXP (64 * (1 + 1))` ASSUME_TAC THENL
     [EXPAND_TAC "Zf" THEN REWRITE_TAC[ARITH_RULE `64 * (1 + 1) = 128`] THEN
      MP_TAC(SPECL [`a DIV 2 EXP (61 * ii)`; `2 EXP 61`] MOD_LT_EQ) THEN
      REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
      UNDISCH_TAC `zv < 2 EXP 64` THEN
      UNDISCH_TAC `((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b <= zv` THEN
      ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `2 EXP 64 * bigdigit Zf 1 + lowdigits Zf 1 = Zf` ASSUME_TAC THENL
     [MP_TAC(SPECL [`Zf:num`; `1`] CBLK_SPLIT) THEN ASM_REWRITE_TAC[ARITH_RULE `64 * 1 = 64`] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    (* jj-bound: Zf < 2^(X17v+61) via JJ_STEP (zv<2^X17v, qh general).
       NB: EXPAND_TAC "Zf" would pick the WRONG =Zf assumption (the CBLK_SPLIT one,
       2 EXP 64*bigdigit Zf 1+lowdigits Zf 1 = Zf, which still contains Zf); use the
       ABBREV equation explicitly via FIRST_X_ASSUM ... SUBST1_TAC(SYM th) (cont105). *)
    SUBGOAL_THEN `Zf < 2 EXP (X17v + 61)` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th = `2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 = Zf` then SUBST1_TAC(SYM th) else NO_TAC) THEN
      MATCH_MP_TAC JJ_STEP THEN
      ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    REWRITE_TAC[ASSUME `2 EXP 64 * bigdigit Zf 1 + lowdigits Zf 1 = Zf`] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      FIRST_ASSUM(fun th -> if concl th = `2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 = Zf`
        then REWRITE_TAC[th] else NO_TAC);
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

