(* C_TOP_FUNNEL_GEN is now defined in cgen_helpers.ml (loaded before this file). *)

let cgen_qh = `(w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64`;;
let cgen_Zf = `2 EXP 61 * (zv - ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64) * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;;

let BIGNUM_MOD_BLOCK_CGEN_304_WIN = prove
 (`!k z m x n a b pc p ii w d Zt zv X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ X17v + 124 < 2 EXP 64 /\
     (X17v + 124) DIV 64 = k + 1 /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Zt + zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Zt + zv < b * 2 EXP 64 /\
     2 EXP (64 * k) * Zt + zv < 2 EXP (64 * k) /\
     2 EXP (64 * k) * Zt + zv < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Zt + zv /\
     nonoverlapping (word pc,0x438) (z,8 * k) /\
     nonoverlapping (word pc,0x438) (m,8 * k) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word k /\ read X12 s = word (p DIV 64 + 1) /\
           read X23 s = word Zt /\
           read X15 s = word (((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\
           read X17 s = word (X17v + 61) /\ read X19 s = word (k + 1) /\
           read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
             == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (64 * (k + 1)) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                               DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`; `zv:num`; `k:num`] THEN
    ASM_REWRITE_TAC[LE_REFL]; ALL_TAC] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
  (* recip-of-t0 LOWER (real form) from recip-of-d LOWER, for DDK_QHAT_LT / DDK_R_LT. *)
  SUBGOAL_THEN `(&2 pow 64 + &w) * &((b * 2 EXP 64) DIV 2 EXP p) <= &2 pow 128` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2 EXP 64 + w) * ((b * 2 EXP 64) DIV 2 EXP p) <= 2 EXP 128` MP_TAC THENL
     [MATCH_MP_TAC RECIP_T0_FROM_D THEN EXISTS_TAC `d:num` THEN
      ASM_REWRITE_TAC[] THEN MATCH_MP_TAC ROUNDUP_T0_LE THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM REAL_OF_NUM_CLAUSES] THEN REWRITE_TAC[REAL_OF_NUM_POW] THEN
      REAL_ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 + (zv DIV 2 EXP p) MOD 2 EXP 64 < 2 EXP 64`
   ASSUME_TAC THENL
   [MP_TAC(ISPECL [`zv:num`; `b:num`; `p:num`; `w:num`] DDK_QHAT_LT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* window decomposition zv = h*2^p + zr for DDK_R_LT + C_CARRY_IS_Q *)
  SUBGOAL_THEN `(zv DIV 2 EXP p) MOD 2 EXP 64 = zv DIV 2 EXP p` ASSUME_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN CONJ_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]]; ALL_TAC] THEN
  ABBREV_TAC `h = (zv DIV 2 EXP p) MOD 2 EXP 64` THEN
  (* ABBREV rewrote the prior asm into `h = zv DIV 2 EXP p`; keep it available *)
  ABBREV_TAC `qh = (w * h) DIV 2 EXP 64 + h` THEN
  SUBGOAL_THEN `zv = h * 2 EXP p + zv MOD 2 EXP p /\ zv MOD 2 EXP p < 2 EXP p` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`zv:num`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `p <= 64 * k` ASSUME_TAC THENL
   [SUBGOAL_THEN `2 EXP (p-1) < 2 EXP (64*k)` MP_TAC THENL
     [TRANS_TAC LET_TRANS `b:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[LT_EXP; ARITH_EQ] THEN UNDISCH_TAC `1 <= p` THEN ARITH_TAC; ALL_TAC] THEN
  (* reduced remainder R = zv - qh*b < 2^(p+2) via DDK_R_LT *)
  SUBGOAL_THEN `zv - qh * b < 2 EXP (p + 2)` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`b:num`; `p:num`; `d:num`; `zv:num`; `h:num`; `qh:num`; `w:num`;
                  `zv MOD 2 EXP p`] DDK_R_LT_D) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(UNDISCH_TAC `2 EXP (p - 1) <= b` THEN MP_TAC(SPECL [`2`; `p - 1`] EXP_EQ_0) THEN ARITH_TAC) THEN
      (EXPAND_TAC "h" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]);
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x2e8`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
        read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
        read X16 s = word (61 * ii) /\ read X17 s = word (X17v + 61) /\
        read X19 s = word (k + 1) /\ read X12 s = word (p DIV 64 + 1) /\
        read X23 s = word (bigdigit (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) k) /\
        read X13 s = word (bigdigit (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61)
                                    ((p DIV 64 + 1) - 1)) /\
        read X14 s = word (bigdigit (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61)
                                    (p DIV 64 + 1)) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s =
          lowdigits (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) k` THEN
  CONJ_TAC THENL
   [ALL_TAC;
    (* seg-C: 0x2e8 -> 0x304 via FIELDSEL_CLOSE_SAT (general X23').  Pre-establish both
       bounds (< b*2^64 via GROWING_VALUE_CLOSE_GEN CONJUNCT2, then < 2^(64(k+1))) so CBLK_SPLIT
       and the FIELDSEL_CLOSE_SAT ANTS discharge by ASM_REWRITE. *)
    SUBGOAL_THEN `2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < b * 2 EXP 64`
      ASSUME_TAC THENL
     [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zv:num`;
                     `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `qh:num`;
                     `2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`] GROWING_VALUE_CLOSE_GEN) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(ACCEPT_TAC o CONJUNCT2); ALL_TAC] THEN
    SUBGOAL_THEN `2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * (k + 1))`
      ASSUME_TAC THENL
     [TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN CONJ_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        REWRITE_TAC[ARITH_RULE `64 * (k + 1) = 64 * k + 64`; EXP_ADD] THEN
        MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]]; ALL_TAC] THEN
    (* jj-bound: Zf' < 2^(X17v+61) via JJ_STEP (zv<2^X17v incoming, block<2^61) *)
    SUBGOAL_THEN `2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (X17v + 61)`
      ASSUME_TAC THENL
     [MATCH_MP_TAC JJ_STEP THEN ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ]; ALL_TAC] THEN
    MP_TAC(SPECL [`2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `k:num`] CBLK_SPLIT) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`p:num`; `pc:num`; `k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                   `a:num`; `b:num`;
                   `bigdigit (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) k`;
                   `lowdigits (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) k`;
                   `ii:num`; `k:num`; `X17v + 61`; `k + 1`; `61 * ii`; `w:num`]
                  FIELDSEL_CLOSE_SAT_JJ) THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    FIRST_ASSUM(fun th -> if is_eq(concl th) &&
       lhs(concl th) = `2 EXP (64 * k) * bigdigit (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) k +
        lowdigits (2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61) k`
      then REWRITE_TAC[th] else NO_TAC) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THENL
       [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zv:num`;
                       `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `qh:num`;
                       `2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`] GROWING_VALUE_CLOSE_GEN) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT1 th]);
        FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC;
        FIRST_ASSUM ACCEPT_TAC];
      ALL_TAC] THEN
    MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ] ENSURES_POSTCONDITION_THM) THEN
    GEN_TAC THEN REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]] THEN
  (* seg-AB: 0x1a4 -> 0x2e8.  Midpoint VERBATIM matches BIGNUM_MOD_PREFIX_DDGE1's post (l:=k,
     Zt:=0, general h) so seg-A is a pure ACCEPT_TAC; seg-B rewrites ((w*h)DIV2^64+h) MOD 2^64 -> qh
     up front to reach the clean form the helpers expect. *)
  ENSURES_SEQUENCE_TAC `pc + 0x23c`
   `\s. read X8 s = word (k - 1) /\
        read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
        read X11 s = word (k - 1) /\ read X12 s = word (p DIV 64 + 1) /\
        read X15 s = word (((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64) /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (word_add z (word (8 * (k - 1))), k - (k - 1)) s = highdigits zv (k - 1) /\
        (1 <= k - 1 ==> read X13 s =
            read (memory :> bytes64 (word_add z (word (8 * (MIN (k-1) (p DIV 64 + 1) - 1))))) s) /\
        (p DIV 64 + 1 < k - 1 ==> read X14 s =
            read (memory :> bytes64 (word_add z (word (8 * (p DIV 64 + 1))))) s) /\
        (~(p DIV 64 + 1 < k - 1) ==> read X14 s = word 0) /\
        read X2 s = word n /\ read X3 s = x /\ read X16 s = word (61 * ii) /\
        read X17 s = word X17v /\ read X19 s = word k /\ read X20 s = word p /\
        read X21 s = word w /\ read X23 s = word 0 /\
        bignum_from_memory (x,n) s = a /\
        bignum_from_memory (z,k-1) s +
        2 EXP (64 * (k-1)) * (val(read X22 s) DIV 8 + 2 EXP 61 * val(read X5 s)) +
        2 EXP 61 * ((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64 * lowdigits b (k-1) =
        (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 + 2 EXP 61 * lowdigits zv (k-1) +
        2 EXP 61 * ((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64 * 2 EXP (64 * (k-1))` THEN
  CONJ_TAC THENL
   [(* seg-A: fold entry X15 = word(((2^(64k)*0+zv)DIV2^p)MOD2^64) -> word h, then verbatim PREFIX *)
    SUBGOAL_THEN `((2 EXP (64 * k) * 0 + zv) DIV 2 EXP p) MOD 2 EXP 64 = h` SUBST1_TAC THENL
     [REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`k:num`; `z:int64`; `m:int64`; `x:int64`; `n:num`; `a:num`; `b:num`;
                   `pc:num`; `p:num`; `ii:num`; `w:num`; `h:num`; `k:num`; `0`;
                   `zv:num`; `X17v:num`; `lfv:num`; `hfv:num`] BIGNUM_MOD_PREFIX_DDGE1) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [(* h < 2^64: h = zv DIV 2^p and zv < b*2^64 <= 2^p*2^64 *)
        EXPAND_TAC "h" THEN
        SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ; GSYM EXP_ADD] THEN
        TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[EXP_ADD] THEN MATCH_MP_TAC LE_MULT2 THEN ASM_SIMP_TAC[LT_IMP_LE; LE_REFL]];
        UNDISCH_TAC `2 <= k` THEN ARITH_TAC];
      REWRITE_TAC[SOME_FLAGS] THEN DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (* seg-B: normalize ((w*h)DIV2^64+h) MOD 2^64 -> qh, then tail-C (general qh) + value bridge *)
  SUBGOAL_THEN `((w * h) DIV 2 EXP 64 + h) MOD 2 EXP 64 = qh` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD_LT THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  GHOST_INTRO_TAC `hiw:int64` `read X5` THEN
  GHOST_INTRO_TAC `cwinw:int64` `read X22` THEN
  GHOST_INTRO_TAC `lfw:int64` `read X13` THEN
  GHOST_INTRO_TAC `hfw:int64` `read X14` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(ISPECL
    [`k:num`; `qh:num`; `val(hiw:int64)`;
     `val(cwinw:int64)`; `0`; `b:num`; `zc:num`; `m:int64`; `z:int64`;
     `pc:num`; `X17v:num`; `p DIV 64 + 1`; `k - 1`; `val(lfw:int64)`; `val(hfw:int64)`;
     `x:int64`; `n:num`; `a:num`;
     `word n:int64`; `x:int64`; `word (61*ii):int64`; `word p:int64`; `word w:int64`]
    TAIL_DDLT_C_WIDE_LOG_X) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    (UNDISCH_TAC `2 <= k` THEN UNDISCH_TAC `k < 2 EXP 58` THEN UNDISCH_TAC `p < 2 EXP 64` THEN
     UNDISCH_TAC `(X17v + 124) DIV 64 = k + 1` THEN ARITH_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN `(k - 1) + 1 = k /\ (k - 1) + 2 = k + 1` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `2 <= k` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN
  REWRITE_TAC[SOME_FLAGS] THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[WORD_VAL];
    SUBSUMED_MAYCHANGE_TAC;
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `highdigits zc (k - 1) = highdigits zv (k - 1)` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th =
         `bignum_from_memory (word_add z (word (8 * (k - 1))),k - (k - 1)) s = highdigits zv (k - 1)`
       then MP_TAC th else NO_TAC) THEN
      GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [GSYM HIGHDIGITS_BIGNUM_FROM_MEMORY] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `bignum_from_memory (z,k-1) s = lowdigits zc (k-1)` ASSUME_TAC THENL
     [EXPAND_TAC "zc" THEN REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
      AP_THM_TAC THEN AP_TERM_TAC THEN AP_TERM_TAC THEN UNDISCH_TAC `2 <= k` THEN ARITH_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `bigdigit zc (k-1) = bigdigit zv (k-1)` ASSUME_TAC THENL
     [MP_TAC(AP_TERM `\hh. bigdigit hh 0` (ASSUME `highdigits zc (k - 1) = highdigits zv (k - 1)`)) THEN
      REWRITE_TAC[BIGDIGIT_HIGHDIGITS; ADD_CLAUSES];
      ALL_TAC] THEN
    SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
     [EXPAND_TAC "zc" THEN REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]; ALL_TAC] THEN
    (* CARRY = qh (DERIVED, C_CARRY_IS_Q).  zlo = lowdigits zc (k-1); inner INV from the seg-AB value-rel *)
    SUBGOAL_THEN `lowdigits zc (k-1) < 2 EXP (64 * (k-1))` ASSUME_TAC THENL
     [REWRITE_TAC[LOWDIGITS_BOUND]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(bigdigit zv (k-1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (k-1))) DIV 2 EXP 64 = qh`
     ASSUME_TAC THENL
     [MP_TAC(ISPECL [`zv:num`; `val(hiw:int64)`; `qh:num`; `b:num`; `lowdigits zc (k-1)`;
                     `val(cwinw:int64)`; `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `zv - qh * b`;
                     `p:num`; `k:num`] C_CARRY_IS_Q) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THENL
       [REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
        MP_TAC(ISPEC `cwinw:int64` VAL_BOUND_64) THEN ARITH_TAC;
        UNDISCH_TAC `qh * b <= zv` THEN ARITH_TAC;
        TRANS_TAC LET_TRANS `zv:num` THEN ASM_REWRITE_TAC[] THEN ARITH_TAC;
        FIRST_X_ASSUM(fun th -> if concl th =
          `bignum_from_memory (z,k - 1) s +
           2 EXP (64 * (k - 1)) * (val(cwinw:int64) DIV 8 + 2 EXP 61 * val(hiw:int64)) +
           2 EXP 61 * qh * lowdigits b (k - 1) =
           (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 + 2 EXP 61 * lowdigits zv (k - 1) +
           2 EXP 61 * qh * 2 EXP (64 * (k - 1))`
          then MP_TAC th else NO_TAC) THEN
        FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k-1) s = lowdigits zc (k-1)`
          then REWRITE_TAC[th] else NO_TAC) THEN DISCH_THEN(fun th -> MP_TAC th) THEN ARITH_TAC];
      ALL_TAC] THEN
    (* funnel word W = 2^64*qh + LOW (DERIVED CARRY=qh), word W = word LOW *)
    ABBREV_TAC `W = bigdigit zv (k-1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (k-1))` THEN
    ABBREV_TAC `LOW = W - 2 EXP 64 * qh` THEN
    SUBGOAL_THEN `2 EXP 64 * qh + LOW = W /\ LOW < 2 EXP 64` STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`W:num`; `2 EXP 64`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
      ASM_REWRITE_TAC[] THEN MAP_EVERY EXPAND_TAC ["LOW"] THEN ARITH_TAC;
      ALL_TAC] THEN
    (* word W = word LOW (C_TOP_FUNNEL_GEN) so the tail's ushr/subword use LOW *)
    SUBGOAL_THEN `word W:int64 = word LOW` ASSUME_TAC THENL
     [MATCH_MP_TAC C_TOP_FUNNEL_GEN THEN EXISTS_TAC `qh:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    (* isolate the inner-INV in C_ASSEMBLE_GEN's exact shape (2^61*(qh*..) parenthesization),
       away from the huge s/s' assumption context (else ARITH_TAC over it hangs) *)
    SUBGOAL_THEN
     `lowdigits zc (k-1) + 2 EXP (64 * (k-1)) * (val(cwinw:int64) DIV 8 + 2 EXP 61 * val(hiw:int64)) +
      2 EXP 61 * (qh * lowdigits b (k-1)) =
      (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 + 2 EXP 61 * lowdigits zv (k-1) +
      2 EXP 61 * (qh * 2 EXP (64 * (k-1)))`
     ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th =
        `bignum_from_memory (z,k - 1) s +
         2 EXP (64 * (k - 1)) * (val(cwinw:int64) DIV 8 + 2 EXP 61 * val(hiw:int64)) +
         2 EXP 61 * qh * lowdigits b (k - 1) =
         (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 + 2 EXP 61 * lowdigits zv (k - 1) +
         2 EXP 61 * qh * 2 EXP (64 * (k - 1))`
        then MP_TAC th else NO_TAC) THEN
      FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k-1) s = lowdigits zc (k-1)`
        then REWRITE_TAC[th] else NO_TAC) THEN
      REWRITE_TAC[MULT_ASSOC];
      ALL_TAC] THEN
    (* assemble: X23' = LOW DIV8, z[k-1] = 2^61*(LOW MOD8)+cwin/8; the assembled value = Zf EXACTLY
       (C_ASSEMBLE_GEN: needs only 2^64*qh+LOW=W, NO no-borrow bound). Zf cong+bound via GVC_GEN. *)
    ABBREV_TAC `Zf = 2 EXP 61 * (zv - qh * b) + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61` THEN
    SUBGOAL_THEN
     `2 EXP (64 * k) * (LOW DIV 2 EXP 3) +
      (lowdigits zc (k-1) + 2 EXP (64 * (k-1)) * (2 EXP 61 * (LOW MOD 2 EXP 3) + val(cwinw:int64) DIV 8)) = Zf`
     ASSUME_TAC THENL
     [EXPAND_TAC "Zf" THEN
      MP_TAC(ISPECL [`lowdigits zc (k-1)`;`val(cwinw:int64)`;`val(hiw:int64)`;`qh:num`;`b:num`;`zv:num`;
                     `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`;`LOW:num`;`k:num`] C_ASSEMBLE_GEN) THEN
      (* ASM_REWRITE closes all C_ASSEMBLE hyps (q*b<=zv, inner-INV, 2^64*qh+LOW=W-form: both sides
         rewrite to W) except bigdigit b(k-1)<2^64, the sole residual ANTS conjunct. *)
