       [REWRITE_TAC[BIGDIGIT_BOUND]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(Zf == a DIV 2 EXP (61 * ii)) (mod b) /\ Zf < b * 2 EXP 64` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL [`a:num`; `b:num`; `ii:num`; `p:num`; `zv:num`;
                     `(a DIV 2 EXP (61 * ii)) MOD 2 EXP 61`; `qh:num`; `Zf:num`] GROWING_VALUE_CLOSE_GEN) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN EXPAND_TAC "Zf" THEN REFL_TAC;
