(* ======== inlined: block_bgen_304_win.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_BLOCK_BGEN_304_WIN -- the GENERAL-qhat growing regime-B block, 0x1a4->0x304.
   ----------------------------------------------------------------------------
   Coverage-gap fix (cont75b): at 2<=l<k (dd=l-1) with ARBITRARY window/qhat (window!=0 reachable at
   growing heads for small-top-word moduli -- capgrowwin.py oracle 48/90; capBFwin: ALWAYS grows l->l+1).
   BIGNUM_MOD_BLOCK_B_GROW_304_WIN pins window=0 (=> q=0); this drops that.

   CRUCIAL fact used: window!=0 at head l => 2^p <= Zf < 2^(64*l) => p < 64*l => b < 2^p < 2^(64*l),
   so `lowdigits b l = b` and the cgen math (C_ASSEMBLE_GEN, C_CARRY_IS_Q, GROWING_VALUE_CLOSE_GEN,
   C_TOP_FUNNEL_GEN) REUSES at k:=l.  (When window=0 the B_GROW block already covers it.)

   Structure = block_cgen_304_win.ml with k->l for the regime index (b still k words):
     setup: Zt=0 (INV2_TOP_ZERO l), qhat<2^64 (DDK_QHAT_LT), b<2^(64*l) from window!=0.
     ENSURES_SEQUENCE 0x2e8 (B-midpoint, Zf' = 2^61*(zv-qh*b)+block general, X23'=0 since <2^(64*l)<=2^(64k));
       seg-C: FIELDSEL_CLOSE_SAT (X23'=0 auto) + GROWING_VALUE_CLOSE_GEN; tighten bound to <2^(64(l+1)).
     ENSURES_SEQUENCE 0x23c (PREFIX_DDGE1[l], general h);
       seg-A: PREFIX_DDGE1; seg-B: TAIL_DDLT_B_WIDE_LOG_X (general qh; two MEM stores z[l-1],z[l]) +
         ENSURES_SUBLEMMA + value bridge: C_CARRY_IS_Q(k:=l); C_ASSEMBLE_GEN(k:=l); GROWING_VALUE_CLOSE_GEN;
         GROWING_ZK_FROM_STORES_GEN (general-q, second store to memory z[l]); LOGDIGIT_FINALIZE_BRIDGE.
   Deps: cgen_helpers.ml + block_b_grow_304_win.ml + block_cgen_304_win.ml deps. Load AFTER all three.
   ============================================================================ *)

(* C_TOP_FUNNEL_GEN is defined in block_cgen_304_win.ml (loaded before this). *)

let BIGNUM_MOD_BLOCK_BGEN_304_WIN = prove
 (`!k z m x n a b pc p ii w d l Zt zv X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 2 <= l /\ l < k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ b < 2 EXP (64 * l) /\
     p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ X17v + 124 < 2 EXP 64 /\
     (X17v + 124) DIV 64 = l + 1 /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Zt + zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Zt + zv < b * 2 EXP 64 /\
     2 EXP (64 * k) * Zt + zv < 2 EXP (64 * l) /\
     2 EXP (64 * k) * Zt + zv < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Zt + zv /\
     nonoverlapping (word pc,0x438) (z,8 * k) /\
     nonoverlapping (word pc,0x438) (m,8 * k) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word l /\ read X12 s = word (p DIV 64 + 1) /\
           read X23 s = word Zt /\
           read X15 s = word (((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
