  SUBGOAL_THEN `word_subword (word_join (word (bigdigit zv (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1))):int64) (word (val(cwinw:int64)):int64):int128) (3,64):int64 = word (bigdigit Zf (l - 1)):int64` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s' = word (bigdigit Zf (l - 1))`
      then MP_TAC th else NO_TAC) THEN
    FIRST_ASSUM(fun th -> if concl th =
       `read (memory :> bytes64 (word_add z (word (8 * (l - 1))))) s' =
        word_subword (word_join (word (bigdigit zc (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1))):int64) (word (val(cwinw:int64)):int64):int128) (3,64)`
      then MP_TAC th else NO_TAC) THEN
    REWRITE_TAC[ASSUME `bigdigit zc (l - 1) = bigdigit zv (l - 1)`] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN DISCH_THEN ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `lowdigits Zf (l - 1) = lowdigits zc (l - 1)` ASSUME_TAC THENL
   [SUBGOAL_THEN `lowdigits Zf (l - 1) = lowdigits (lowdigits Zf k) (l - 1)` SUBST1_TAC THENL
     [REWRITE_TAC[LOWDIGITS_LOWDIGITS] THEN AP_TERM_TAC THEN UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `lowdigits Zf k = Zf` SUBST1_TAC THENL
     [MATCH_MP_TAC LOWDIGITS_SELF THEN TRANS_TAC LTE_TRANS `2 EXP (64 * (l + 1))` THEN
      ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN UNDISCH_TAC `l < k` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s' = Zf` then MP_TAC th else NO_TAC) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[LOWDIGITS_BIGNUM_FROM_MEMORY] THEN
    FIRST_ASSUM(fun th -> if concl th = `bignum_from_memory (z,l - 1) s' = lowdigits zc (l - 1)` then MP_TAC th else NO_TAC) THEN
    SUBGOAL_THEN `MIN k (l-1) = l - 1` SUBST1_TAC THENL
     [UNDISCH_TAC `l < k` THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
  MP_TAC(ISPECL [`z:int64`; `k:num`; `zc:num`; `l - 1`; `p DIV 64 + 1`;
                 `lfw:int64`; `hfw:int64`; `s:armstate`] TAIL_LOGIN_TO_ZPRE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`] THEN UNDISCH_TAC `2 <= l` THEN ARITH_TAC; ALL_TAC] THEN
  STRIP_TAC THEN
  MP_TAC(ISPECL [`Zf:num`; `zc:num`; `l - 1`; `p DIV 64 + 1`; `lfw:int64`; `hfw:int64`]
        LOGDIGIT_FINALIZE_BRIDGE) THEN
  REWRITE_TAC[ASSUME `l - 1 + 1 = l`; ASSUME `l - 1 + 2 = l + 1`] THEN
  ASM_REWRITE_TAC[ARITH_RULE `1 <= p DIV 64 + 1`] THEN
  DISCH_THEN(fun bridge -> REWRITE_TAC[GSYM bridge]) THEN
  REWRITE_TAC[WORD_VAL] THEN
  (* two funnel forms in the goal's (word W)/cwinw shape *)
  SUBGOAL_THEN `word_ushr (word W:int64) 3 = word (bigdigit Zf l):int64` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bigdigit zv (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1)) = W`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `word_subword (word_join (word W:int64) (cwinw:int64):int128) (3,64):int64 = word (bigdigit Zf (l - 1)):int64` ASSUME_TAC THENL
   [FIRST_ASSUM(fun th -> if concl th = `bigdigit zv (l - 1) + val(hiw:int64) + qh * (2 EXP 64 - 1 - bigdigit b (l - 1)) = W`
      then MP_TAC th else NO_TAC) THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    SUBGOAL_THEN `cwinw:int64 = word(val(cwinw:int64))` SUBST1_TAC THENL
     [REWRITE_TAC[WORD_VAL]; ALL_TAC] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  (* m-preservation *)
  FIRST_X_ASSUM(fun th -> if can (term_match [] `(f:armstate->armstate->bool) s s'`) (concl th)
    then LABEL_TAC "frame" th else NO_TAC) THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`m:int64`; `k:num`; `z:int64`; `k:num`] MAINLOOP_FRAME_PRESERVES_X_MF)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "frame" (MP_TAC o MATCH_MP th)) THEN ASM_REWRITE_TAC[]);;

