(* ======== inlined: block_dispatch.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_BODY_DISPATCH -- the FULL regime dispatch for ONE main-loop iteration
   (0x1a4 -> 0x304), keyed on l = MIN(k+1)((X17v+63)DIV64), covering ALL regimes incl FLAT.
   ----------------------------------------------------------------------------
   cont102: rebuilt for the jj-bound invariant + the reachable FLAT regime.
   - exit X19 = word(MIN(k+1)((X17v+124)DIV64))  [general raw2, NOT the grow-only raw+1].
   - jj-bound threaded: pre `2^(64k)*Zt+zv < 2^X17v`, post `V' < 2^(X17v+61)`.  Every block now
     carries this (pre+post); the FLAT leaf uses it to discharge its value-fit witness.
   - the false grow-only hyp `(X17v+124)DIV64 = raw+1` is DROPPED; RAW2_STEP splits grow/flat internally.
   Case tree (raw = (X17v+63)DIV64):
     k+1<=raw                          -> DDK  (l=k+1, saturated, raw2=raw)
     l=raw<k+1, RAW2_STEP raw2=raw+1 (GROW):  l=1,k=1->L1K1 ; l=1,1<k->L1 ;
                                              2<=l=k [win=0->C ; win!=0->CGEN] ;
                                              2<=l<k [win=0->B_GROW ; win!=0->BGEN]
     l=raw<k+1, RAW2_STEP raw2=raw   (FLAT):  unified general-FLAT block (2<=l, l<=k), value-fit
                                              witness discharged via JJ_STEP + FLAT_JJ_FIT from the jj-pre.
   Deps: all 8 blocks + jj_bound (JJ_STEP, FLAT_JJ_FIT) + flat_gen_helpers (RAW2_STEP) +
   cgen_helpers (WINDOW_NZ_IMP_B_LT).  Load LAST.
   ============================================================================ *)

let BIGNUM_MOD_BODY_DISPATCH = prove
 (`!k z m x n a b pc p ii w d Zt zv X17v lfv hfv.
     1 <= n /\ n < 2 EXP 58 /\ ii < (64 * n + 60) DIV 61 - 1 /\
     w < 2 EXP 64 /\ 1 <= k /\ k < 2 EXP 58 /\
     b < 2 EXP (64 * k) /\ p < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
     X17v + 124 < 2 EXP 64 /\ 61 <= X17v /\ 1 <= (X17v + 63) DIV 64 /\
     zv < 2 EXP (64 * k) /\
     0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
     (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
     d < 2 EXP 64 /\
     (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
      ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
     (2 EXP 64 + w) * d <= 2 EXP 128 /\
     2 EXP 128 <= (2 EXP 64 + w + 1) * d /\
     (2 EXP (64 * k) * Zt + zv == a DIV 2 EXP (61 * (ii + 1))) (mod b) /\
     2 EXP (64 * k) * Zt + zv < b * 2 EXP 64 /\
     2 EXP (64 * k) * Zt + zv < 2 EXP (64 * MIN (k + 1) ((X17v + 63) DIV 64)) /\
     2 EXP (64 * k) * Zt + zv < 2 EXP X17v /\
     ((w * ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
      ((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) * b
       <= 2 EXP (64 * k) * Zt + zv /\
     nonoverlapping (word pc,0x438) (z,8 * k) /\ nonoverlapping (word pc,0x438) (m,8 * k) /\
     nonoverlapping (word pc,0x438) (x,8 * n) /\
     nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
     ==> ensures arm
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * (ii + 1)) /\ read X17 s = word X17v /\
           read X19 s = word (MIN (k + 1) ((X17v + 63) DIV 64)) /\
           read X12 s = word (p DIV 64 + 1) /\ read X23 s = word Zt /\
           read X15 s = word (((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64) /\
           read X13 s = word lfv /\ read X14 s = word hfv /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           bignum_from_memory (z,k) s = zv)
      (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x304) /\
           read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
           read X4 s = m /\ read X20 s = word p /\ read X21 s = word w /\
           read X16 s = word (61 * ii) /\
           read X17 s = word (X17v + 61) /\
           read X19 s = word (MIN (k + 1) ((X17v + 124) DIV 64)) /\
           read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s == a DIV 2 EXP (61 * ii)) (mod b) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s <
             2 EXP (64 * MIN (k + 1) ((X17v + 124) DIV 64)) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (X17v + 61) /\
           read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                               DIV 2 EXP p) MOD 2 EXP 64))
      (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                  X16; X17; X19; X20; X21; X22; X23; X24] ,,
       MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ABBREV_TAC `l = MIN (k + 1) ((X17v + 63) DIV 64)` THEN
  SUBGOAL_THEN `1 <= l` ASSUME_TAC THENL
   [EXPAND_TAC "l" THEN UNDISCH_TAC `1 <= (X17v + 63) DIV 64` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_CASES_TAC `k + 1 <= (X17v + 63) DIV 64` THENL
   [(* ===== DDK: l=k+1, raw2=raw=k+1 (saturated stays) ===== *)
    SUBGOAL_THEN `l = k + 1` SUBST_ALL_TAC THENL
     [EXPAND_TAC "l" THEN UNDISCH_TAC `k + 1 <= (X17v + 63) DIV 64` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `MIN (k + 1) ((X17v + 124) DIV 64) = k + 1` SUBST1_TAC THENL
     [MP_TAC(SPEC `X17v:num` RAW2_STEP) THEN
      UNDISCH_TAC `k + 1 <= (X17v + 63) DIV 64` THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                   `p:num`;`ii:num`;`w:num`;`d:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                  BIGNUM_MOD_BLOCK_DDK_304_WIN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    (* ===== growing: l = raw < k+1 ===== *)
    ALL_TAC] THEN
  SUBGOAL_THEN `l < k + 1 /\ l = (X17v + 63) DIV 64` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN EXPAND_TAC "l" THEN UNDISCH_TAC `~(k + 1 <= (X17v + 63) DIV 64)` THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `l <= k` ASSUME_TAC THENL
   [UNDISCH_TAC `l < k + 1` THEN ARITH_TAC; ALL_TAC] THEN
  (* RAW2_STEP: raw2 = raw (FLAT) or raw+1 (GROW).  Split. *)
  DISJ_CASES_TAC(SPEC `X17v:num` RAW2_STEP) THENL
   [(* ===== FLAT: raw2 = raw = l, exit l unchanged ===== *)
    SUBGOAL_THEN `MIN (k + 1) ((X17v + 124) DIV 64) = l` (fun th -> REWRITE_TAC[th]) THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l < k + 1` THEN UNDISCH_TAC `l = (X17v + 63) DIV 64` THEN
      ARITH_TAC; ALL_TAC] THEN
    (* Establish 2<=l : l=1-flat is VACUOUS given 61<=X17v (raw2=raw at raw=1 forces X17v in [61,64]
       => (X17v+124)DIV64=2 != 1). *)
    SUBGOAL_THEN `2 <= l` ASSUME_TAC THENL
     [SUBGOAL_THEN `~(l = 1)` MP_TAC THENL
       [DISCH_TAC THEN
        MP_TAC(SPECL [`X17v + 63`; `64`] DIVISION) THEN
        MP_TAC(SPECL [`X17v + 124`; `64`] DIVISION) THEN REWRITE_TAC[ARITH_EQ] THEN
        UNDISCH_TAC `(X17v + 124) DIV 64 = (X17v + 63) DIV 64` THEN
        UNDISCH_TAC `l = (X17v + 63) DIV 64` THEN UNDISCH_TAC `l = 1` THEN
        UNDISCH_TAC `61 <= X17v` THEN ARITH_TAC;
        UNDISCH_TAC `1 <= l` THEN ARITH_TAC]; ALL_TAC] THEN
    (* (X17v+124)DIV64=l (flat); FLAT_JJ_FIT gives X17v+61<=64*l. *)
    SUBGOAL_THEN `(X17v + 124) DIV 64 = l` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `X17v + 61 <= 64 * l` ASSUME_TAC THENL
     [MP_TAC(SPEC `X17v:num` FLAT_JJ_FIT) THEN
      ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
       [CONV_TAC SYM_CONV THEN FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    (* cont105: at ANY flat, Zt=0 -- from V = 2^(64k)*Zt+zv < 2^(64*l) and l<=k (INV2_TOP_ZERO).  SUBST
       + fold UNIFORMLY (before the l<pcode split) so BOTH leaves see the zv-base value-fit witness:
       block_flat_gen's `2^61*zv+block` and flatgen_all's `2^61*(zv-qh*b)+block` both use zv (not the
       full 2^(64k)*Zt+zv) as the base.  (The old code SUBST Zt=0 only in the l<pcode leaf, leaving the
       flatgen_all leaf with a full-value witness that its zv-base hyp could not match -> tryfind.) *)
    SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC INV2_TOP_ZERO THEN MAP_EVERY EXISTS_TAC [`k:num`;`zv:num`;`l:num`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[MULT_CLAUSES; ADD_CLAUSES]) THEN
    (* value-fit witness (zv base): 2^61*(zv - qh*b)+block < 2^(64*l) via JJ_STEP + X17v+61<=64*l. *)
    SUBGOAL_THEN
     `2 EXP 61 * (zv -
        ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
         (zv DIV 2 EXP p) MOD 2 EXP 64) * b) +
      (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l)`
     ASSUME_TAC THENL
     [MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `2 EXP (X17v + 61)` THEN CONJ_TAC THENL
       [MATCH_MP_TAC JJ_STEP THEN ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
        ASM_REWRITE_TAC[LE_EXP; ARITH_EQ]]; ALL_TAC] THEN
    ASM_CASES_TAC `l < p DIV 64 + 1` THENL
     [(* l < pcode: window=0 (V<2^p, large p) -> b-free block_flat_gen_304_win (Zt:=0).  block wants
         the BARE witness 2^61*zv+block<2^(64l); derive it by collapsing qh=0 (window=0) in ours. *)
      SUBGOAL_THEN `(zv DIV 2 EXP p) MOD 2 EXP 64 = 0` ASSUME_TAC THENL
       [SUBGOAL_THEN `zv DIV 2 EXP p = 0` (fun th -> REWRITE_TAC[th; MOD_0]) THEN
        MATCH_MP_TAC DIV_LT THEN
        TRANS_TAC LTE_TRANS `2 EXP (64 * l)` THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
          UNDISCH_TAC `l < p DIV 64 + 1` THEN
          MP_TAC(SPECL [`p:num`; `64`] DIVISION) THEN ARITH_TAC]; ALL_TAC] THEN
      SUBGOAL_THEN `2 EXP 61 * zv + (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l)` ASSUME_TAC THENL
       [UNDISCH_TAC `2 EXP 61 * (zv -
           ((w * (zv DIV 2 EXP p) MOD 2 EXP 64) DIV 2 EXP 64 +
            (zv DIV 2 EXP p) MOD 2 EXP 64) * b) +
         (a DIV 2 EXP (61 * ii)) MOD 2 EXP 61 < 2 EXP (64 * l)` THEN
        ASM_REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; DIV_0; SUB_0]; ALL_TAC] THEN
      MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                     `p:num`;`ii:num`;`w:num`;`l:num`;`0`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                    BIGNUM_MOD_BLOCK_FLAT_GEN_304_WIN) THEN
      REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[];
        REWRITE_TAC[ASSUME `(zv DIV 2 EXP p) MOD 2 EXP 64 = 0`] THEN DISCH_THEN ACCEPT_TAC];
      (* pcode <= l: b<2^(64*l) (p<=64*l-1); unified FLATGEN (Zt:=0, zv-base witness matches). *)
      SUBGOAL_THEN `b < 2 EXP (64 * l)` ASSUME_TAC THENL
       [TRANS_TAC LTE_TRANS `2 EXP p` THEN CONJ_TAC THENL
         [ASM_REWRITE_TAC[LT_IMP_LE];
          REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
          UNDISCH_TAC `~(l < p DIV 64 + 1)` THEN
          MP_TAC(SPECL [`p:num`; `64`] DIVISION) THEN ARITH_TAC]; ALL_TAC] THEN
      MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                     `p:num`;`ii:num`;`w:num`;`d:num`;`l:num`;`0`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                    BIGNUM_MOD_BLOCK_FLATGEN_ALL_304_WIN) THEN
      REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    (* ===== GROW: raw2 = raw + 1, exit l+1 ===== *)
    SUBGOAL_THEN `MIN (k + 1) ((X17v + 124) DIV 64) = l + 1` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[] THEN UNDISCH_TAC `l < k + 1` THEN UNDISCH_TAC `l = (X17v + 63) DIV 64` THEN
      ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(X17v + 124) DIV 64 = l + 1` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_CASES_TAC `l = 1` THENL
     [(* ===== l=1 ===== *)
      FIRST_X_ASSUM(fun th -> if concl th = `l = 1` then SUBST_ALL_TAC th else NO_TAC) THEN
      REWRITE_TAC[ARITH_RULE `1 + 1 = 2`] THEN
      SUBGOAL_THEN `Zt = 0` SUBST_ALL_TAC THENL
       [SUBGOAL_THEN `2 EXP (64 * k) * Zt < 2 EXP (64 * k) * 1` MP_TAC THENL
         [REWRITE_TAC[MULT_CLAUSES] THEN
          TRANS_TAC LET_TRANS `2 EXP (64 * k) * Zt + zv` THEN CONJ_TAC THENL
           [ARITH_TAC; ALL_TAC] THEN
          TRANS_TAC LTE_TRANS `2 EXP (64 * 1)` THEN CONJ_TAC THENL
           [FIRST_X_ASSUM(fun th -> if concl th = `2 EXP (64 * k) * Zt + zv < 2 EXP (64 * 1)`
               then ACCEPT_TAC th else NO_TAC);
            REWRITE_TAC[LE_EXP] THEN UNDISCH_TAC `1 <= k` THEN ARITH_TAC];
          REWRITE_TAC[LT_MULT_LCANCEL; EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC];
        ALL_TAC] THEN
      REWRITE_TAC[ARITH_RULE `2 EXP (64 * k) * 0 + zv = zv`] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[ARITH_RULE `2 EXP (64 * k) * 0 + zv = zv`]) THEN
      SUBGOAL_THEN `zv < 2 EXP 64` ASSUME_TAC THENL
       [TRANS_TAC LTE_TRANS `2 EXP (64 * 1)` THEN CONJ_TAC THENL
         [FIRST_X_ASSUM(fun th -> if concl th = `zv < 2 EXP (64 * 1)` then ACCEPT_TAC th else NO_TAC);
          REWRITE_TAC[MULT_CLAUSES; LE_REFL]];
        ALL_TAC] THEN
      ASM_CASES_TAC `k = 1` THENL
       [(* L1K1: k=1 *)
        FIRST_X_ASSUM(fun th -> if concl th = `k = 1` then SUBST_ALL_TAC th else NO_TAC) THEN
        MP_TAC(ISPECL [`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                       `p:num`;`ii:num`;`w:num`;`d:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                      BIGNUM_MOD_BLOCK_L1K1_304_WIN) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN
          TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          TRY(ASM_REWRITE_TAC[MULT_CLAUSES] THEN NO_TAC) THEN
          (FIRST_X_ASSUM(fun th -> if concl th = `1 = (X17v + 63) DIV 64` then MP_TAC th else NO_TAC) THEN
           UNDISCH_TAC `(X17v + 124) DIV 64 = 1 + 1` THEN ARITH_TAC);
          DISCH_THEN ACCEPT_TAC];
        (* L1: 1<k *)
        MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                       `p:num`;`ii:num`;`w:num`;`d:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                      BIGNUM_MOD_BLOCK_L1_304_WIN) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN
          TRY(FIRST_ASSUM ACCEPT_TAC) THEN
          TRY(UNDISCH_TAC `~(k = 1)` THEN UNDISCH_TAC `1 <= k` THEN ARITH_TAC) THEN
          (UNDISCH_TAC `(X17v + 124) DIV 64 = 1 + 1` THEN ARITH_TAC);
          DISCH_THEN ACCEPT_TAC]];
      (* ===== 2<=l ===== *)
      SUBGOAL_THEN `2 <= l` ASSUME_TAC THENL
       [UNDISCH_TAC `~(l = 1)` THEN UNDISCH_TAC `1 <= l` THEN ARITH_TAC; ALL_TAC] THEN
      ASM_CASES_TAC `l:num = k` THENL
       [(* l=k: C / CGEN *)
        FIRST_X_ASSUM(fun th -> if concl th = `l:num = k` then SUBST_ALL_TAC th else NO_TAC) THEN
        ASM_CASES_TAC `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0` THENL
         [FIRST_ASSUM(fun th -> if concl th = `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0`
             then GEN_REWRITE_TAC (RATOR_CONV o LAND_CONV o ONCE_DEPTH_CONV) [th] else NO_TAC) THEN
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                        BIGNUM_MOD_BLOCK_C_304_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISCH_THEN ACCEPT_TAC];
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`d:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                        BIGNUM_MOD_BLOCK_CGEN_304_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISCH_THEN ACCEPT_TAC]];
        (* l<k: B_GROW / BGEN *)
        SUBGOAL_THEN `l < k` ASSUME_TAC THENL
         [UNDISCH_TAC `l < k + 1` THEN UNDISCH_TAC `~(l:num = k)` THEN ARITH_TAC; ALL_TAC] THEN
        ASM_CASES_TAC `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0` THENL
         [FIRST_ASSUM(fun th -> if concl th = `((2 EXP (64 * k) * Zt + zv) DIV 2 EXP p) MOD 2 EXP 64 = 0`
             then GEN_REWRITE_TAC (RATOR_CONV o LAND_CONV o ONCE_DEPTH_CONV) [th] else NO_TAC) THEN
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`l:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                        BIGNUM_MOD_BLOCK_B_GROW_304_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISCH_THEN ACCEPT_TAC];
          SUBGOAL_THEN `b < 2 EXP (64 * l)` ASSUME_TAC THENL
           [MATCH_MP_TAC WINDOW_NZ_IMP_B_LT THEN
            MAP_EVERY EXISTS_TAC [`2 EXP (64 * k) * Zt + zv`; `p:num`] THEN ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                         `p:num`;`ii:num`;`w:num`;`d:num`;`l:num`;`Zt:num`;`zv:num`;`X17v:num`;`lfv:num`;`hfv:num`]
                        BIGNUM_MOD_BLOCK_BGEN_304_WIN) THEN
          ANTS_TAC THENL
           [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN ASM_REWRITE_TAC[];
            DISCH_THEN ACCEPT_TAC]]]]]);;

Printf.printf "\n=== block_dispatch.ml: BIGNUM_MOD_BODY_DISPATCH (FULL 9-leaf, jj-bound, RAW2_STEP flat/grow) ===\n%!";;


(* ======== inlined: mainloop_wrap.ml ======== *)
(* ============================================================================
   Stage 3f: BIGNUM_MOD_MAINLOOP -- the full main division loop (pc+0x1a4 -> pc+0x304),
   wrapping BIGNUM_MOD_BODY_DISPATCH over the 61-bit-block countdown via ENSURES_WHILE_PDOWN_TAC.
   ----------------------------------------------------------------------------
   cont106.  Precond n < 2^58 - 1 (tightened from 2^58): the ARM l'-block-counter add
   (j+124)/64 overflows a 64-bit register at exactly n = 2^58-1 (a ~2 EB unallocatable input);
   n <= 2^58-2 keeps X17v+124 = 61*(NB-i)+124 <= 61*NB+124 < 2^64 at every body.  See
   X17_BOUND_ONPAPER.md.  Also needs k < 2^58 (from BIGNUM_MOD_CORRECT), not just k<2^64.

   Invariant INV(i) (i = NB..0, NB = (64n+60)DIV61-1) with the jj-bound clause, ending in `/\ T`
   (ENSURES_WHILE_PDOWN_TAC is the EXTRA-CONJUNCT variant: it takes the LAST top conjunct as the
   loop-end-only extra; `/\ T` makes it trivial so the body-step pre is the FULL invariant):
     X17=word(61+61*(NB-i)) [the running j]; X16=word(61*i); X19=word(MIN(k+1)((61+61*(NB-i)+63)DIV64));
     V := 2^(64k)*val(X23)+bignum(z,k); cong V==a DIV 2^(61 i) mod b; V<b*2^64;
     V<2^(64*MIN(k+1)(...)); V<2^(61+61*(NB-i)) [jj]; X15=window.
   Body maps INV(i+1)@0x1a4 -> INV(i)@0x304 via BIGNUM_MOD_BODY_DISPATCH (X17v:=61+61*(NB-(i+1)),
   ii:=i, w:=val w, Zt/zv/lfv/hfv GHOST_INTRO'd).  Entry i=NB: V=a DIV 2^(61 NB)<2^61 (jj base).
   Deps: BIGNUM_MOD_BODY_DISPATCH + BIGNUM_MOD_EXEC + I0_BOUNDS (banked). *)

(* QH_NOOVERSHOOT (old, RECIP_B-routed) REMOVED cont108 -- superseded by RED_LEMMA_D (red_lemma_d.ml),
   which gives qh*b<=V pointwise from the recip-of-d brackets (no false RECIP_B).  The body-step below
   now calls RED_LEMMA_D directly for the dispatch's qh-bound hyp. *)

let BIGNUM_MOD_MAINLOOP = prove
 (`!k z n x m a b w d p pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\ p < 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\
      a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\
      ~(b = 0) /\
      val(w:int64) < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
      0 < (b * 2 EXP 64) DIV 2 EXP p /\ (b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64 /\
      (b * 2 EXP 64) DIV 2 EXP p * 2 EXP p + (b * 2 EXP 64) MOD 2 EXP p = b * 2 EXP 64 /\
      d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + val(w:int64)) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + val(w:int64) + 1) * d /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\
      nonoverlapping (word pc,0x438) (x,8 * n) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      nonoverlapping (z,8 * k) (x,8 * n)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x1a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
            read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
            read X20 s = word p /\ read X21 s = w /\
            read X16 s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
            read X17 s = word 61 /\ read X19 s = word 1 /\
            read X12 s = word (p DIV 64 + 1) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            read X15 s = word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
                               DIV 2 EXP p MOD 2 EXP 64) /\
            2 EXP (64*k) * val(read X23 s) + bignum_from_memory (z,k) s =
              a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
            read X3 s = x /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\
            read X12 s = word (p DIV 64 + 1) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            (2 EXP (64*k) * val(read X23 s) + bignum_from_memory (z,k) s == a)
              (mod b) /\
            2 EXP (64*k) * val(read X23 s) + bignum_from_memory (z,k) s
              < b * 2 EXP 64 /\
            read X15 s = word (((2 EXP (64*k) * val(read X23 s) +
                                bignum_from_memory (z,k) s) DIV 2 EXP p) MOD 2 EXP 64))
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `61 * ((64 * n + 60) DIV 61 - 1) + 124 < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `n < 2 EXP 58 - 1` THEN ARITH_TAC; ALL_TAC] THEN
  ABBREV_TAC `NB = (64 * n + 60) DIV 61 - 1` THEN
  ENSURES_WHILE_PDOWN_TAC `NB:num` `pc + 0x1a4` `pc + 0x304`
   `\i s. (read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
           read X3 s = x /\ read X4 s = m /\ read X20 s = word p /\ read X21 s = w /\
           read X16 s = word (61 * i) /\
           read X17 s = word (61 + 61 * (NB - i)) /\
           read X19 s = word (MIN (k + 1) ((61 + 61 * (NB - i) + 63) DIV 64)) /\
           read X12 s = word (p DIV 64 + 1) /\
           bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
           (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
              == a DIV 2 EXP (61 * i)) (mod b) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s
              < 2 EXP (64 * MIN (k + 1) ((61 + 61 * (NB - i) + 63) DIV 64)) /\
           2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < 2 EXP (61 + 61 * (NB - i)) /\
           bignum_from_memory (z,k) s < 2 EXP (64 * k) /\
           read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                               DIV 2 EXP p) MOD 2 EXP 64)) /\
          T` THEN
  ASM_REWRITE_TAC[] THEN
  (* ---- NB <> 0 ---- *)
  CONJ_TAC THENL
   [EXPAND_TAC "NB" THEN
    MP_TAC(SPECL [`64 * n`; `61`] DIVISION) THEN REWRITE_TAC[ARITH_EQ] THEN
    UNDISCH_TAC `1 <= n` THEN ARITH_TAC;
    ALL_TAC] THEN
  (* ---- entry jj-base: a DIV 2^(61 NB) < 2^61  (from a < 2^(64n) <= 2^(61+61*NB)) ---- *)
  SUBGOAL_THEN `64 * n <= 61 + 61 * NB` ASSUME_TAC THENL
   [EXPAND_TAC "NB" THEN MP_TAC(SPECL [`64 * n`; `61`] DIVISION) THEN
    REWRITE_TAC[ARITH_EQ] THEN UNDISCH_TAC `1 <= n` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `a DIV 2 EXP (61 * NB) < 2 EXP 61` ASSUME_TAC THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
    REWRITE_TAC[GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `2 EXP (64 * n)` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
      UNDISCH_TAC `64 * n <= 61 + 61 * NB` THEN ARITH_TAC]; ALL_TAC] THEN
  (* ---- ENTRY (i = NB) ---- *)
  CONJ_TAC THENL
   [ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SUB_REFL; MULT_CLAUSES; ADD_CLAUSES] THEN
    SUBGOAL_THEN `MIN (k + 1) ((61 + 63) DIV 64) = 1` SUBST1_TAC THENL
     [REWRITE_TAC[ARITH_RULE `(61 + 63) DIV 64 = 1`; ARITH_RULE `MIN (k + 1) 1 = 1`]; ALL_TAC] THEN
    REWRITE_TAC[CONG_REFL; MULT_CLAUSES] THEN
    (* residual (V = a DIV 2^(61 NB), with a DIV 2^(61 NB) < 2^61 in hyps):
       V<b*2^64 ; V<2^(64*1) ; V<2^61 ; bignum(z,k)<2^(64k).  Also X23=word 0 so V=bignum(z,k). *)
    REPEAT CONJ_TAC THEN
    TRY(FIRST_ASSUM ACCEPT_TAC) THEN
    TRY(REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND]) THEN
    TRY(TRANS_TAC LTE_TRANS `2 EXP 61` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
        (UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC)) THEN
    (* V < b*2^64 : V<2^61 <= 1*2^64 <= b*2^64 *)
    TRANS_TAC LTE_TRANS `2 EXP 61` THEN ASM_REWRITE_TAC[] THEN
    TRANS_TAC LE_TRANS `1 * 2 EXP 64` THEN CONJ_TAC THENL
     [REWRITE_TAC[MULT_CLAUSES; LE_EXP] THEN ARITH_TAC;
      REWRITE_TAC[LE_MULT_RCANCEL] THEN DISJ1_TAC THEN UNDISCH_TAC `~(b = 0)` THEN ARITH_TAC];
    ALL_TAC] THEN
  (* ---- BODY (INV(i+1)@0x1a4 -> INV(i)@0x304 via BIGNUM_MOD_BODY_DISPATCH) ---- *)
  CONJ_TAC THENL
   [X_GEN_TAC `i:num` THEN STRIP_TAC THEN
    GHOST_INTRO_TAC `Ztv:num` `\s. val(read X23 s)` THEN
    GHOST_INTRO_TAC `zprev:num` `bignum_from_memory (z,k)` THEN
    GHOST_INTRO_TAC `lfvv:int64` `read X13` THEN
    GHOST_INTRO_TAC `hfvv:int64` `read X14` THEN
    (* expose the invariant-pre conjuncts (cong, bounds, zprev<2^(64k), X15, regs) as free hyps,
       so the dispatch ANTS discharges from them (GLOBALIZE_PRECONDITION_TAC, cf body_assembly.ml). *)
    GLOBALIZE_PRECONDITION_TAC THEN
    (* reconcile the dispatch's (X17v+61)/(X17v+124) outputs with 61+61*(NB-i)/+63 forms.
       (NB-(i+1))+1 = NB-i since i+1<=NB (i<NB). *)
    (* NB: HOL `+` is RIGHT-assoc, but the dispatch builds X17v+61 = (61+61*(NB-(i+1)))+61
       (LEFT-assoc, from substituting the compound X17v).  State the identities with EXPLICIT
       left-assoc parens so REWRITE matches the dispatch's actual X17/X19 subterms. *)
    SUBGOAL_THEN `(61 + 61 * (NB - (i + 1))) + 61 = 61 + 61 * (NB - i) /\
                  (61 + 61 * (NB - (i + 1))) + 124 = 61 + 61 * (NB - i) + 63`
      STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `i < NB` THEN ARITH_TAC; ALL_TAC] THEN
    (* qh-noovershoot for the dispatch's qh-bound hyp (V := 2^(64k)*Ztv+zprev), via RED_LEMMA_D
       (recip-of-d).  RED_LEMMA_D yields qh*b<=V /\ V<qh*b+2^(p+2); take the first conjunct. *)
    (* V = 2^(64k)*Ztv+zprev < b*2^64 < 2^(p+64) => V DIV 2^p < 2^64 (window MOD is identity). *)
    SUBGOAL_THEN `(2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p < 2 EXP 64` ASSUME_TAC THENL
     [MP_TAC(SPECL [`2 EXP p`; `2 EXP (64 * k) * Ztv + zprev`; `2 EXP 64`] RDIV_LT_EQ) THEN
      REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN DISCH_THEN SUBST1_TAC THEN
      TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
      ONCE_REWRITE_TAC[MULT_SYM] THEN REWRITE_TAC[LE_MULT_LCANCEL] THEN
      DISJ2_TAC THEN ASM_SIMP_TAC[LT_IMP_LE];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `2 EXP (64 * k) * Ztv + zprev =
      ((2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p) MOD 2 EXP 64 * 2 EXP p +
      (2 EXP (64 * k) * Ztv + zprev) MOD 2 EXP p` ASSUME_TAC THENL
     [SUBGOAL_THEN `((2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p) MOD 2 EXP 64 =
                    (2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p` SUBST1_TAC THENL
       [ASM_SIMP_TAC[MOD_LT]; ALL_TAC] THEN
      MP_TAC(SPECL [`2 EXP (64 * k) * Ztv + zprev`; `2 EXP p`] DIVISION) THEN
      REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(ISPECL [`b:num`;`p:num`;`val(w:int64)`;`d:num`;
                   `((2 EXP (64 * k) * Ztv + zprev) DIV 2 EXP p) MOD 2 EXP 64`;
                   `(2 EXP (64 * k) * Ztv + zprev) MOD 2 EXP p`;
                   `2 EXP (64 * k) * Ztv + zprev`] RED_LEMMA_D) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN NO_TAC) THEN
      ASM_REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ];
      DISCH_THEN(MP_TAC o CONJUNCT1) THEN
      REWRITE_TAC[GSYM QHAT_ID] THEN DISCH_TAC] THEN
    MP_TAC(ISPECL [`k:num`;`z:int64`;`m:int64`;`x:int64`;`n:num`;`a:num`;`b:num`;`pc:num`;
                   `p:num`;`i:num`;`val(w:int64)`;`d:num`;`Ztv:num`;`zprev:num`;
                   `61 + 61 * (NB - (i + 1))`;`val(lfvv:int64)`;`val(hfvv:int64)`]
                  BIGNUM_MOD_BODY_DISPATCH) THEN
    REWRITE_TAC[WORD_VAL] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[VAL_BOUND_64] THEN
      RULE_ASSUM_TAC(REWRITE_RULE[GSYM ADD_ASSOC]) THEN
      REWRITE_TAC[GSYM ADD_ASSOC] THEN REPEAT CONJ_TAC THEN
      TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      TRY(UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `n < 2 EXP 58 - 1` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `i < NB` THEN UNDISCH_TAC `(64 * n + 60) DIV 61 - 1 = NB` THEN ARITH_TAC) THEN
      TRY(UNDISCH_TAC `61 * NB + 124 < 2 EXP 64` THEN UNDISCH_TAC `i < NB` THEN
          UNDISCH_TAC `(64 * n + 60) DIV 61 - 1 = NB` THEN ARITH_TAC) THEN
      TRY(MP_TAC(SPECL [`61 + 61 * (NB - (i + 1))`; `64`] DIVISION) THEN ARITH_TAC) THEN
      ARITH_TAC;
      (* dispatch ensures ==> loop-body ensures.  Rewrite the two arith identities so dispatch's
         POST matches the loop-body POST; then only the PRE differs (dispatch PRE has the full
         register+X15 reads, loop PRE was GLOBALIZE'd) -- close via ENSURES_PRECONDITION_THM
         (prove loop-PRE ==> dispatch-PRE by GEN+STRIP+ASM_REWRITE), cf block_ddk_304_win:177. *)
      REWRITE_TAC[ASSUME `(61 + 61 * (NB - (i + 1))) + 61 = 61 + 61 * (NB - i)`;
                  ASSUME `(61 + 61 * (NB - (i + 1))) + 124 = 61 + 61 * (NB - i) + 63`;
                  WORD_VAL; SOME_FLAGS] THEN
      (* dispatch-ens ==> loop-ens.  After the identity rewrite the POSTs agree EXCEPT loop-POST
         has an extra `bignum(z,k) s < 2^(64k)` conjunct (Q_d' ==> Q_l by BIGNUM_FROM_MEMORY_BOUND),
         and the PREs differ (P_l ==> P_d).  Chain POST-weaken (ENSURES_POSTCONDITION_THM: Q_d'==>Q_l)
         then PRE-weaken (ENSURES_PRECONDITION_THM: P_l==>P_d).  Metavars left by MATCH_MP_TAC unify
         against the dispatch ens supplied by MP_TAC. *)
      DISCH_THEN(fun dth ->
        (* dth : ensures arm P_d Q_d C.  Extract Q_d, P_d exactly.  Weaken POST (Q_d==>Q_l via
           BIGNUM_FROM_MEMORY_BOUND) then PRE (P_l==>P_d), then ACCEPT dth. *)
        let ens = concl dth in
        let qd = rand(rator ens) and pd = rand(rator(rator ens)) in
