   [X_GEN_TAC `i:num` THEN STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
    SUBGOAL_THEN `val(word (61 * i):int64) = 61 * i` ASSUME_TAC THENL
     [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
