(* ============================================================================
   BIGNUM_MOD_NEGADD1_PREFIX (pc 0x308 -> 0x32c) -- the Stage-4 quotient setup:
     umulh t0,w,h; add q,t0,h  (q = multop(w,h)+h into X15);  mov hh(X5),q;  mov ii(X8),0;
     add p(X20),p,#3 (the p-bump);  lsr pcode(X12),p,#6;  mov lf(X13),0;  mov hf(X14),0;
     cbz k,negaddtail1 (NOT taken since k<>0).
   Straight-line ARM_STEPS(1--9).  Sets up the negaddloop1 PRE (X5=X15=q, X8=0, X12=pcode,
   X13=X14=0).  Precond p+3<2^64 (X20 bump no wrap; p=bitsize b << 2^64 at call site),
   h<2^64, q=multop(w,h)+h<2^64 (from RED_LEMMA_D's qh<2^64 at the call site).
   ============================================================================ *)

let BIGNUM_MOD_NEGADD1_PREFIX = prove
 (`!k z m w h p zk b Ztv pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ p + 3 < 2 EXP 64 /\
      h < 2 EXP 64 /\ (val(w:int64) * h) DIV 2 EXP 64 + h < 2 EXP 64
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\ read X15 s = word h /\
            read X23 s = word Ztv /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x32c) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word (p + 3) /\ read X21 s = w /\ read X23 s = word Ztv /\
            read X8 s = word 0 /\
            read X15 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
            read X5 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
            read X12 s = word ((p + 3) DIV 64) /\
            read X13 s = word 0 /\ read X14 s = word 0 /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `val(word h:int64) = h` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  ARM_STEPS_TAC BIGNUM_MOD_EXEC (1--9) THEN
  ENSURES_FINAL_STATE_TAC THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [CONV_TAC WORD_RULE;
    CONV_TAC WORD_RULE;
    CONV_TAC WORD_RULE;
    REWRITE_TAC[word_ushr; GSYM WORD_ADD] THEN AP_TERM_TAC THEN
    REWRITE_TAC[VAL_WORD; DIMINDEX_64] THEN
    SUBGOAL_THEN `(p + 3) MOD 2 EXP 64 = p + 3` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`];
    FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zk`
      then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
    FIRST_X_ASSUM(MP_TAC o check (can
      (term_match [] `(f:armstate->armstate->bool) s0 s9`) o concl)) THEN
    REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
    REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
    REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC;
    FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (m,k) s0 = b`
      then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
    FIRST_X_ASSUM(MP_TAC o check (can
      (term_match [] `(f:armstate->armstate->bool) s0 s9`) o concl)) THEN
    REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
    REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
    REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC]);;

