(* ============================================================================
   negadd1_loop_small.ml (cont108aw) -- BIGNUM_MOD_NEGADD1_LOOP_LOG_SMALL.
   The pcode=0 (p<61 single-word modulus) variant of BIGNUM_MOD_NEGADD1_LOOP_LOG.
   For p<61, pcode = (p+3) DIV 64 = 0, so the negaddloop1 field logging degenerates:
     lf (X13): logged when ii<pcode=0 -> NEVER -> stays word 0.
     hf (X14): logged when ii=pcode=0 -> at ii=0 -> becomes z[0] (the stored word).
   POST: X13 = word 0, X14 = read(mem z[0]) (= the final low word of z).  The value
   equation is identical to the plain loop.  Feeds the p-general BIGNUM_MOD_NEGADD1_TAIL
   field-select, which at pcode=0 computes (2^64*hf + lf) DIV 2^(p+3) MOD 2^64 =
   z[0]*2^(61-p) MOD 2^64 (FUNNEL_SMALL) = the p<61 second-pass window.

   Same structure as BIGNUM_MOD_NEGADD1_LOOP (negadd1_loop.ml): ENSURES_WHILE_AUP over
   i=0..k, per-word NEGADD_STEP + NEGADD1_ADVANCE, but the invariant carries the two
   degenerate logging clauses (X13=word 0 always; X14 = z[0] for i>=1, word 0 for i=0)
   instead of the general MIN/pcode clauses.
   Deps: NEGADD_STEP (stage3_workspace), NEGADD1_ADVANCE (negadd1_helpers).
   ============================================================================ *)

let BIGNUM_MOD_NEGADD1_LOOP_LOG_SMALL = prove
 (`!k z m q zorig b r20 r21 r23 pc.
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      1 <= k /\ k < 2 EXP 58 /\ q < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zorig < 2 EXP (64 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x32c) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X8 s = word 0 /\ read X15 s = word q /\ read X5 s = word q /\
            read X12 s = word 0 /\ read X13 s = word 0 /\ read X14 s = word 0 /\
            read X20 s = r20 /\ read X21 s = r21 /\ read X23 s = r23 /\
            bignum_from_memory (z,k) s = zorig /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x36c) /\ read X8 s = word k /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X15 s = word q /\ read X12 s = word 0 /\
            read X20 s = r20 /\ read X21 s = r21 /\ read X23 s = r23 /\
            read X13 s = word 0 /\
            read X14 s = read (memory :> bytes64 (word_add z (word 0))) s /\
            bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read X5 s) + q * b =
              zorig + q * 2 EXP (64 * k))
       (MAYCHANGE [PC; X5; X6; X7; X8; X9; X10; X13; X14] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_WHILE_AUP_TAC `0` `k:num` `pc + 0x32c` `pc + 0x364`
   `\i s. read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
          read X15 s = word q /\ read X12 s = word 0 /\ read X8 s = word i /\
          read X20 s = r20 /\ read X21 s = r21 /\ read X23 s = r23 /\
          read X13 s = word 0 /\
          bignum_from_memory (m,k) s = b /\
          bignum_from_memory (word_add z (word (8 * i)), k - i) s = highdigits zorig i /\
          (1 <= i ==> read X14 s = read (memory :> bytes64 (word_add z (word 0))) s) /\
          (i = 0 ==> read X14 s = word 0) /\
          bignum_from_memory (z,i) s + 2 EXP (64 * i) * val(read X5 s) +
            q * lowdigits b i = lowdigits zorig i + q * 2 EXP (64 * i)` THEN
  REPEAT CONJ_TAC THENL
   [UNDISCH_TAC `1 <= k` THEN ARITH_TAC;
    (* ===== ENTRY (i=0) ===== *)
    REWRITE_TAC[MULT_CLAUSES; ADD_CLAUSES; SUB_0; WORD_ADD_0;
                ARITH_RULE `~(1 <= 0)`] THEN
    ENSURES_INIT_TAC "s0" THEN ENSURES_FINAL_STATE_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[BIGNUM_FROM_MEMORY_TRIVIAL; HIGHDIGITS_0; LOWDIGITS_0] THEN
    REWRITE_TAC[MULT_CLAUSES; EXP; ADD_CLAUSES; DIV_1] THEN
    MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `q < 2 EXP 64` THEN ARITH_TAC;
    (* ===== BODY (i -> i+1) ===== *)
    X_GEN_TAC `i:num` THEN STRIP_TAC THEN VAL_INT64_TAC `i:num` THEN
    GHOST_INTRO_TAC `hhin:int64` `read X5` THEN
    GHOST_INTRO_TAC `hfin:int64` `read X14` THEN
    GEN_REWRITE_TAC (LAND_CONV o ONCE_DEPTH_CONV)
     [BIGNUM_FROM_MEMORY_OFFSET_EQ_HIGHDIGITS] THEN
    ASM_REWRITE_TAC[ARITH_RULE `k - i = 0 <=> ~(i < k)`; GSYM NOT_LT] THEN
    REWRITE_TAC[ARITH_RULE `k - i - 1 = k - (i + 1)`; BIGNUM_FROM_MEMORY_STEP] THEN
    ENSURES_INIT_TAC "s0" THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add m (word (8 * i)))) s0 =
                  word (bigdigit b i)` ASSUME_TAC THENL
     [REWRITE_TAC[GSYM(ASSUME `bignum_from_memory (m,k) s0 = b`)] THEN
      ASM_SIMP_TAC[BIGDIGIT_BIGNUM_FROM_MEMORY; WORD_VAL]; ALL_TAC] THEN
    SUBGOAL_THEN `read (memory :> bytes64 (word_add z (word (8 * i)))) s0 =
