(* ======== inlined: negadd1_tail.ml ======== *)
(* ============================================================================
   negadd1_tail.ml (cont108) -- BIGNUM_MOD_NEGADD1_TAIL (pc 0x36c -> 0x3a4).
   The negaddtail1 top-word fold + field-select, straight-line (14 instrs):
     sub hh,hh,q; mov ss,zt(X23); add ss,ss,hh; mov zt,ss  (top word zt' = Ztv + (hh - q));
     cmp ii(=k),pcode; csel lf,ss,lf,cc; csel hf,ss,hf,eq   (top-word logging);
     and t0,p_new,#63; neg t1; lsr lf; lsl hf; orr; cmp; csel h  (field-select -> X15).
   Purely the STATE evolution (value semantics V1=V-q*b and LOGGED_FIELD are proven at the
   composition step from NEGADD1_LOOP_LOG's postcond).  X15 output via FIELDSEL_GEN.
   Deps: FIELDSEL_GEN (negadd1_helpers.ml).
   ============================================================================ *)

let BIGNUM_MOD_NEGADD1_TAIL = prove
 (`!k z m p w q hh Ztv lf hf zk b pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ p + 3 < 2 EXP 64
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x36c) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word (p + 3) /\ read X21 s = w /\ read X15 s = word q /\
            read X5 s = hh /\ read X23 s = Ztv /\
            read X8 s = word k /\ read X12 s = word ((p + 3) DIV 64) /\
            read X13 s = lf /\ read X14 s = hf /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x3a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word (p + 3) /\ read X21 s = w /\
            read X23 s = word_add Ztv (word_sub hh (word q)) /\
            read X15 s =
              word ((2 EXP 64 *
                     val(if k = (p + 3) DIV 64
                         then word_add Ztv (word_sub hh (word q)) else hf) +
                     val(if k < (p + 3) DIV 64
                         then word_add Ztv (word_sub hh (word q)) else lf))
                    DIV 2 EXP ((p + 3) MOD 64) MOD 2 EXP 64) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (MAYCHANGE [PC; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  ENSURES_INIT_TAC "s0" THEN
  SUBGOAL_THEN `val(word ((p + 3) DIV 64):int64) = (p + 3) DIV 64` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `p + 3 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `val(word k:int64) = k` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN REWRITE_TAC[DIMINDEX_64] THEN
    UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  ARM_STEPS_TAC BIGNUM_MOD_EXEC (1--14) THEN
  ENSURES_FINAL_STATE_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `word_and (word (p + 3):int64) (word 63) = word ((p + 3) MOD 64)` ASSUME_TAC THENL
   [SUBGOAL_THEN `word 63:int64 = word (2 EXP 6 - 1)` SUBST1_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    REWRITE_TAC[WORD_AND_MASK_WORD; VAL_WORD; DIMINDEX_64] THEN
    AP_TERM_TAC THEN REWRITE_TAC[ARITH_RULE `2 EXP 6 = 64`] THEN
    ONCE_REWRITE_TAC[ARITH_RULE `2 EXP 64 = 64 * 2 EXP 58`] THEN REWRITE_TAC[MOD_MOD];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(val(word_sub (word k) (word ((p + 3) DIV 64)):int64) = 0) <=> (k = (p + 3) DIV 64)`
    SUBST1_TAC THENL
   [REWRITE_TAC[VAL_EQ_0; WORD_SUB_EQ_0] THEN EQ_TAC THENL
     [DISCH_THEN(MP_TAC o AP_TERM `val:int64->num`) THEN ASM_REWRITE_TAC[];
      DISCH_THEN SUBST1_TAC THEN REFL_TAC];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL
      [`if k = (p + 3) DIV 64 then word_add Ztv (word_sub hh (word q)) else hf:int64`;
       `if k < (p + 3) DIV 64 then word_add Ztv (word_sub hh (word q)) else lf:int64`;
       `(p + 3) MOD 64`] FIELDSEL_GEN) THEN
    ANTS_TAC THENL
     [MP_TAC(SPECL [`p + 3`; `64`] DIVISION) THEN ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    (* the two memory-preserve conjuncts: negaddtail1 touches no z/m memory *)
    CONJ_TAC THEN
    (FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s0 = zk` ||
                                concl th = `bignum_from_memory (m,k) s0 = b`
       then GEN_REWRITE_TAC RAND_CONV [SYM th] else NO_TAC) THEN
     REWRITE_TAC[BIGNUM_FROM_MEMORY_BYTES] THEN
     FIRST_X_ASSUM(MP_TAC o check (can
       (term_match [] `(f:armstate->armstate->bool) s0 s14`) o concl)) THEN
     REWRITE_TAC[MAYCHANGE; SEQ_ID] THEN REWRITE_TAC[GSYM SEQ_ASSOC] THEN
     REWRITE_TAC[ASSIGNS_SEQ; ASSIGNS_THM; LEFT_IMP_EXISTS_THM] THEN
     REPEAT GEN_TAC THEN DISCH_THEN(SUBST1_TAC o SYM) THEN READ_OVER_WRITE_ORTHOGONAL_TAC)]);;

