(* ======== inlined: negadd1_log.ml ======== *)
(* ============================================================================
   negadd1_log.ml (cont108) -- BIGNUM_MOD_NEGADD1_LOG (pc 0x308 -> 0x3a4).
   The field-h-ENRICHED first correction pass: same as BIGNUM_MOD_NEGADD1 (value-level
   V1 = V - q*b), PLUS the negaddtail1 field-select output in the POST:
     read X15 s = word (((V - q*b) DIV 2^(p-61)) MOD 2^64)      [V = 2^(64k)*Ztv + zk]
   i.e. h2 = the bit-(p-61) window of V1 = V - q*b.  This h2 is the SECOND-PASS quotient
   digit input that Stage 4b (BIGNUM_MOD_NEGADD2) consumes.

   Structure: PREFIX ;; LOOP_LOG ;; TAIL, composed via ENSURES_SUBLEMMA_THM (same idiom as
   negadd1.ml) but using BIGNUM_MOD_NEGADD1_LOOP_LOG (with lf/hf logging + spectators
   r20/r21/r23 and m-preservation) instead of the plain _LOOP.  The TAIL POST field-select
   (csel funnel over lf/hf/zt') is reconciled to the window of V1 via LOGGED_FIELD_RECONCILE:
     - low term always lf = z[pcode-1] = bigdigit V1 (pcode-1)  (pcode<=k since p<=64k)
     - top term: k=pcode -> zt' = bigdigit V1 k (BIGDIGIT_TOP); pcode<k -> hf = z[pcode]
       = bigdigit V1 pcode (BIGDIGIT_ADD_LEFT)
     then LOGGED_FIELD_WINDOW closes to (V1 DIV 2^(p-61)) MOD 2^64.
   The value V1 = V - q*b is pinned first (NEGADD1_TOPFOLD + CONG_BOUND_PIN + TWOPART_BOUND,
   as in negadd1.ml), then substituted into the field RHS so RECONCILE applies at zt'/zc.

   Extra precond over NEGADD1: p <= 64*k (=> pcode <= k, so the field windows are in range;
   at the CORRECT splice p = bitsize b <= 64*k from b < 2^(64k)).  q written EXPLICITLY.
   Deps: BIGNUM_MOD_NEGADD1_PREFIX (negadd1_loop), BIGNUM_MOD_NEGADD1_LOOP_LOG (negadd1_loop,
         now with r20/r21/r23 spectators + m-preservation in POST), BIGNUM_MOD_NEGADD1_TAIL
         (negadd1_tail), NEGADD1_TOPFOLD/CONG_BOUND_PIN/TWOPART_BOUND/LOGGED_FIELD_RECONCILE
         (negadd1_helpers), ENSURES_SUBLEMMA_THM (base), BIGDIGIT_BIGNUM_FROM_MEMORY,
         VAL_WORD_BIGDIGIT, LE_LDIV_EQ.
   ============================================================================ *)

let BIGNUM_MOD_NEGADD1_LOG = prove
 (`!k z m w h p b Ztv zk pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 61 <= p /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\
      h < 2 EXP 64 /\ (val(w:int64) * h) DIV 2 EXP 64 + h < 2 EXP 64 /\
      ((val(w:int64) * h) DIV 2 EXP 64 + h) * b <= 2 EXP (64 * k) * Ztv + zk /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\ read X15 s = word h /\
            read X23 s = word Ztv /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x3a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word (p + 3) /\ read X21 s = w /\
            read X15 s =
              word ((((2 EXP (64 * k) * Ztv + zk) -
                      ((val(w:int64) * h) DIV 2 EXP 64 + h) * b)
                     DIV 2 EXP (p - 61)) MOD 2 EXP 64) /\
            bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s =
              (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h) DIV 2 EXP 64 + h) * b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  (* ===== PREFIX 0x308 -> 0x32c ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x32c`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
        read X20 s = word (p + 3) /\ read X21 s = w /\ read X23 s = word Ztv /\
        read X8 s = word 0 /\
        read X15 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
        read X5 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
        read X12 s = word ((p + 3) DIV 64) /\
        read X13 s = word 0 /\ read X14 s = word 0 /\
        bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `w:int64`; `h:num`; `p:num`; `zk:num`;
                  `b:num`; `Ztv:num`; `pc:num`] BIGNUM_MOD_NEGADD1_PREFIX) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[SOME_FLAGS] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [SUBSUMED_MAYCHANGE_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ===== LOOP_LOG 0x32c -> 0x36c (with lf/hf logging) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x36c`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
        read X20 s = word (p + 3) /\ read X21 s = w /\ read X23 s = word Ztv /\
        read X8 s = word k /\ read X15 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
        read X12 s = word ((p + 3) DIV 64) /\
        (1 <= k ==> read X13 s =
            read (memory :> bytes64 (word_add z (word (8 * (MIN k ((p + 3) DIV 64) - 1))))) s) /\
        ((p + 3) DIV 64 < k ==> read X14 s =
            read (memory :> bytes64 (word_add z (word (8 * ((p + 3) DIV 64))))) s) /\
        (~((p + 3) DIV 64 < k) ==> read X14 s = word 0) /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read X5 s) +
          ((val(w:int64) * h) DIV 2 EXP 64 + h) * b =
          zk + ((val(w:int64) * h) DIV 2 EXP 64 + h) * 2 EXP (64 * k)` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `(val(w:int64) * h) DIV 2 EXP 64 + h`;
                  `zk:num`; `b:num`; `word (p + 3):int64`; `w:int64`; `word Ztv:int64`;
                  `pc:num`; `(p + 3) DIV 64`] BIGNUM_MOD_NEGADD1_LOOP_LOG) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `1 <= k` ASSUME_TAC THENL [UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `1 <= (p + 3) DIV 64` ASSUME_TAC THENL
     [REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`] THEN
      REWRITE_TAC[DIV_EQ_0; ARITH_EQ] THEN UNDISCH_TAC `61 <= p` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(p + 3) DIV 64 < 2 EXP 64` ASSUME_TAC THENL
     [TRANS_TAC LET_TRANS `p + 3` THEN REWRITE_TAC[DIV_LE] THEN
      UNDISCH_TAC `p + 3 < 2 EXP 64` THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
      SUBSUMED_MAYCHANGE_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ===== TAIL 0x36c -> 0x3a4 + value pin (V1=V-q*b) + field-h pin ===== *)
  GHOST_INTRO_TAC `hh:int64` `read X5` THEN
  GHOST_INTRO_TAC `lf:int64` `read X13` THEN
  GHOST_INTRO_TAC `hf:int64` `read X14` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `p:num`; `w:int64`;
                `(val(w:int64) * h) DIV 2 EXP 64 + h`; `hh:int64`;
                `word Ztv:int64`; `lf:int64`; `hf:int64`; `zc:num`; `b:num`; `pc:num`]
               BIGNUM_MOD_NEGADD1_TAIL) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    SUBSUMED_MAYCHANGE_TAC;
    ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  (* shared facts *)
  SUBGOAL_THEN `zc < 2 EXP (64 * k)` ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if concl th = `bignum_from_memory (z,k) s = zc`
      then MP_TAC th else NO_TAC) THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[BIGNUM_FROM_MEMORY_BOUND];
    ALL_TAC] THEN
  SUBGOAL_THEN `val(word Ztv:int64) = Ztv` ASSUME_TAC THENL
   [MATCH_MP_TAC VAL_WORD_EQ THEN ASM_REWRITE_TAC[DIMINDEX_64]; ALL_TAC] THEN
  (* value pin: V1 = V - q*b (NEGADD1_TOPFOLD + CONG_BOUND_PIN + TWOPART_BOUND) *)
  SUBGOAL_THEN
   `2 EXP (64 * k) *
      val(word_add (word Ztv) (word_sub hh (word ((val(w:int64) * h) DIV 2 EXP 64 + h))):int64) +
      zc =
    (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h) DIV 2 EXP 64 + h) * b`
   ASSUME_TAC THENL
   [MP_TAC(SPECL [`word Ztv:int64`; `hh:int64`; `(val(w:int64) * h) DIV 2 EXP 64 + h`;
                  `zc:num`; `zk:num`; `b:num`; `k:num`] NEGADD1_TOPFOLD) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC CONG_BOUND_PIN THEN
    EXISTS_TAC `2 EXP (64 * (k + 1))` THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[VAL_BOUND_64];
      MATCH_MP_TAC(ARITH_RULE `V < K ==> V - qb < K`) THEN
      MATCH_MP_TAC TWOPART_BOUND THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* conjuncts: field-select h  /\  value equation (= the pinned V1EQ) *)
  CONJ_TAC THENL [ALL_TAC; FIRST_ASSUM ACCEPT_TAC] THEN
  (* field-select h = window of V1: strip word, substitute V1EQ, apply LOGGED_FIELD_RECONCILE *)
  AP_TERM_TAC THEN
  FIRST_X_ASSUM(fun th ->
    if is_eq(concl th) &&
       (let l = lhs(concl th) in
        is_comb l && (try fst(dest_const(fst(strip_comb l))) = "+" with _ -> false))
    then GEN_REWRITE_TAC (RAND_CONV o LAND_CONV o LAND_CONV) [SYM th]
    else NO_TAC) THEN
  GEN_REWRITE_TAC (RAND_CONV o LAND_CONV o LAND_CONV) [ADD_SYM] THEN
  MATCH_MP_TAC LOGGED_FIELD_RECONCILE THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[VAL_BOUND_64];
    UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC;
    (* pcode<k ==> val hf = bigdigit zc pcode *)
    DISCH_TAC THEN
    FIRST_X_ASSUM(fun th -> if concl th =
       `(p + 3) DIV 64 < k
        ==> hf = read (memory :> bytes64 (word_add z (word (8 * (p + 3) DIV 64)))) s`
       then MP_TAC th else NO_TAC) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL [`k:num`; `z:int64`; `s:armstate`; `(p + 3) DIV 64`]
      BIGDIGIT_BIGNUM_FROM_MEMORY) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[VAL_WORD_BIGDIGIT];
    (* val lf = bigdigit zc (pcode-1) *)
    SUBGOAL_THEN `(p + 3) DIV 64 <= k` ASSUME_TAC THENL
     [SIMP_TAC[LE_LDIV_EQ; ARITH_EQ] THEN UNDISCH_TAC `p <= 64 * k` THEN ARITH_TAC; ALL_TAC] THEN
    FIRST_X_ASSUM(fun th -> if concl th =
       `1 <= k ==> lf = read (memory :> bytes64 (word_add z (word (8 * (MIN k ((p + 3) DIV 64) - 1))))) s`
       then MP_TAC th else NO_TAC) THEN
    ANTS_TAC THENL [UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `MIN k ((p + 3) DIV 64) = (p + 3) DIV 64` SUBST1_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `MIN k n = n <=> n <= k`]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    MP_TAC(ISPECL [`k:num`; `z:int64`; `s:armstate`; `(p + 3) DIV 64 - 1`]
      BIGDIGIT_BIGNUM_FROM_MEMORY) THEN
    SUBGOAL_THEN `(p + 3) DIV 64 - 1 < k` ASSUME_TAC THENL
     [UNDISCH_TAC `(p + 3) DIV 64 <= k` THEN UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    REWRITE_TAC[VAL_WORD_BIGDIGIT]]);;

Printf.printf "\n=== negadd1_log.ml: BIGNUM_MOD_NEGADD1_LOG (0x308->0x3a4, value + field-h) ===\n%!";;


(* ======== inlined: negadd1_log_small.ml ======== *)
(* ============================================================================
   negadd1_log_small.ml (cont108aw) -- BIGNUM_MOD_NEGADD1_LOG_SMALL (pc 0x308 -> 0x3a4, p<61).
   The p<61 (single-word small modulus) analog of BIGNUM_MOD_NEGADD1_LOG.  Same value-level
   V1 = V - q*b (q = multop(w,h)+h), but the negaddtail1 field-select at pcode=(p+3)DIV64=0
   degenerates: lf=word 0, hf=z[0], so the funnel gives
     read X15 = word (((2^64 * z[0]) DIV 2^(p+3)) MOD 2^64) = word ((V1 * 2^(61-p)) MOD 2^64)
   (FUNNEL_SMALL + z[0] = V1 MOD 2^64 = V1 since V1 < 2^(p+2) <= 2^63).

   Structure: PREFIX ;; LOOP_LOG_SMALL ;; TAIL, composed via ENSURES_SUBLEMMA_THM (same idiom
   as negadd1_log.ml).  PREFIX + TAIL are the p-general lemmas (reused verbatim); the loop is
   the pcode=0 BIGNUM_MOD_NEGADD1_LOOP_LOG_SMALL.  The value pin (V1=V-q*b) is IDENTICAL to
   negadd1_log (NEGADD1_TOPFOLD + CONG_BOUND_PIN + TWOPART_BOUND, all p-free).  The field-h
   reconcile uses LOGGED_FIELD_WINDOW_SMALL (below) instead of LOGGED_FIELD_RECONCILE.

   Extra precond p >= 1 (so pcode=(p+3)DIV64=0 needs p+3<64 i.e. p<=60; stated as p < 61).
   Deps: BIGNUM_MOD_NEGADD1_PREFIX, BIGNUM_MOD_NEGADD1_LOOP_LOG_SMALL, BIGNUM_MOD_NEGADD1_TAIL,
   NEGADD1_TOPFOLD/CONG_BOUND_PIN/TWOPART_BOUND (negadd1_helpers), FUNNEL_SMALL (red2_small),
   ENSURES_SUBLEMMA_THM, BIGDIGIT_BIGNUM_FROM_MEMORY, VAL_WORD_BIGDIGIT.
   ============================================================================ *)

(* LOGGED_FIELD_WINDOW_SMALL: at pcode=0 (p<61), the negaddtail1 funnel over lf=word 0,
   hf=word(bigdigit V1 0) equals (V1 * 2^(61-p)) MOD 2^64, given V1 < 2^(p+2), p < 61.
   (V1 MOD 2^64 = V1 since V1 < 2^63; z[0] = bigdigit V1 0 = V1 MOD 2^64.) *)
let LOGGED_FIELD_WINDOW_SMALL = prove
 (`!V1 p. V1 < 2 EXP (p + 2) /\ p < 61
   ==> (2 EXP 64 * bigdigit V1 0 + 0) DIV 2 EXP (p + 3) MOD 2 EXP 64
       = (V1 * 2 EXP (61 - p)) MOD 2 EXP 64`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ADD_CLAUSES] THEN
  SUBGOAL_THEN `bigdigit V1 0 = V1` SUBST1_TAC THENL
   [REWRITE_TAC[bigdigit; MULT_CLAUSES; EXP; DIV_1] THEN MATCH_MP_TAC MOD_LT THEN
    TRANS_TAC LT_TRANS `2 EXP (p + 2)` THEN ASM_REWRITE_TAC[LT_EXP] THEN
    UNDISCH_TAC `p < 61` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(2 EXP 64 * V1) DIV 2 EXP (p + 3) = V1 * 2 EXP (61 - p)` SUBST1_TAC THENL
   [MATCH_MP_TAC FUNNEL_SMALL THEN UNDISCH_TAC `p < 61` THEN ARITH_TAC; ALL_TAC] THEN
  REFL_TAC);;

Printf.printf "\n=== negadd1_log_small.ml: LOGGED_FIELD_WINDOW_SMALL ===\n%!";;

let BIGNUM_MOD_NEGADD1_LOG_SMALL = prove
 (`!k z m w h p b Ztv zk pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 1 <= p /\ p < 61 /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\
      h < 2 EXP 64 /\ (val(w:int64) * h) DIV 2 EXP 64 + h < 2 EXP 64 /\
      ((val(w:int64) * h) DIV 2 EXP 64 + h) * b <= 2 EXP (64 * k) * Ztv + zk /\
      (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h) DIV 2 EXP 64 + h) * b < 2 EXP (p + 2) /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\
      nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\ read X15 s = word h /\
            read X23 s = word Ztv /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x3a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word (p + 3) /\ read X21 s = w /\
            read X15 s =
              word ((((2 EXP (64 * k) * Ztv + zk) -
                      ((val(w:int64) * h) DIV 2 EXP 64 + h) * b)
                     * 2 EXP (61 - p)) MOD 2 EXP 64) /\
            bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s =
              (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h) DIV 2 EXP 64 + h) * b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  (* ===== PREFIX 0x308 -> 0x32c (p-general) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x32c`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
        read X20 s = word (p + 3) /\ read X21 s = w /\ read X23 s = word Ztv /\
        read X8 s = word 0 /\
        read X15 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
        read X5 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
        read X12 s = word ((p + 3) DIV 64) /\
        read X13 s = word 0 /\ read X14 s = word 0 /\
        bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `w:int64`; `h:num`; `p:num`; `zk:num`;
                  `b:num`; `Ztv:num`; `pc:num`] BIGNUM_MOD_NEGADD1_PREFIX) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[SOME_FLAGS] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [SUBSUMED_MAYCHANGE_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* pcode = (p+3) DIV 64 = 0 for p < 61 *)
  SUBGOAL_THEN `(p + 3) DIV 64 = 0` ASSUME_TAC THENL
   [REWRITE_TAC[DIV_EQ_0; ARITH_EQ] THEN UNDISCH_TAC `p < 61` THEN ARITH_TAC; ALL_TAC] THEN
  (* ===== LOOP_LOG_SMALL 0x32c -> 0x36c (pcode=0: lf=word 0, hf=z[0]) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x36c`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
        read X20 s = word (p + 3) /\ read X21 s = w /\ read X23 s = word Ztv /\
        read X8 s = word k /\ read X15 s = word ((val(w:int64) * h) DIV 2 EXP 64 + h) /\
        read X12 s = word 0 /\ read X13 s = word 0 /\
        read X14 s = read (memory :> bytes64 (word_add z (word 0))) s /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * val(read X5 s) +
          ((val(w:int64) * h) DIV 2 EXP 64 + h) * b =
          zk + ((val(w:int64) * h) DIV 2 EXP 64 + h) * 2 EXP (64 * k)` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `(val(w:int64) * h) DIV 2 EXP 64 + h`;
                  `zk:num`; `b:num`; `word (p + 3):int64`; `w:int64`; `word Ztv:int64`;
                  `pc:num`] BIGNUM_MOD_NEGADD1_LOOP_LOG_SMALL) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `1 <= k` ASSUME_TAC THENL [UNDISCH_TAC `~(k = 0)` THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    MATCH_MP_TAC ENSURES_SUBLEMMA_THM THEN REWRITE_TAC[] THEN
    REPEAT CONJ_TAC THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
      SUBSUMED_MAYCHANGE_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* ===== TAIL 0x36c -> 0x3a4 + value pin (V1=V-q*b) + field-h pin (small window) ===== *)
  GHOST_INTRO_TAC `hh:int64` `read X5` THEN
  GHOST_INTRO_TAC `lf:int64` `read X13` THEN
  GHOST_INTRO_TAC `hf:int64` `read X14` THEN
  GHOST_INTRO_TAC `zc:num` `bignum_from_memory (z,k)` THEN
  MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `p:num`; `w:int64`;
                `(val(w:int64) * h) DIV 2 EXP 64 + h`; `hh:int64`;
                `word Ztv:int64`; `lf:int64`; `hf:int64`; `zc:num`; `b:num`; `pc:num`]
