(* ======== inlined: accuracy_close.ml ======== *)
(* ============================================================================
   accuracy_close.ml (cont108) -- the accuracy-bridge helpers that connect the reciprocal
   reduction lemmas (RED_LEMMA_D / RED2) to the machine-level NEGADD interface, for the
   Stage 4 splice BIGNUM_MOD_308_TO_428 (0x308 -> 0x428).

   The two correction passes both compute q = multop(val w, h) + h = (val w * h) DIV 2^64 + h
   from a 64-bit window h; RED_LEMMA_D / RED2 phrase the same q as ((2^64 + val w) * h) DIV 2^64
   (bridged by QHAT_ID).  These helpers supply the side conditions the machine lemmas need:

     WINDOW2_SMALL  -- the 2nd window h2 = (V1 DIV 2^(p-61)) MOD 2^64 does not wrap: h2 < 2^63
                       and the MOD is vacuous (V1 < 2^(p+2) so V1 DIV 2^(p-61) < 2^63).
     MULTOP_FITS    -- from h2 < 2^63: (val w * h2) DIV 2^64 + h2 < 2^64  (NEGADD2 precond;
                       also NEGADD1's q1 fits since h1 < 2^64 gives the < 2^64 loop bound directly,
                       but pass 2 needs the sharper h2 < 2^63).
     PASS1_RED      -- RED_LEMMA_D specialized to V (window h1), q1 in machine multop form:
                       q1*b <= V (subtraction exact) and V1 = V - q1*b < 2^(p+2) (feeds RED2 + the
                       V1 residual bound).

   Deps: RED_LEMMA_D (red_lemma_d.ml), QHAT_ID (block_value.ml), arith.
   ============================================================================ *)

(* the 2nd window does not wrap: V1 < 2^(p+2), 61<=p  =>  V1 DIV 2^(p-61) < 2^63 and the MOD is id. *)
let WINDOW2_SMALL = prove
 (`!V1 p. V1 < 2 EXP (p + 2) /\ 61 <= p
          ==> V1 DIV 2 EXP (p - 61) < 2 EXP 63 /\
              (V1 DIV 2 EXP (p - 61)) MOD 2 EXP 64 = V1 DIV 2 EXP (p - 61)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `V1 DIV 2 EXP (p - 61) < 2 EXP 63` ASSUME_TAC THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
    REWRITE_TAC[GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `2 EXP (p + 2)` THEN ASM_REWRITE_TAC[LE_EXP; ARITH_EQ] THEN
    UNDISCH_TAC `61 <= p` THEN ARITH_TAC;
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD_LT THEN
    TRANS_TAC LT_TRANS `2 EXP 63` THEN ASM_REWRITE_TAC[LT_EXP] THEN ARITH_TAC]);;

Printf.printf "\n=== accuracy_close.ml: WINDOW2_SMALL ===\n%!";;

(* the multop-plus-window fits a word: h2 < 2^63 (val w < 2^64 automatic) => q2 setup < 2^64. *)
let MULTOP_FITS = prove
 (`!w:int64. !h2. h2 < 2 EXP 63 ==> (val w * h2) DIV 2 EXP 64 + h2 < 2 EXP 64`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(ARITH_RULE `a < 2 EXP 63 /\ h2 < 2 EXP 63 ==> a + h2 < 2 EXP 64`) THEN
  ASM_REWRITE_TAC[] THEN
  SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
  REWRITE_TAC[GSYM EXP_ADD] THEN
  TRANS_TAC LTE_TRANS `2 EXP 64 * 2 EXP 63` THEN CONJ_TAC THENL
   [MATCH_MP_TAC LT_MULT2 THEN ASM_REWRITE_TAC[VAL_BOUND_64];
    REWRITE_TAC[GSYM EXP_ADD; LE_EXP; ARITH_EQ] THEN ARITH_TAC]);;

Printf.printf "\n=== accuracy_close.ml: MULTOP_FITS ===\n%!";;

(* pass-1 reduction accuracy in machine multop form: q1*b <= V (exact) and V1 = V-q1*b < 2^(p+2).
   RED_LEMMA_D on V (window h1), q phrased as (val w * h1) DIV 2^64 + h1 via QHAT_ID. *)
let PASS1_RED = prove
 (`!b p w d h1 V.
      ~(b = 0) /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 61 <= p /\
      d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + val(w:int64)) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + val(w:int64) + 1) * d /\
      V < b * 2 EXP 64 /\
      h1 = (V DIV 2 EXP p) MOD 2 EXP 64
      ==> ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b <= V /\
          V - ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b < 2 EXP (p + 2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hb0 hblt hpb hp hd hdisj hup hlo hv hh1" THEN
  MP_TAC(SPECL [`b:num`; `p:num`; `val(w:int64)`; `d:num`; `h1:num`; `V MOD 2 EXP p`; `V:num`]
    RED_LEMMA_D) THEN
  ANTS_TAC THENL
   [SUBGOAL_THEN `V DIV 2 EXP p < 2 EXP 64` ASSUME_TAC THENL
     [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
      TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
      ONCE_REWRITE_TAC[MULT_SYM] THEN REWRITE_TAC[LE_MULT_LCANCEL] THEN
      DISJ2_TAC THEN MATCH_MP_TAC LT_IMP_LE THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `h1 = V DIV 2 EXP p` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `1 <= p` (fun th -> REWRITE_TAC[th]) THENL
     [UNDISCH_TAC `61 <= p` THEN ARITH_TAC; ALL_TAC] THEN
    SUBGOAL_THEN `(V DIV 2 EXP p) MOD 2 EXP 64 = V DIV 2 EXP p` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`V:num`; `2 EXP p`] DIVISION) THEN
    REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT2 th] THEN
      GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [CONJUNCT1 th]);
    ALL_TAC] THEN
  REWRITE_TAC[GSYM QHAT_ID] THEN STRIP_TAC THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ARITH_RULE `q <= V /\ V < q + e ==> V - q < e`) THEN ASM_REWRITE_TAC[]]);;

Printf.printf "\n=== accuracy_close.ml: PASS1_RED ===\n%!";;

(* a quotient q with q*b <= V < b*2^64 fits a word (b=0 case vacuous since V<0 impossible).
   Used for q1 < 2^64 (NEGADD1_LOG loop bound) and q2 < 2^64 (OPTADD/NEGADD2). *)
let QLE_FIT = prove
 (`!q b V. q * b <= V /\ V < b * 2 EXP 64 ==> q < 2 EXP 64`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `b = 0` THENL
   [UNDISCH_TAC `V < b * 2 EXP 64` THEN ASM_REWRITE_TAC[MULT_CLAUSES; LT]; ALL_TAC] THEN
  SUBGOAL_THEN `q * b < b * 2 EXP 64` MP_TAC THENL
   [TRANS_TAC LET_TRANS `V:num` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ONCE_REWRITE_TAC[MULT_SYM] THEN
  GEN_REWRITE_TAC (LAND_CONV o RAND_CONV) [MULT_SYM] THEN
  ASM_SIMP_TAC[LT_MULT_LCANCEL]);;

Printf.printf "\n=== accuracy_close.ml: QLE_FIT ===\n%!";;


(* ======== inlined: modclose_helpers.ml ======== *)
(* ============================================================================
   modclose_helpers.ml (cont108) -- Stage 4d MOD-close arithmetic helpers.
   After MAINLOOP (V in [0,b*2^64), V==a mod b) + NEGADD1 (V1=V-q1*b) + NEGADD2 (signed V1-q2*b
   + sign mask) + OPTADD (conditional +b), the final k-word result z = a MOD b.
   ============================================================================ *)

(* MOD_CLOSE_CORE -- z = a MOD b from: z==V (mod b), z<b, V==a (mod b), ~(b=0). *)
let MOD_CLOSE_CORE = prove
 (`!z V a b:num.
      (z == V) (mod b) /\ z < b /\ (V == a) (mod b) /\ ~(b = 0)
      ==> z = a MOD b`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC CONG_IMP_EQ THEN EXISTS_TAC `b:num` THEN
  REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ASM_SIMP_TAC[MOD_LT_EQ];
    MP_TAC(SPECL [`a:num`; `b:num`]
      (prove(`!a b:num. (a == a MOD b)(mod b)`,
             REPEAT GEN_TAC THEN ONCE_REWRITE_TAC[CONG_SYM] THEN
             REWRITE_TAC[CONG_LMOD; CONG_REFL]))) THEN
    MATCH_MP_TAC(NUMBER_RULE
      `(z == V)(mod b) /\ (V == a)(mod b)
       ==> (a == a MOD b)(mod b) ==> (z == a MOD b)(mod b)`) THEN
    ASM_REWRITE_TAC[]]);;

Printf.printf "\n=== modclose_helpers.ml: MOD_CLOSE_CORE ===\n%!";;

(* ---- congruence micro-lemmas (top-level so NUMBER_RULE runs cleanly) ---- *)
let CONG_ADD_MULB = prove
 (`!zk2 q2 V b:num. zk2 + q2 * b = V ==> (zk2 == V)(mod b)`,
  CONV_TAC NUMBER_RULE);;

let CONG_SPLIT_CLOSE = prove
 (`!r qbV b V q2:num. r + qbV = b /\ qbV + V = q2 * b ==> (r == V)(mod b)`,
  CONV_TAC NUMBER_RULE);;

(* NEGADD2_OPTADD_VALUE -- value-chain reconstruction for pass2 + optadd (TWO-SIDED).
   V = 2^(64k)*zt1v + zk1 (pre-pass2); NEGADD2 eqn (zk2 = new z-mem, hh/cf loop-final acc/carry);
   sign mask msk = (Tv MOD 2^64 < q2), Tv = zt1v+hh+bitval cf; OPTADD result
   zfin = (zk2 + bitval msk * b) MOD 2^(64k).  ACCURACY BRACKET (two-sided):
     q2*b <= V+b  /\  V < q2*b+b     (i.e. V2 = V - q2*b in [-b, b)); mask fires iff V < q2*b.
   Both branches (q2=Tv: V2 in [0,b), mask F; q2=Tv+1: V2 in [-b,0), mask T) give zfin in [0,b),
   zfin == V (mod b).  NB the "<=" on q2*b (not "<") admits V2=-b exactly (q2 = floor(V/b)+1 with
   V a multiple of b): OPTADD's add-back then yields 0.
   Deep 2nd-pass accuracy (RED2) must deliver this bracket; carried as hyp here.  Type-annotate
   the ABBREV vars (e,Tv,r):num in all quotations (monolithic prove parses them eagerly with fresh
   type vars -> "inventing type variables" + tryfind otherwise).  Deps: CONG_ADD_MULB, CONG_SPLIT_CLOSE. *)
let NEGADD2_OPTADD_VALUE = prove
 (`!k zt1v zk1 zk2 hh cf q2 b V.
      ~(b = 0) /\ q2 < 2 EXP 64 /\
      zt1v < 2 EXP 64 /\ zk1 < 2 EXP (64 * k) /\ zk2 < 2 EXP (64 * k) /\
      hh < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zk2 + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b = zk1 + q2 * 2 EXP (64 * k) /\
      2 EXP (64 * k) * zt1v + zk1 = V /\
      q2 * b <= V + b /\ V < q2 * b + b
      ==> (zk2 + bitval((zt1v + hh + bitval cf) MOD 2 EXP 64 < q2) * b) MOD 2 EXP (64 * k) < b /\
          ((zk2 + bitval((zt1v + hh + bitval cf) MOD 2 EXP 64 < q2) * b) MOD 2 EXP (64 * k) == V)
            (mod b)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ABBREV_TAC `e:num = 2 EXP (64 * k)` THEN
  ABBREV_TAC `Tv:num = zt1v + hh + bitval cf` THEN
  SUBGOAL_THEN `V + (e:num) * q2 = (zk2 + q2 * b) + (e:num) * (Tv:num)` ASSUME_TAC THENL
   [MAP_EVERY (fun t -> UNDISCH_TAC t)
     [`zk2 + (e:num) * (hh + bitval cf) + q2 * b = zk1 + q2 * (e:num)`;
      `(e:num) * zt1v + zk1 = V`; `zt1v + hh + bitval cf = (Tv:num)`] THEN
    CONV_TAC NUM_RING;
    ALL_TAC] THEN
  SUBGOAL_THEN `1 <= (e:num)` ASSUME_TAC THENL
   [EXPAND_TAC "e" THEN REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`; EXP_EQ_0; ARITH_EQ];
    ALL_TAC] THEN
  (* Tv <= q2 : STRICT side, uses V < q2*b+b (strict) *)
  SUBGOAL_THEN `(e:num) * (Tv:num) < (e:num) * (q2 + 1)` MP_TAC THENL
   [MP_TAC(ASSUME `V + (e:num) * q2 = (zk2 + q2 * b) + (e:num) * (Tv:num)`) THEN
    UNDISCH_TAC `V < q2 * b + b` THEN UNDISCH_TAC `b < (e:num)` THEN ARITH_TAC;
    REWRITE_TAC[LT_MULT_LCANCEL] THEN
    ASM_SIMP_TAC[ARITH_RULE `1 <= e ==> ~(e = 0)`] THEN DISCH_TAC] THEN
  SUBGOAL_THEN `(Tv:num) <= q2` ASSUME_TAC THENL
   [UNDISCH_TAC `(Tv:num) < q2 + 1` THEN ARITH_TAC; ALL_TAC] THEN
  (* q2 <= Tv+1 : uses the <= bracket q2*b <= V+b *)
  SUBGOAL_THEN `(e:num) * q2 < (e:num) * ((Tv:num) + 2)` MP_TAC THENL
   [MP_TAC(ASSUME `V + (e:num) * q2 = (zk2 + q2 * b) + (e:num) * (Tv:num)`) THEN
    UNDISCH_TAC `q2 * b <= V + b` THEN UNDISCH_TAC `b < (e:num)` THEN
    UNDISCH_TAC `zk2 < (e:num)` THEN ARITH_TAC;
    REWRITE_TAC[LT_MULT_LCANCEL] THEN
    ASM_SIMP_TAC[ARITH_RULE `1 <= e ==> ~(e = 0)`] THEN DISCH_TAC] THEN
  SUBGOAL_THEN `q2 = (Tv:num) \/ q2 = (Tv:num) + 1` MP_TAC THENL
   [UNDISCH_TAC `q2 < (Tv:num) + 2` THEN UNDISCH_TAC `(Tv:num) <= q2` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(Tv:num) MOD 2 EXP 64 = (Tv:num)` SUBST1_TAC THENL
   [MATCH_MP_TAC MOD_LT THEN
    UNDISCH_TAC `(Tv:num) <= q2` THEN UNDISCH_TAC `q2 < 2 EXP 64` THEN ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN DISJ_CASES_TAC THENL
   [(* q2 = Tv: mask F; zk2 = V - q2*b in [0,b) *)
    SUBGOAL_THEN `~((Tv:num) < q2)` (fun th -> REWRITE_TAC[th]) THENL
     [ASM_REWRITE_TAC[LT_REFL]; ALL_TAC] THEN
    REWRITE_TAC[BITVAL_CLAUSES; MULT_CLAUSES; ADD_CLAUSES] THEN
    SUBGOAL_THEN `zk2 + q2 * b = V` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th = `q2 = (Tv:num)` then SUBST_ALL_TAC th else NO_TAC) THEN
      UNDISCH_TAC `V + (e:num) * (Tv:num) = (zk2 + (Tv:num) * b) + (e:num) * (Tv:num)` THEN
      CONV_TAC NUM_RING; ALL_TAC] THEN
    SUBGOAL_THEN `zk2 < b` ASSUME_TAC THENL
     [ASM_MESON_TAC[ARITH_RULE `zk2 + q2 * b = V /\ V < q2 * b + b ==> zk2 < b`]; ALL_TAC] THEN
    SUBGOAL_THEN `zk2 MOD (e:num) = zk2` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN TRANS_TAC LTE_TRANS `b:num` THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[LT_IMP_LE]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONG_ADD_MULB THEN EXISTS_TAC `q2:num` THEN ASM_REWRITE_TAC[];
    (* q2 = Tv + 1: mask T; kill e*Tv (SUBST q2=Tv+1 + NUM_RING) => zk2 + q2*b = V + e;
       then pure nat arith via ASM_MESON (UNDISCH_TAC flaky here -- ASM_MESON+ARITH_RULE robust). *)
    SUBGOAL_THEN `zk2 + q2 * b = V + (e:num)` ASSUME_TAC THENL
     [FIRST_X_ASSUM(fun th -> if concl th = `q2 = (Tv:num) + 1` then SUBST_ALL_TAC th else NO_TAC) THEN
      UNDISCH_TAC `V + (e:num) * ((Tv:num) + 1) = (zk2 + ((Tv:num) + 1) * b) + (e:num) * (Tv:num)` THEN
      CONV_TAC NUM_RING; ALL_TAC] THEN
    SUBGOAL_THEN `(Tv:num) < q2` (fun th -> REWRITE_TAC[th]) THENL
     [ASM_MESON_TAC[ARITH_RULE `q2 = (Tv:num) + 1 ==> (Tv:num) < q2`]; ALL_TAC] THEN
    REWRITE_TAC[BITVAL_CLAUSES; MULT_CLAUSES] THEN
    SUBGOAL_THEN `q2 * b - V <= b /\ 0 < q2 * b - V` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ARITH_RULE
        `zk2 + q2 * b = V + (e:num) /\ zk2 < (e:num) /\ q2 * b <= V + b /\ V < q2 * b + b
         ==> q2 * b - V <= b /\ 0 < q2 * b - V`];
      ALL_TAC] THEN
    SUBGOAL_THEN `zk2 + b = (e:num) + (b - (q2 * b - V))` ASSUME_TAC THENL
     [ASM_MESON_TAC[ARITH_RULE
        `zk2 + q2 * b = V + (e:num) /\ q2 * b - V <= b /\ 0 < q2 * b - V /\ b < (e:num)
         ==> zk2 + b = (e:num) + (b - (q2 * b - V))`];
      ALL_TAC] THEN
    ABBREV_TAC `r:num = b - (q2 * b - V)` THEN
    SUBGOAL_THEN `(r:num) < b` ASSUME_TAC THENL
     [ASM_MESON_TAC[ARITH_RULE
        `(r:num) = b - (q2 * b - V) /\ 0 < q2 * b - V /\ q2 * b - V <= b ==> (r:num) < b`];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `((e:num) + (r:num)) MOD (e:num) = (r:num)` SUBST1_TAC THENL
     [SUBGOAL_THEN `(e:num) + (r:num) = (r:num) + 1 * (e:num)` SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
      REWRITE_TAC[MOD_MULT_ADD] THEN MATCH_MP_TAC MOD_LT THEN
      TRANS_TAC LTE_TRANS `b:num` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[LT_IMP_LE];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC CONG_SPLIT_CLOSE THEN
    MAP_EVERY EXISTS_TAC [`q2 * b - V`; `q2:num`] THEN
    CONJ_TAC THENL
     [ASM_MESON_TAC[ARITH_RULE `(r:num) = b - (q2 * b - V) /\ q2 * b - V <= b ==> (r:num) + (q2 * b - V) = b`];
      ASM_MESON_TAC[ARITH_RULE `0 < q2 * b - V /\ q2 * b <= V + b ==> (q2 * b - V) + V = q2 * b`]]]);;

Printf.printf "\n=== modclose_helpers.ml: NEGADD2_OPTADD_VALUE (two-sided) ===\n%!";;

(* NEGADD_PASSES_CLOSE -- the FULL MOD-close: NEGADD2_OPTADD_VALUE (zfin<b /\ zfin==V1) chained with
   MOD_CLOSE_CORE (V1==a mod b, ~(b=0)) gives the final k-word OPTADD result = a MOD b.
   V1 = value entering pass2 = V - q1*b (post-NEGADD1); V1 == a (mod b) since V == a and each pass
   subtracts a multiple of b.  Applied by the machine splice at 0x428 to close CORRECT.
   Deps: NEGADD2_OPTADD_VALUE, MOD_CLOSE_CORE. *)
let NEGADD_PASSES_CLOSE = prove
 (`!k zt1v zk1 zk2 hh cf q2 b V1 a.
      ~(b = 0) /\ q2 < 2 EXP 64 /\
      zt1v < 2 EXP 64 /\ zk1 < 2 EXP (64 * k) /\ zk2 < 2 EXP (64 * k) /\
      hh < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zk2 + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b = zk1 + q2 * 2 EXP (64 * k) /\
      2 EXP (64 * k) * zt1v + zk1 = V1 /\
      q2 * b <= V1 + b /\ V1 < q2 * b + b /\
      (V1 == a) (mod b)
      ==> (zk2 + bitval((zt1v + hh + bitval cf) MOD 2 EXP 64 < q2) * b) MOD 2 EXP (64 * k) =
          a MOD b`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPECL [`k:num`;`zt1v:num`;`zk1:num`;`zk2:num`;`hh:num`;`cf:bool`;`q2:num`;`b:num`;`V1:num`]
    NEGADD2_OPTADD_VALUE) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN
  MATCH_MP_TAC MOD_CLOSE_CORE THEN
  EXISTS_TAC `V1:num` THEN ASM_REWRITE_TAC[]);;

Printf.printf "\n=== modclose_helpers.ml: NEGADD_PASSES_CLOSE ===\n%!";;


(* ======== inlined: splice_308_428_dev.ml ======== *)
(* ============================================================================
   splice_308_428_dev.ml (cont108) -- Stage 4 splice building blocks (0x308 -> 0x428).
   NOT loaded into CI.  Segment lemmas + accuracy setup for BIGNUM_MOD_308_TO_428.

     0x308 -> 0x3a4  NEGADD1_SEG  (from BIGNUM_MOD_NEGADD1_LOG: V1 = V - q1*b; X15 = word h2)
     0x3a4 -> 0x400  NEGADD2_SEG  (from BIGNUM_MOD_NEGADD2:     signed V1 - q2*b + sign mask)
     0x400 -> 0x428  BIGNUM_MOD_OPTADD                          (conditional add-back)
   + accuracy (PASS1_RED/WINDOW2_SMALL/MULTOP_FITS/QLE_FIT/RED2) + NEGADD_PASSES_CLOSE.

   Composition idiom (validated): each segment's POST is written to EXACTLY match the block
   POST (ENSURES_SEQUENCE_TAC adds aligned+PC), then discharged by
     MATCH_MP_TAC(REWRITE_RULE[TAUT `(a==>b==>c) <=> (a/\b==>c)`]
       (DISCH_ALL(DISCH_ALL(UNDISCH(SPEC_ALL ENSURES_POSTCONDITION_THM)))))
   which weakens the block-POST onto the (identical) sequenced intermediate.

   Deps: BIGNUM_MOD_NEGADD1_LOG, _NEGADD2, _OPTADD, NEGADD_PASSES_CLOSE,
   accuracy_close.ml (WINDOW2_SMALL/MULTOP_FITS/PASS1_RED/QLE_FIT), red2.ml (RED2), QHAT_ID.
   ============================================================================ *)

(* NEGADD1 as a segment lemma: entry X15=word h1 / value V=2^(64k)Ztv+zk, exit X15=word h2 /
   value V1=V-q1*b (q1 = multop(w,h1)+h1).  Just BIGNUM_MOD_NEGADD1_LOG re-abstracted with
   h2 and V1 as named outputs, discharged by the POST-match idiom. *)
let NEGADD1_SEG = prove
 (`!k z m w h1 h2 p b Ztv zk pc V1.
      ~(k = 0) /\ k < 2 EXP 58 /\ 61 <= p /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\ h1 < 2 EXP 64 /\
      (val(w:int64) * h1) DIV 2 EXP 64 + h1 < 2 EXP 64 /\
      ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b <= 2 EXP (64 * k) * Ztv + zk /\
      V1 = (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b /\
      h2 = (V1 DIV 2 EXP (p - 61)) MOD 2 EXP 64 /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\ nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\ read X15 s = word h1 /\
            read X23 s = word Ztv /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x3a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word (p + 3) /\ read X21 s = w /\ read X15 s = word h2 /\
            bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s = V1)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `w:int64`; `h1:num`; `p:num`;
                `b:num`; `Ztv:num`; `zk:num`; `pc:num`] BIGNUM_MOD_NEGADD1_LOG) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(REWRITE_RULE[TAUT `(a==>b==>c) <=> (a/\b==>c)`]
    (DISCH_ALL(DISCH_ALL(UNDISCH(SPEC_ALL ENSURES_POSTCONDITION_THM))))));;

Printf.printf "\n=== splice_308_428_dev.ml: NEGADD1_SEG ===\n%!";;

(* NEGADD2 as a segment lemma (= BIGNUM_MOD_NEGADD2 verbatim; interfaces already match). *)
let NEGADD2_SEG = prove
 (`!k z m w h2 q2 zt1w zk b p pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ h2 < 2 EXP 64 /\ b < 2 EXP (64 * k) /\
      zk < 2 EXP (64 * k) /\ zt1w < 2 EXP 64 /\
      (val(w:int64) * h2) DIV 2 EXP 64 + h2 < 2 EXP 64 /\
      q2 = (((val(w:int64) * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61) + 1 /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\ nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x3a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X21 s = (w:int64) /\ read X15 s = word h2 /\ read X23 s = word zt1w /\
            read X20 s = word p /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x400) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\ read X20 s = word p /\
            bignum_from_memory (m,k) s = b /\
            ?hh cf. bignum_from_memory (z,k) s + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
                    zk + q2 * 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
                    read X10 s = word ((zt1w + hh + bitval cf) MOD 2 EXP 64) /\
                    read X9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2
                                      then 2 EXP 64 - 1 else 0))
       (MAYCHANGE [PC; X5; X6; X7; X8; X9; X10; X15] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC BIGNUM_MOD_NEGADD2 THEN ASM_REWRITE_TAC[]);;

Printf.printf "\n=== splice_308_428_dev.ml: NEGADD2_SEG ===\n%!";;

(* peel an existential precondition: prove (!x. ensures ...(P x)...) to get ensures ...(?x.P x)... *)
let ENSURES_EXISTS_PRE = prove
 (`!step (P:A->armstate->bool) Q C.
      (!x. ensures step (\s. P x s) Q C) ==> ensures step (\s. ?x. P x s) Q C`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ensures] THEN
  DISCH_TAC THEN GEN_TAC THEN REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN ASM_MESON_TAC[]);;

Printf.printf "\n=== splice_308_428_dev.ml: ENSURES_EXISTS_PRE ===\n%!";;

(* OPTADD + MOD-close as one segment (0x400 -> 0x428).  Flat PRE (hh,cf,zk2 concrete): X9=sign mask,
   z-mem=zk2, value eqn zk2 + 2^(64k)(hh+cf) + q2*b = zk + q2*2^(64k), + the two-sided accuracy
   bracket on V := 2^(64k)*zt1w+zk and (V==a)(mod b).  Applies BIGNUM_MOD_OPTADD (msk := the sign
   condition) then NEGADD_PASSES_CLOSE (lowdigits = MOD) to conclude bignum(z,k) = a MOD b.
   Frame [PC;X0;X6;X7;X8;X9;X10] (OPTADD's).  PROVEN 0-hyp. *)
let OPTADD_CLOSE_SEG = prove
 (`!k z m q2 zt1w zk zk2 hh cf b a p r15 pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ ~(b = 0) /\ b < 2 EXP (64 * k) /\
      zk < 2 EXP (64 * k) /\ zk2 < 2 EXP (64 * k) /\ zt1w < 2 EXP 64 /\ hh < 2 EXP 64 /\
      q2 < 2 EXP 64 /\
      zk2 + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b = zk + q2 * 2 EXP (64 * k) /\
      q2 * b <= (2 EXP (64 * k) * zt1w + zk) + b /\
      2 EXP (64 * k) * zt1w + zk < q2 * b + b /\
      (2 EXP (64 * k) * zt1w + zk == a) (mod b) /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\ nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x400) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\ read X20 s = word p /\
            read X9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0) /\
            read X15 s = r15 /\
            bignum_from_memory (z,k) s = zk2 /\ bignum_from_memory (m,k) s = b)
       (\s. read PC s = word (pc + 0x428) /\ bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [PC; X0; X6; X7; X8; X9; X10] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SOME_FLAGS] THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;
             `(zt1w + hh + bitval cf) MOD 2 EXP 64 < q2`;`zk2:num`;`b:num`;`r15:int64`;`word p:int64`;`pc:num`]
       BIGNUM_MOD_OPTADD)) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL [UNDISCH_TAC `~(k=0)` THEN ARITH_TAC; ALL_TAC] THEN
  DISCH_TAC THEN
  MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN
  EXISTS_TAC
   `\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x428) /\
        bignum_from_memory (z,k) s =
        lowdigits (zk2 + bitval ((zt1w + hh + bitval cf) MOD 2 EXP 64 < q2) * b) k` THEN
  CONJ_TAC THENL
   [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[lowdigits] THEN
    MP_TAC(ISPECL [`k:num`;`zt1w:num`;`zk:num`;`zk2:num`;`hh:num`;`cf:bool`;`q2:num`;
                   `b:num`;`2 EXP (64 * k) * zt1w + zk`;`a:num`] NEGADD_PASSES_CLOSE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  FIRST_X_ASSUM(fun th ->
    if (try fst(dest_const(fst(strip_comb(concl th)))) = "ensures" with _ -> false)
    then EXISTS_TAC (rand(rator(rator(concl th)))) THEN
         CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th]
    else NO_TAC));;

Printf.printf "\n=== splice_308_428_dev.ml: OPTADD_CLOSE_SEG ===\n%!";;

(* pull an s-independent conjunct c out of the precondition into an implication *)
let ENSURES_PRE_DISCH = prove
 (`!step P (c:bool) Q C.
      (c ==> ensures step (\s. P s) Q C) ==> ensures step (\s. P s /\ c) Q C`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ensures] THEN MESON_TAC[]);;

Printf.printf "\n=== splice_308_428_dev.ml: ENSURES_PRE_DISCH ===\n%!";;

(* ---- the full Stage-4 splice ---- *)
let BIGNUM_MOD_308_TO_428 = prove
 (`!k z m w d p a b Ztv zk pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 61 <= p /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ ~(b = 0) /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\
      zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\ d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + val(w:int64)) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + val(w:int64) + 1) * d /\
      (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
      2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64 /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\ nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\ read X23 s = word Ztv /\
            read X15 s = word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. read PC s = word (pc + 0x428) /\ bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt hp hp3 hpk hbk hb0 hbp hpb hzk hZt hd hdisj hup hlo hcong hVlt hn1 hn2 hn3" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ABBREV_TAC `V = 2 EXP (64 * k) * Ztv + zk` THEN
  ABBREV_TAC `h1 = (V DIV 2 EXP p) MOD 2 EXP 64` THEN
  MP_TAC(SPECL [`b:num`; `p:num`; `w:int64`; `d:num`; `h1:num`; `V:num`] PASS1_RED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q1le") (LABEL_TAC "V1lt")) THEN
  ABBREV_TAC `q1 = (val(w:int64) * h1) DIV 2 EXP 64 + h1` THEN
  ABBREV_TAC `V1 = V - q1 * b` THEN
  SUBGOAL_THEN `q1 < 2 EXP 64` (LABEL_TAC "q1fit") THENL
   [MATCH_MP_TAC QLE_FIT THEN MAP_EVERY EXISTS_TAC [`b:num`; `V:num`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ABBREV_TAC `h2 = (V1 DIV 2 EXP (p - 61)) MOD 2 EXP 64` THEN
  SUBGOAL_THEN `h2 < 2 EXP 63` (LABEL_TAC "h2small") THENL
   [EXPAND_TAC "h2" THEN MP_TAC(SPECL [`V1:num`; `p:num`] WINDOW2_SMALL) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT2 th; CONJUNCT1 th]); ALL_TAC] THEN
  SUBGOAL_THEN `h2 < 2 EXP 64` (LABEL_TAC "h2fit") THENL
   [TRANS_TAC LT_TRANS `2 EXP 63` THEN ASM_REWRITE_TAC[LT_EXP] THEN ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`w:int64`; `h2:num`] MULTOP_FITS) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(LABEL_TAC "q2setupfit") THEN
  ABBREV_TAC `q2 = ((val(w:int64) * h2) DIV 2 EXP 64 + h2) DIV 2 EXP 61 + 1` THEN
  MP_TAC(SPECL [`b:num`; `p:num`; `val(w:int64)`; `d:num`; `h2:num`; `V1:num`] RED2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN EXPAND_TAC "h2" THEN REFL_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM QHAT_ID] THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "q2le") (LABEL_TAC "V1ltq2")) THEN
  SUBGOAL_THEN `(V1 == a) (mod b)` (LABEL_TAC "congV1") THENL
   [SUBGOAL_THEN `V1 + q1 * b = V` MP_TAC THENL
     [MAP_EVERY (fun t -> UNDISCH_TAC t) [`V - q1 * b = V1`; `q1 * b <= V`] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(SPECL [`V1:num`;`q1:num`;`V:num`;`b:num`] CONG_ADD_MULB) THEN REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(NUMBER_RULE `(V1 == V)(mod b) /\ (V == a)(mod b) ==> (V1 == a)(mod b)`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `q2 < 2 EXP 64` (LABEL_TAC "q2fit") THENL
   [EXPAND_TAC "q2" THEN MATCH_MP_TAC(ARITH_RULE `x < 8 ==> x + 1 < 2 EXP 64`) THEN
    MATCH_MP_TAC(ARITH_RULE `y < 2 EXP 64 ==> y DIV 2 EXP 61 < 8`) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== 0x308 -> 0x3a4 : NEGADD1_SEG ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x3a4`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
        read X20 s = word (p + 3) /\ read X21 s = w /\ read X15 s = word h2 /\
        bignum_from_memory (m,k) s = b /\
        2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s = V1` THEN
  CONJ_TAC THENL
   [MP_TAC(REWRITE_RULE[SOME_FLAGS]
      (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:int64`;`h1:num`;`h2:num`;`p:num`;
               `b:num`;`Ztv:num`;`zk:num`;`pc:num`;`V1:num`] NEGADD1_SEG)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[ASSUME `(val w * h1) DIV 2 EXP 64 + h1 = q1`;
                  ASSUME `2 EXP (64 * k) * Ztv + zk = V`] THEN ASM_REWRITE_TAC[] THEN
      EXPAND_TAC "h1" THEN REWRITE_TAC[MOD_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
      REWRITE_TAC[ASSUME `V - q1 * b = V1`; ASSUME `(V1 DIV 2 EXP (p - 61)) MOD 2 EXP 64 = h2`];
      ALL_TAC] THEN
    DISCH_TAC THEN MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
    FIRST_X_ASSUM(fun th ->
      if (try fst(dest_const(fst(strip_comb(concl th)))) = "ensures" with _ -> false)
      then EXISTS_TAC (rand(rator(rator(concl th)))) THEN
           CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th]
      else NO_TAC);
    ALL_TAC] THEN
  (* ===== at 0x3a4: GHOST X23/z-mem, lift value facts to context ===== *)
  GHOST_INTRO_TAC `zt1w:num` `\s. val(read X23 s)` THEN
  GHOST_INTRO_TAC `zk1:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x3a4) /\
         read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
         read X20 s = word (p + 3) /\ read X21 s = w /\ read X15 s = word h2 /\
         read X23 s = word zt1w /\
         bignum_from_memory (z,k) s = zk1 /\ bignum_from_memory (m,k) s = b) /\
        (2 EXP (64 * k) * zt1w + zk1 = V1 /\ zt1w < 2 EXP 64 /\ zk1 < 2 EXP (64 * k))` THEN
  CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN RULE_ASSUM_TAC BETA_RULE THEN
    FIRST_X_ASSUM(fun th -> if is_conj(concl th) then STRIP_ASSUME_TAC th else NO_TAC) THEN
    BETA_TAC THEN
    (* state-agnostic X23=word zt1w: SYM the ghost fact val(read X23 ?)=zt1w (whatever the
       GEN_TAC state var is named -- was hardcoded `s` which broke cold-load when GEN_TAC
       chose `x`), add it, then ASM_REWRITE[WORD_VAL] substitutes zt1w:=val(read X23 ?) and
       closes the register reads + the value eqn, leaving val(read X23 ?)<2^64 /\ zk1<2^(64k). *)
    FIRST_X_ASSUM(fun t -> if is_eq(concl t) && rand(concl t) = `zt1w:num` &&
          (try fst(dest_const(fst(strip_comb(lhand(concl t))))) = "val" with _->false)
        then ASSUME_TAC(SYM t) else NO_TAC) THEN
    ASM_REWRITE_TAC[WORD_VAL] THEN CONJ_TAC THENL
     [REWRITE_TAC[VAL_BOUND_64];
      ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND]];
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  (* ===== 0x3a4 -> 0x400 : NEGADD2_SEG (frame-widen), zt1w/zk1 ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x400`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\ read X20 s = word (p + 3) /\
        bignum_from_memory (m,k) s = b /\
        ?hh cf. bignum_from_memory (z,k) s + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
                zk1 + q2 * 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
                read X10 s = word ((zt1w + hh + bitval cf) MOD 2 EXP 64) /\
                read X9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2
                                  then 2 EXP 64 - 1 else 0)` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
    EXISTS_TAC
     `MAYCHANGE [PC; X5; X6; X7; X8; X9; X10; X15] ,,
      MAYCHANGE [NF; ZF; CF; VF] ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)]` THEN
    CONJ_TAC THENL
     [SUBSUMED_MAYCHANGE_TAC;
      MP_TAC(REWRITE_RULE[SOME_FLAGS]
        (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:int64`;`h2:num`;`q2:num`;`zt1w:num`;
                 `zk1:num`;`b:num`;`p + 3`;`pc:num`] NEGADD2_SEG)) THEN
      ASM_REWRITE_TAC[] THEN
      (* NEGADD2_SEG's instantiated PRE lists the register reads (X21,X15,X23,X20) in a
         different conjunct order than our ENSURES_SEQUENCE PRE (X20 first) -- so the MP'd
         `ens P_a Q C ==> ens P_b Q C` is not literal `A==>A` and ASM_REWRITE alone can't
         close it.  Reconcile via ENSURES_PRECONDITION_THM (P_b ==> P_a, GEN+STRIP+ASM_REWRITE). *)
      DISCH_THEN(fun th ->
        MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
        EXISTS_TAC (rand(rator(rator(concl th)))) THEN
        CONJ_TAC THENL
         [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th])];
    ALL_TAC] THEN
  (* ===== 0x400 -> 0x428 : peel existential, OPTADD_CLOSE_SEG ===== *)
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. ?hh cf. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x400) /\
        read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\ read X20 s = word (p + 3) /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b =
          zk1 + q2 * 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
        read X10 s = word ((zt1w + hh + bitval cf) MOD 2 EXP 64) /\
        read X9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0)` THEN
  CONJ_TAC THENL [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_EXISTS_PRE THEN GEN_TAC THEN
  MATCH_MP_TAC ENSURES_EXISTS_PRE THEN GEN_TAC THEN
  GHOST_INTRO_TAC `zk2:num` `bignum_from_memory (z,k)` THEN
  GHOST_INTRO_TAC `r15:int64` `read X15` THEN
  MATCH_MP_TAC ENSURES_FRAME_SUBSUMED THEN
  EXISTS_TAC
   `MAYCHANGE [PC; X0; X6; X7; X8; X9; X10] ,,
    MAYCHANGE [NF; ZF; CF; VF] ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)]` THEN
  CONJ_TAC THENL [SUBSUMED_MAYCHANGE_TAC; ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x400) /\
         read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\ read X20 s = word (p + 3) /\
         read X9 s = word (if (zt1w + hh + bitval cf) MOD 2 EXP 64 < q2 then 2 EXP 64 - 1 else 0) /\
         read X15 s = r15 /\
         bignum_from_memory (z,k) s = zk2 /\ bignum_from_memory (m,k) s = b) /\
        (zk2 < 2 EXP (64 * k) /\ hh < 2 EXP 64 /\
         zk2 + 2 EXP (64 * k) * (hh + bitval cf) + q2 * b = zk1 + q2 * 2 EXP (64 * k))` THEN
  CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN RULE_ASSUM_TAC BETA_RULE THEN
    FIRST_X_ASSUM(fun th -> if is_conj(concl th) then STRIP_ASSUME_TAC th else NO_TAC) THEN
    BETA_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND];
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;`q2:num`;`zt1w:num`;`zk1:num`;`zk2:num`;`hh:num`;`cf:bool`;
             `b:num`;`a:num`;`p + 3`;`r15:int64`;`pc:num`] OPTADD_CLOSE_SEG)) THEN
  ASM_REWRITE_TAC[] THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(fun t -> if is_eq(concl t) && rand(concl t) = `V1:num`
      then REWRITE_TAC[SYM t] else NO_TAC) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(fun th -> MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
      EXISTS_TAC (rand(rator(rator(concl th)))) THEN
      CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th])]);;

Printf.printf "\n=== splice_308_428_dev.ml: BIGNUM_MOD_308_TO_428 (full Stage-4 splice) ===\n%!";;

(* ---- the WHOLE CHEAT region 0x1a4->0x428 = MAINLOOP ;; 308_TO_428.
   NB requires mainloop_wrap.ml's MAINLOOP POST to carry aligned_bytes_loaded (added cont108ar).
   MAINLOOP discharge: MP + ASM_REWRITE (discharges all precond EXCEPT the DIVISION identity whose
   orientation is reversed vs my `divid` hyp) then ANTS_TAC[CONV_TAC SYM_CONV;ASM] then POST-weaken.
   GHOST X23->Ztv/z-mem->zk at 0x308 + ENSURES_PRE_DISCH lift (Ztv<2^64 via VAL_BOUND_64 -- X23 holds
   word Ztv so val<2^64 directly; zk<2^(64k) via BIGNUM_FROM_MEMORY_BOUND; cong/bound from MAINLOOP POST)
   then BIGNUM_MOD_308_TO_428.  MAINLOOP half = MP + ASM_REWRITE (POST matches exactly; ANTS incl the
   forward DIVISION identity discharged from context). *)
let BIGNUM_MOD_1A4_TO_428 = prove
 (`!k z n x m a b w d p pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\ p < 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\ a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\ ~(b = 0) /\
      val(w:int64) < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ 61 <= p /\
      p + 3 < 2 EXP 64 /\ p <= 64 * k /\ d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + val(w:int64)) * d <= 2 EXP 128 /\ 2 EXP 128 <= (2 EXP 64 + val(w:int64) + 1) * d /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\ nonoverlapping (word pc,0x438) (m,8 * k) /\
      nonoverlapping (word pc,0x438) (x,8 * n) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
            read X4 s = m /\ read X23 s = word 0 /\ read X20 s = word p /\ read X21 s = w /\
            read X16 s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
            read X17 s = word 61 /\ read X19 s = word 1 /\ read X12 s = word (p DIV 64 + 1) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            read X15 s = word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) DIV 2 EXP p) MOD 2 EXP 64) /\
            2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s =
              a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
       (\s. read PC s = word (pc + 0x428) /\ bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt h8k hp64 hn hn1 ha hbk hb0 hw hbp hpb h1p hp61 hp3 hpk hd hdisj hup hlo hn1o hn2o hn3o hn4o hn5o" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (* MAINLOOP's 3 extra recip-window preconds *)
  SUBGOAL_THEN `2 EXP p <= b * 2 EXP 64` (LABEL_TAC "pleb") THENL
   [TRANS_TAC LE_TRANS `2 EXP (p - 1) * 2 EXP 64` THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM EXP_ADD; LE_EXP; ARITH_EQ] THEN UNDISCH_TAC `1 <= p` THEN ARITH_TAC;
      REWRITE_TAC[LE_MULT_RCANCEL] THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(SPECL [`b * 2 EXP 64`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
  DISCH_THEN(fun th -> LABEL_TAC "divid" (SYM(CONJUNCT1 th))) THEN
  SUBGOAL_THEN `(b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64` (LABEL_TAC "t0hi") THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REWRITE_TAC[GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `2 EXP p * 2 EXP 64` THEN CONJ_TAC THENL
     [REWRITE_TAC[LT_MULT_RCANCEL; EXP_EQ_0; ARITH_EQ] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM EXP_ADD; LE_EXP; ARITH_EQ] THEN ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `0 < (b * 2 EXP 64) DIV 2 EXP p` (LABEL_TAC "t0lo") THENL
   [REWRITE_TAC[ARITH_RULE `0 < n <=> ~(n = 0)`] THEN
    ASM_SIMP_TAC[DIV_EQ_0; EXP_EQ_0; ARITH_EQ] THEN REWRITE_TAC[NOT_LT] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== 0x1a4 -> 0x308 via MAINLOOP ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x308`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
        read X4 s = m /\ read X20 s = word p /\ read X21 s = w /\ read X12 s = word (p DIV 64 + 1) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s == a) (mod b) /\
        2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
        read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                            DIV 2 EXP p) MOD 2 EXP 64)` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `w:int64`; `d:num`; `p:num`; `pc:num`] BIGNUM_MOD_MAINLOOP) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[SOME_FLAGS] THEN
    MATCH_MP_TAC(REWRITE_RULE[TAUT `(a==>b==>c) <=> (a/\b==>c)`]
      (DISCH_ALL(DISCH_ALL(UNDISCH(SPEC_ALL ENSURES_POSTCONDITION_THM))))) THEN
    BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== 0x308 -> 0x428 via 308_TO_428: GHOST X23/z to name Ztv/zk ===== *)
  GHOST_INTRO_TAC `Ztv:num` `\s. val(read X23 s)` THEN
  GHOST_INTRO_TAC `zk:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x308) /\
         read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\ read X20 s = word p /\
         read X21 s = w /\ read X23 s = word Ztv /\
         read X15 s = word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
         bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b) /\
        (Ztv < 2 EXP 64 /\ zk < 2 EXP (64 * k) /\
         (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
         2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64)` THEN
  CONJ_TAC THENL
   [(* weaken: MAINLOOP-POST(val X23, bignum) x  ==>  base(word Ztv,zk) /\ facts.
       val(read X23 x)=Ztv already substituted by GHOST; WORD_VAL/VAL_BOUND_64 give X23=word Ztv/Ztv<2^64;
       BIGNUM_FROM_MEMORY_BOUND gives zk<2^(64k); cong/bound are the PRE's own conjuncts. *)
    GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[WORD_VAL; VAL_BOUND_64] THEN
    ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND; WORD_VAL; VAL_BOUND_64];
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:int64`;`d:num`;`p:num`;`a:num`;`b:num`;`Ztv:num`;`zk:num`;`pc:num`]
       BIGNUM_MOD_308_TO_428)) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
    EXISTS_TAC (rand(rator(rator(concl th)))) THEN
    CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th]));;

Printf.printf "\n=== splice_308_428_dev.ml: BIGNUM_MOD_1A4_TO_428 (WHOLE CHEAT region) ===\n%!";;

(* FINAL ASSEMBLY (cont108ap-aq): BIGNUM_MOD_308_TO_428.  Structure PROVEN piecewise:
   accuracy setup (all facts land in one block) ;; ENSURES_SEQUENCE[0x3a4] NEGADD1_SEG (discharged
   via MP + POST-weaken idiom + ENSURES_PRECONDITION reconcile for X23/X15 order) ;; then 0x3a4->0x428.
   THREADING FINDING (cont108aq): the 0x3a4->0x428 tail is NOT cleanly factored as NEGADD2_SEG;;
   OPTADD_CLOSE_SEG because NEGADD2's POST is EXISTENTIAL (?hh cf) and OPTADD_CLOSE_SEG needs the
   value-eqn / hh<2^64 / zk2<2^(64k) as GLOBAL hyps -- after ENSURES_EXISTS_PRE peels hh,cf they sit
   in the intermediate PRE lambda, not in the tactic context, so OPTADD_CLOSE_SEG's ANTS is
   unprovable at the call site.  CORRECT ASSEMBLY: do the whole 0x3a4->0x428 inside BIGNUM_MOD_308_TO_428
   WITHOUT the NEGADD2_OPTADD_SEG intermediate: after NEGADD1_SEG, ENSURES_SEQUENCE[0x400] w/ NEGADD2_SEG
   (frame-widen via ENSURES_FRAME_SUBSUMED), then MATCH_MP_TAC ENSURES_PRECONDITION_THM to pull the
   existential OUT and simultaneously STRIP hh/cf/value-eqn/X10/X9 into CONTEXT (not re-bury), GHOST zk2/r15,
   derive zk2<2^(64k), then apply OPTADD_CLOSE_SEG (all its ANTS now context hyps).  The peel must land
   hh,cf,value-eqn as hyps: use `GEN_TAC THEN GEN_TAC THEN GHOST... THEN STRIP` on an ENSURES_SEQUENCE
   intermediate stated as `(base-regs) /\ value-eqn /\ hh<2^64 /\ X10... /\ X9...` (value facts OUTSIDE
   any per-state binder) so they become context after the sequence's second-half INIT.
   ALL segment lemmas (NEGADD1_SEG, NEGADD2_SEG, OPTADD_CLOSE_SEG) + accuracy + ENSURES_EXISTS_PRE PROVEN.

   EXACT ASSEMBLY ORDER (cont108aq, validated through NEGADD1; tail order pinned):
   1. accuracy setup (one block: q1le/V1lt/q1fit/h2small/h2fit/q2setupfit/q2le/V1ltq2/congV1/q2fit);
   2. ENSURES_SEQUENCE[0x3a4] <NEGADD1_SEG POST>; CONJ1 = NEGADD1_SEG via
        MP(REWRITE_RULE[SOME_FLAGS](ISPECL[...]NEGADD1_SEG)) THEN ANTS[fold q1def/vdef; EXPAND h1 MOD_LT_EQ;
        V1def/h2def] THEN DISCH_TAC THEN MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
        FIRST_X_ASSUM(ensures)->EXISTS(rand(rator(rator concl))) + [STRIP+ASM_REWRITE; ACCEPT];
   3. At 0x3a4 (POST-of-NEGADD1 is now the goal PRE): GHOST_INTRO zt1w := \s. val(read X23 s),
      zk1 := bignum(z,k); this yields PRE with `2^(64k)*zt1w+zk1 = V1 /\ val(read X23 s)=zt1w /\
      bignum(z,k) s=zk1`.  Derive zt1w<2^64 (QLE_FIT[2^(64k);V1]: zt1w*2^(64k)<=V1<2^(64k)*2^64 from
      V1<2^(p+2),p<=64k), zk1<2^(64k) (from bignum eqn via BIGNUM_FROM_MEMORY_BOUND), read X23 s=word zt1w
      (WORD_VAL o SYM of val=zt1w).  Rewrite q2le/V1ltq2/congV1 (currently on V1) to the
      `2^(64k)*zt1w+zk1` form (= V1 by the ghost eqn) so they match OPTADD_CLOSE_SEG's V:=2^(64k)*zt1w+zk1.
   4. ENSURES_SEQUENCE[0x400] <NEGADD2 existential POST with zt1w,zk1>; CONJ1 = NEGADD2_SEG via
      ENSURES_FRAME_SUBSUMED (widen [PC;X5..X10;X15]->splice frame) THEN MP(REWRITE[SOME_FLAGS] NEGADD2_SEG)+ASM;
   5. CONJ2 (0x400->0x428): ENSURES_PRECONDITION to pull ?hh cf OUT (EXISTS `\s. ?hh cf. <flat body>`,
      weaken by ASM_MESON) THEN ENSURES_EXISTS_PRE x2 THEN GEN hh, GEN cf THEN GHOST zk2/r15 THEN
      ENSURES_FRAME_SUBSUMED(->OPTADD frame [PC;X0;X6..X10]) THEN ENSURES_PRECONDITION strengthen with
      zk2<2^(64k) (BETA+STRIP the applied-lambda hyp; ASM_MESON[BIGNUM_FROM_MEMORY_BOUND]) THEN
      MP(REWRITE[SOME_FLAGS] OPTADD_CLOSE_SEG[q2;zt1w;zk1;zk2;hh;cf;b;a;p+3;r15]) -- its ANTS
      (zk2<2^(64k)/hh<2^64/value-eqn) are NOW context hyps -- THEN ANTS[ASM_REWRITE] THEN
      PRE-reconcile (ENSURES_PRECONDITION + FIRST_X_ASSUM ensures + EXISTS + [STRIP+ASM; ACCEPT]).
   The value-eqn/hh<2^64 become context hyps at step 5 because ENSURES_EXISTS_PRE+GEN lifts hh,cf to
   schematic vars and the subsequent ENSURES_PRECONDITION strengthen's GEN+STRIP exposes the flat body. *)


(* ======== inlined: negadd_small.ml ======== *)
(* ============================================================================
   negadd_small.ml (cont108ay) -- the p<61 (small single-word modulus) Stage-4 splice.
   Mirrors splice_308_428_dev.ml's BIGNUM_MOD_308_TO_428 with the p<61 substitutions:
     * 61<=p  ->  1<=p /\ p<61
     * 2nd-pass window h2 = (V1 DIV 2^(p-61))MOD2^64  ->  h2 = (V1 * 2^(61-p))MOD2^64 (LEFT shift)
     * NEGADD1_SEG -> NEGADD1_SEG_SMALL (wraps BIGNUM_MOD_NEGADD1_LOG_SMALL)
     * RED2 -> RED2_SMALL ; WINDOW2_SMALL -> WINDOW2_SMALL_P (h2<2^63 for p<=61)
   NEGADD2_SEG and OPTADD_CLOSE_SEG are p-agnostic (0 refs to p-61) and reused verbatim.
   Accuracy engine (RED_LEMMA_D via PASS1_RED, QLE_FIT, MULTOP_FITS, CONG_ADD_MULB,
   NEGADD_PASSES_CLOSE) is all p-general.  Produces BIGNUM_MOD_308_TO_428_SMALL, then
   BIGNUM_MOD_1A4_TO_428_SMALL = MAINLOOP ;; 308_TO_428_SMALL (MAINLOOP needs only 1<=p).
   Deps: red2_small.ml (RED2_SMALL/FUNNEL_SMALL), negadd1_log_small.ml (NEGADD1_LOG_SMALL),
   splice_308_428_dev.ml (NEGADD2_SEG, OPTADD_CLOSE_SEG, ENSURES_EXISTS_PRE, ENSURES_PRE_DISCH,
   BIGNUM_MOD_308_TO_428), accuracy_close.ml (PASS1_RED, QLE_FIT, MULTOP_FITS), mainloop_wrap.ml,
   modclose_helpers.ml (NEGADD_PASSES_CLOSE via OPTADD_CLOSE_SEG).  DEV (not yet CI).
   ============================================================================ *)

(* h2 = (V1*2^(61-p)) MOD 2^64 has no wrap and h2 < 2^63, for V1<2^(p+2), p<=61. *)
let WINDOW2_SMALL_P = prove
 (`!V1 p. V1 < 2 EXP (p + 2) /\ p <= 61
          ==> (V1 * 2 EXP (61 - p)) MOD 2 EXP 64 = V1 * 2 EXP (61 - p) /\
              V1 * 2 EXP (61 - p) < 2 EXP 63`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `V1 * 2 EXP (61 - p) < 2 EXP 63` ASSUME_TAC THENL
   [TRANS_TAC LTE_TRANS `2 EXP (p + 2) * 2 EXP (61 - p)` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[LT_MULT_RCANCEL; EXP_EQ_0; ARITH_EQ];
      REWRITE_TAC[GSYM EXP_ADD; LE_EXP; ARITH_EQ] THEN UNDISCH_TAC `p <= 61` THEN ARITH_TAC];
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD_LT THEN
    TRANS_TAC LT_TRANS `2 EXP 63` THEN ASM_REWRITE_TAC[LT_EXP] THEN ARITH_TAC]);;

Printf.printf "\n=== negadd_small.ml: WINDOW2_SMALL_P ===\n%!";;

(* PASS1_RED_GEN: PASS1_RED with 1<=p (the `61<=p` in PASS1_RED is spurious -- its proof only
   uses it to get 1<=p; the pass-1 accuracy is RED_LEMMA_D on V, window h1=V DIV 2^p, p-general). *)
let PASS1_RED_GEN = prove
 (`!b p w d h1 V.
      ~(b = 0) /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\
      d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + val(w:int64)) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + val(w:int64) + 1) * d /\
      V < b * 2 EXP 64 /\
      h1 = (V DIV 2 EXP p) MOD 2 EXP 64
      ==> ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b <= V /\
          V - ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b < 2 EXP (p + 2)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hb0 hblt hpb hp hd hdisj hup hlo hv hh1" THEN
  MP_TAC(SPECL [`b:num`; `p:num`; `val(w:int64)`; `d:num`; `h1:num`; `V MOD 2 EXP p`; `V:num`] RED_LEMMA_D) THEN
  ANTS_TAC THENL
   [SUBGOAL_THEN `V DIV 2 EXP p < 2 EXP 64` ASSUME_TAC THENL
     [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN
      TRANS_TAC LTE_TRANS `b * 2 EXP 64` THEN ASM_REWRITE_TAC[] THEN
      ONCE_REWRITE_TAC[MULT_SYM] THEN REWRITE_TAC[LE_MULT_LCANCEL] THEN
      DISJ2_TAC THEN MATCH_MP_TAC LT_IMP_LE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `h1 = V DIV 2 EXP p` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(V DIV 2 EXP p) MOD 2 EXP 64 = V DIV 2 EXP p` SUBST1_TAC THENL
     [MATCH_MP_TAC MOD_LT THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`V:num`; `2 EXP p`] DIVISION) THEN
    REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT2 th] THEN GEN_REWRITE_TAC (LAND_CONV o LAND_CONV) [CONJUNCT1 th]);
    ALL_TAC] THEN
  REWRITE_TAC[GSYM QHAT_ID] THEN STRIP_TAC THEN
  CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    MATCH_MP_TAC(ARITH_RULE `q <= V /\ V < q + e ==> V - q < e`) THEN ASM_REWRITE_TAC[]]);;

Printf.printf "\n=== negadd_small.ml: PASS1_RED_GEN ===\n%!";;

(* NEGADD1_SEG_SMALL: wrapper over BIGNUM_MOD_NEGADD1_LOG_SMALL, POST X15 = word h2
   (h2 = (V1 * 2^(61-p)) MOD 2^64), value 2^(64k)*X23 + z = V1.  Extra precond V1 < 2^(p+2). *)
let NEGADD1_SEG_SMALL = prove
 (`!k z m w h1 h2 p b Ztv zk pc V1.
      ~(k = 0) /\ k < 2 EXP 58 /\ 1 <= p /\ p < 61 /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\ h1 < 2 EXP 64 /\
      (val(w:int64) * h1) DIV 2 EXP 64 + h1 < 2 EXP 64 /\
      ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b <= 2 EXP (64 * k) * Ztv + zk /\
      V1 = (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b /\
      V1 < 2 EXP (p + 2) /\
      h2 = (V1 * 2 EXP (61 - p)) MOD 2 EXP 64 /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\ nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\ read X15 s = word h1 /\ read X23 s = word Ztv /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x3a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word (p + 3) /\ read X21 s = w /\ read X15 s = word h2 /\
            bignum_from_memory (m,k) s = b /\
            2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s = V1)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b < 2 EXP (p + 2)`
    ASSUME_TAC THENL
   [UNDISCH_TAC `V1 < 2 EXP (p + 2)` THEN
    UNDISCH_TAC `V1 = (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`k:num`; `z:int64`; `m:int64`; `w:int64`; `h1:num`; `p:num`;
                `b:num`; `Ztv:num`; `zk:num`; `pc:num`] BIGNUM_MOD_NEGADD1_LOG_SMALL) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(REWRITE_RULE[TAUT `(a==>b==>c) <=> (a/\b==>c)`]
    (DISCH_ALL(DISCH_ALL(UNDISCH(SPEC_ALL ENSURES_POSTCONDITION_THM))))) THEN
  BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `V1 = (2 EXP (64 * k) * Ztv + zk) - ((val(w:int64) * h1) DIV 2 EXP 64 + h1) * b` THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[]);;

Printf.printf "\n=== negadd_small.ml: NEGADD1_SEG_SMALL ===\n%!";;

(* BIGNUM_MOD_308_TO_428_SMALL : the p<61 Stage-4 splice 0x308->0x428.  Same shape as
   BIGNUM_MOD_308_TO_428 but 1<=p/\p<61, left-shift window, RED2_SMALL, NEGADD1_SEG_SMALL. *)
let BIGNUM_MOD_308_TO_428_SMALL = prove
 (`!k z m w d p a b Ztv zk pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 1 <= p /\ p < 61 /\ p + 3 < 2 EXP 64 /\ p <= 64 * k /\
      b < 2 EXP (64 * k) /\ ~(b = 0) /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\
      zk < 2 EXP (64 * k) /\ Ztv < 2 EXP 64 /\ d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + val(w:int64)) * d <= 2 EXP 128 /\
      2 EXP 128 <= (2 EXP 64 + val(w:int64) + 1) * d /\
      (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
      2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64 /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\ nonoverlapping (z,8 * k) (m,8 * k)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x308) /\
            read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\
            read X20 s = word p /\ read X21 s = w /\ read X23 s = word Ztv /\
            read X15 s = word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
            bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b)
       (\s. read PC s = word (pc + 0x428) /\ bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt hp hp61 hp3 hpk hbk hb0 hbp hpb hzk hZt hd hdisj hup hlo hcong hVlt hn1 hn2 hn3" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  ABBREV_TAC `V = 2 EXP (64 * k) * Ztv + zk` THEN
  ABBREV_TAC `h1 = (V DIV 2 EXP p) MOD 2 EXP 64` THEN
