(* ============================================================================
   BIGNUM_MOD_1A4_TO_428_SMALL : the whole p<61 CHEAT region 0x1a4->0x428 =
   MAINLOOP ;; 308_TO_428_SMALL.  Identical to BIGNUM_MOD_1A4_TO_428 (splice_308_428_dev.ml)
   but 61<=p -> p<61 and final MP uses BIGNUM_MOD_308_TO_428_SMALL.  MAINLOOP needs only 1<=p.
   ============================================================================ *)
let BIGNUM_MOD_1A4_TO_428_SMALL = prove
 (`!k z n x m a b w d p pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\ p < 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\ a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\ ~(b = 0) /\
      val(w:int64) < 2 EXP 64 /\ b < 2 EXP p /\ 2 EXP (p - 1) <= b /\ 1 <= p /\ p < 61 /\
      p + 3 < 2 EXP 64 /\ p <= 64 * k /\ d < 2 EXP 64 /\
      (d = (b * 2 EXP 64) DIV 2 EXP p + 1 \/
       ((b * 2 EXP 64) DIV 2 EXP p = 2 EXP 64 - 1 /\ d = 2 EXP 64 - 1)) /\
      (2 EXP 64 + val(w:int64)) * d <= 2 EXP 128 /\ 2 EXP 128 <= (2 EXP 64 + val(w:int64) + 1) * d /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\ nonoverlapping (word pc,0x438) (m,8 * k) /\
      nonoverlapping (word pc,0x438) (x,8 * n) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\ nonoverlapping (z,8 * k) (x,8 * n)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x1a4) /\
            read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
            read X4 s = m /\ read X23 s = word 0 /\ read X20 s = word p /\ read X21 s = w /\
            read X16 s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
            read X17 s = word 61 /\ read X19 s = word 1 /\ read X12 s = word (p DIV 64 + 1) /\
            bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
            read X15 s = word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)) DIV 2 EXP p) MOD 2 EXP 64) /\
            2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s =
              a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
       (\s. read PC s = word (pc + 0x428) /\ bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,, MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "hk hklt h8k hp64 hn hn1 ha hbk hb0 hw hbp hpb h1p hp61 hp3 hpk hd hdisj hup hlo hn1o hn2o hn3o hn4o hn5o" THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  SUBGOAL_THEN `2 EXP p <= b * 2 EXP 64` (LABEL_TAC "pleb") THENL
   [TRANS_TAC LE_TRANS `2 EXP (p - 1) * 2 EXP 64` THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM EXP_ADD; LE_EXP; ARITH_EQ] THEN UNDISCH_TAC `1 <= p` THEN ARITH_TAC;
      REWRITE_TAC[LE_MULT_RCANCEL] THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  MP_TAC(SPECL [`b * 2 EXP 64`; `2 EXP p`] DIVISION) THEN REWRITE_TAC[EXP_EQ_0; ARITH_EQ] THEN
  DISCH_THEN(fun th -> LABEL_TAC "divid" (SYM(CONJUNCT1 th))) THEN
  SUBGOAL_THEN `(b * 2 EXP 64) DIV 2 EXP p < 2 EXP 64` (LABEL_TAC "t0hi") THENL
   [SIMP_TAC[RDIV_LT_EQ; EXP_EQ_0; ARITH_EQ] THEN REWRITE_TAC[GSYM EXP_ADD] THEN
    TRANS_TAC LTE_TRANS `2 EXP p * 2 EXP 64` THEN CONJ_TAC THENL
     [REWRITE_TAC[LT_MULT_RCANCEL; EXP_EQ_0; ARITH_EQ] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[GSYM EXP_ADD; LE_EXP; ARITH_EQ] THEN ARITH_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `0 < (b * 2 EXP 64) DIV 2 EXP p` (LABEL_TAC "t0lo") THENL
   [REWRITE_TAC[ARITH_RULE `0 < n <=> ~(n = 0)`] THEN
    ASM_SIMP_TAC[DIV_EQ_0; EXP_EQ_0; ARITH_EQ] THEN REWRITE_TAC[NOT_LT] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* ===== 0x1a4 -> 0x308 via MAINLOOP (1<=p) ===== *)
  ENSURES_SEQUENCE_TAC `pc + 0x308`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\ read X3 s = x /\
        read X4 s = m /\ read X20 s = word p /\ read X21 s = w /\ read X12 s = word (p DIV 64 + 1) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        (2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s == a) (mod b) /\
        2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s < b * 2 EXP 64 /\
        read X15 s = word (((2 EXP (64 * k) * val(read X23 s) + bignum_from_memory (z,k) s)
                            DIV 2 EXP p) MOD 2 EXP 64)` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `w:int64`; `d:num`; `p:num`; `pc:num`] BIGNUM_MOD_MAINLOOP) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[SOME_FLAGS] THEN
    MATCH_MP_TAC(REWRITE_RULE[TAUT `(a==>b==>c) <=> (a/\b==>c)`]
      (DISCH_ALL(DISCH_ALL(UNDISCH(SPEC_ALL ENSURES_POSTCONDITION_THM))))) THEN
    BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* ===== 0x308 -> 0x428 via 308_TO_428_SMALL ===== *)
  GHOST_INTRO_TAC `Ztv:num` `\s. val(read X23 s)` THEN
  GHOST_INTRO_TAC `zk:num` `bignum_from_memory (z,k)` THEN
  MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
  EXISTS_TAC
   `\s. (aligned_bytes_loaded s (word pc) bignum_mod_mc /\ read PC s = word (pc + 0x308) /\
         read X0 s = word k /\ read X1 s = z /\ read X4 s = m /\ read X20 s = word p /\
         read X21 s = w /\ read X23 s = word Ztv /\
         read X15 s = word (((2 EXP (64 * k) * Ztv + zk) DIV 2 EXP p) MOD 2 EXP 64) /\
         bignum_from_memory (z,k) s = zk /\ bignum_from_memory (m,k) s = b) /\
        (Ztv < 2 EXP 64 /\ zk < 2 EXP (64 * k) /\
         (2 EXP (64 * k) * Ztv + zk == a) (mod b) /\
         2 EXP (64 * k) * Ztv + zk < b * 2 EXP 64)` THEN
  CONJ_TAC THENL
   [GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[WORD_VAL; VAL_BOUND_64] THEN
    ASM_MESON_TAC[BIGNUM_FROM_MEMORY_BOUND; WORD_VAL; VAL_BOUND_64];
    ALL_TAC] THEN
  MATCH_MP_TAC ENSURES_PRE_DISCH THEN STRIP_TAC THEN
  MP_TAC(REWRITE_RULE[SOME_FLAGS]
    (ISPECL [`k:num`;`z:int64`;`m:int64`;`w:int64`;`d:num`;`p:num`;`a:num`;`b:num`;`Ztv:num`;`zk:num`;`pc:num`]
       BIGNUM_MOD_308_TO_428_SMALL)) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> MATCH_MP_TAC ENSURES_PRECONDITION_THM THEN
    EXISTS_TAC (rand(rator(rator(concl th)))) THEN
    CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC th]));;

