(* ======== inlined: splice_68_428_dev.ml ======== *)
(* ============================================================================
   splice_68_428_dev.ml (cont108av) -- BIGNUM_MOD_68_TO_428.
   The COMPLETE end-to-end DEV composition pc+0x68 (finder POST) -> pc+0x428
   (final: bignum(z,k) = a MOD b), for the nge0 (~(b=0)) path, p := bitsize b.
   Identical in structure to BIGNUM_MOD_68_TO_308 (splice_68_308_dev.ml) EXCEPT the
   final leg is 0x1a4->0x428 via BIGNUM_MOD_1A4_TO_428 (whole main loop + all Stage-4
   corrections) instead of 0x1a4->0x308 via MAINLOOP.  The RECIP_CLUSTER assembly
   (d := val t0, w, p := bitsize b) feeds 1A4_TO_428's recip-of-d preconds directly.

     0x68 -> 0x98   BIGNUM_MOD_WINUP_D   (window+roundup, exposes roundup disjunction)
     0x98 -> 0x13c  BIGNUM_MOD_RECIP_WIDE (word_recip; real-division bracket on val t0)
     0x13c-> 0x1a4  BIGNUM_MOD_PREHEADER  (n/61 setup; threads X21=w)
     0x1a4-> 0x428  BIGNUM_MOD_1A4_TO_428 (main loop + negadd1/2 + optadd + MOD-close)

   This is THE single CI-integration object: the CORRECT proof, after FINDER
   (which lands at 0x68), splices this in one MP, closing the whole CHEAT region.
   POST is the UNCONDITIONAL bignum(z,k)=a MOD b (CORRECT wraps it under ~(b=0)).

   NB precond n < 2^58 - 1 (1A4_TO_428/MAINLOOP tightened bound).  Needs the extra
   1A4_TO_428 spec preconds p+3<2^64 (=bitsize b + 3, from bitsize b <= 64k < 2^64)
   and 61<=p, p<=64k, 2^(p-1)<=b, b<2^p, 1<=p -- all supplied by RECIP_CLUSTER or
   BITSIZE facts.  Deps: WINUP_D, RECIP_WIDE, PREHEADER, RECIP_CLUSTER,
   BIGNUM_MOD_1A4_TO_428.  NOT loaded into CI (dev scaffold for the splice).
   ============================================================================ *)

let BIGNUM_MOD_68_TO_428 = prove
 (`!k z n x m a b pc.
      ~(k = 0) /\ k < 2 EXP 58 /\ 8 * k <= 2 EXP 64 /\
      n < 2 EXP 58 - 1 /\ 1 <= n /\
      a < 2 EXP (64 * n) /\ b < 2 EXP (64 * k) /\ ~(b = 0) /\
      nonoverlapping (word pc,0x438) (z,8 * k) /\
      nonoverlapping (word pc,0x438) (m,8 * k) /\
      nonoverlapping (word pc,0x438) (x,8 * n) /\
      nonoverlapping (z,8 * k) (m,8 * k) /\
      nonoverlapping (z,8 * k) (x,8 * n)
      ==> ensures arm
       (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
            read PC s = word (pc + 0x68) /\
            read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
            read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
            bignum_from_memory (x,n) s = a /\
            bignum_from_memory (m,k) s = b /\
            bignum_from_memory (z,k) s = 0 /\
            read X8 s = word k /\
            (read X11 s = word 0 /\ read X5 s = word 0 /\ read X6 s = word 0 /\
             (!j. j < k ==> bigdigit b j = 0)
             \/
             val(read X11 s) < k /\
             ~(bigdigit b (val(read X11 s)) = 0) /\
             read X5 s = word(bigdigit b (val(read X11 s))) /\
             read X6 s = word(if val(read X11 s) = 0 then 0
                              else bigdigit b (val(read X11 s) - 1)) /\
             (!j. val(read X11 s) < j /\ j < k ==> bigdigit b j = 0)))
       (\s. read PC s = word (pc + 0x428) /\
            bignum_from_memory (z,k) s = a MOD b)
       (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12; X13; X14; X15;
                   X16; X17; X19; X20; X21; X22; X23; X24] ,,
        MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
        MAYCHANGE [memory :> bignum(z,k)])`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  REWRITE_TAC[SOME_FLAGS] THEN
  (*** 0x68 -> 0x98 via WINUP_D (carries roundup disjunction) ***)
  ENSURES_SEQUENCE_TAC `pc + 0x98`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
        read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
        read X20 s = word (bitsize b) /\
        bignum_from_memory (x,n) s = a /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0 /\
        (~(b = 0) ==> bit 63 (read X5 s)) /\
        (val(read X5 s) = (b * 2 EXP 64) DIV 2 EXP (bitsize b) + 1 \/
         (b * 2 EXP 64) DIV 2 EXP (bitsize b) = 2 EXP 64 - 1 /\
         val(read X5 s) = 2 EXP 64 - 1)` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `pc:num`] BIGNUM_MOD_WINUP_D) THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN (UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (*** 0x98 -> 0x13c via RECIP_WIDE (bracket on val t0); disjunction becomes free fact ***)
  GHOST_INTRO_TAC `t0:int64` `read X5` THEN
  GLOBALIZE_PRECONDITION_TAC THEN
  ENSURES_SEQUENCE_TAC `pc + 0x13c`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
        read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
        read X20 s = word (bitsize b) /\
        bignum_from_memory (x,n) s = a /\
        bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0 /\
        (bit 63 (t0:int64)
         ==> &2 pow 64 + &(val(read X21 s)) < &2 pow 128 / &(val t0) /\
             &2 pow 128 / &(val t0) <= &2 pow 64 + &(val(read X21 s)) + &1)` THEN
  CONJ_TAC THENL
   [ENSURES_PRECONDITION_TAC
     `\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
          read PC s = word (pc + 0x98) /\
          read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
          read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
          read X20 s = word (bitsize b) /\ read X5 s = (t0:int64) /\
          bignum_from_memory (x,n) s = a /\
          bignum_from_memory (m,k) s = b /\
          bignum_from_memory (z,k) s = 0` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[] THEN X_GEN_TAC `s:armstate` THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                    `a:num`; `b:num`; `bitsize b`; `t0:int64`; `pc:num`]
             BIGNUM_MOD_RECIP_WIDE) THEN
      REWRITE_TAC[SOME_FLAGS] THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN (UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC);
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  (*** 0x13c -> 0x1a4 via PREHEADER (threads X21=w) ***)
  GHOST_INTRO_TAC `w:int64` `read X21` THEN
  GLOBALIZE_PRECONDITION_TAC THEN
  SUBGOAL_THEN `bitsize b < 2 EXP 64` ASSUME_TAC THENL
   [TRANS_TAC LET_TRANS `64 * k` THEN CONJ_TAC THENL
     [ASM_REWRITE_TAC[BITSIZE_LE];
      UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `k < 2 EXP 64` ASSUME_TAC THENL
   [UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `n < 2 EXP 60` ASSUME_TAC THENL
   [UNDISCH_TAC `n < 2 EXP 58 - 1` THEN ARITH_TAC; ALL_TAC] THEN
  ENSURES_SEQUENCE_TAC `pc + 0x1a4`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
        read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
        read X20 s = word (bitsize b) /\ read X21 s = w /\
        read X16 s = word (61 * ((64 * n + 60) DIV 61 - 1)) /\
        read X17 s = word 61 /\ read X19 s = word 1 /\
        read X12 s = word (bitsize b DIV 64 + 1) /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        read X15 s = word ((a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1)))
                           DIV 2 EXP (bitsize b) MOD 2 EXP 64) /\
        2 EXP (64*k) * val(read X23 s) + bignum_from_memory (z,k) s =
          a DIV 2 EXP (61 * ((64 * n + 60) DIV 61 - 1))` THEN
  CONJ_TAC THENL
   [ENSURES_PRECONDITION_TAC
     `\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
          read PC s = word (pc + 0x13c) /\
          read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
          read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
          read X20 s = word (bitsize b) /\ read X21 s = w /\
          bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
          bignum_from_memory (z,k) s = 0` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[] THEN X_GEN_TAC `s:armstate` THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                    `a:num`; `b:num`; `w:int64`; `bitsize b`; `pc:num`]
             BIGNUM_MOD_PREHEADER) THEN
      REWRITE_TAC[SOME_FLAGS] THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN NONOVERLAPPING_TAC;
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  (*** 0x1a4 -> 0x428: establish the two p-independent global bounds bitsize b <= 64k and
       bitsize b + 3 < 2^64 (both consumed by 1A4_TO_428 and 1A4_TO_428_SMALL as preconds),
       assemble the recip-of-d cluster, then CASE-SPLIT on 61<=bitsize b.
       ASM_CASES_TAC gives subgoal 1 = 61<=p (LARGE, BIGNUM_MOD_1A4_TO_428),
                          subgoal 2 = ~(61<=p) = p<61 (SMALL, BIGNUM_MOD_1A4_TO_428_SMALL).
       Both consume the same recip-of-d cluster + p=bitsize b + the two global bounds, differing
       only in the 61<=p / p<61 precond.  POST matches in both. ***)
  SUBGOAL_THEN `bitsize b <= 64 * k` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[BITSIZE_LE]; ALL_TAC] THEN
  SUBGOAL_THEN `bitsize b + 3 < 2 EXP 64` ASSUME_TAC THENL
   [SUBGOAL_THEN `(2:num) EXP 64 = 64 * 2 EXP 58` ASSUME_TAC THENL
     [CONV_TAC NUM_REDUCE_CONV; ALL_TAC] THEN
    MAP_EVERY UNDISCH_TAC
      [`(2:num) EXP 64 = 64 * 2 EXP 58`; `bitsize b <= 64 * k`; `k < 2 EXP 58`] THEN
    ARITH_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`b:num`; `t0:int64`; `w:int64`] RECIP_CLUSTER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ASM_CASES_TAC `61 <= bitsize b` THENL
   [(* subgoal 1: hyp 61<=bitsize b -> BIGNUM_MOD_1A4_TO_428 *)
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `w:int64`; `val(t0:int64)`; `bitsize b`; `pc:num`]
                 BIGNUM_MOD_1A4_TO_428) THEN
    ASM_REWRITE_TAC[SOME_FLAGS] THEN REWRITE_TAC[VAL_BOUND_64] THEN
    DISCH_TAC THEN
    FIRST_X_ASSUM(fun dth ->
      if (try fst(dest_const(fst(strip_comb(concl dth)))) = "ensures" with _ -> false)
      then let mlq = rand(rator(concl dth)) in
           MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN EXISTS_TAC mlq THEN
           CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC dth]
      else NO_TAC);
    (* subgoal 2: hyp ~(61<=bitsize b) i.e. p<61 -> BIGNUM_MOD_1A4_TO_428_SMALL *)
    SUBGOAL_THEN `bitsize b < 61` ASSUME_TAC THENL
     [UNDISCH_TAC `~(61 <= bitsize b)` THEN ARITH_TAC; ALL_TAC] THEN
    MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`;
                  `a:num`; `b:num`; `w:int64`; `val(t0:int64)`; `bitsize b`; `pc:num`]
                 BIGNUM_MOD_1A4_TO_428_SMALL) THEN
    ASM_REWRITE_TAC[SOME_FLAGS] THEN REWRITE_TAC[VAL_BOUND_64] THEN
    DISCH_TAC THEN
    FIRST_X_ASSUM(fun dth ->
      if (try fst(dest_const(fst(strip_comb(concl dth)))) = "ensures" with _ -> false)
      then let mlq = rand(rator(concl dth)) in
           MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN EXISTS_TAC mlq THEN
           CONJ_TAC THENL [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ACCEPT_TAC dth]
      else NO_TAC)]);;

