(* ======== final theorems: BIGNUM_MOD_CORRECT + SUBROUTINE_CORRECT ======== *)
(* ============================================================================
   ci_correct_edit.ml (cont109) -- the VALIDATED replacement for BIGNUM_MOD_CORRECT
   in arm/proofs/bignum_mod.ml.  Proven 0-hyp WARM this session (all dev deps loaded).

   CHANGES vs the CI original (lines 2672-2966):
     - PRECOND: add  nonoverlapping (word pc,0x438) (x,8 * val n)
                     nonoverlapping (word pc,0x438) (m,8 * val k)   [pc-x, pc-m: the
                       main-loop/correction ARM-sim needs code disjoint from the read
                       buffers; cdiv's cleaner spec omits these -- future refinement]
                and  ~(b = 0)                                        [user decision cont109:
                       code has no b=0 early-out; b=0 POST is vacuous but MAINLOOP needs b>0]
                and  tighten  val n < 2 EXP 58  ->  val n < 2 EXP 58 - 1  [X17 j-counter
                       64-bit wrap at n~2^58-1; pre-authorized]
     - PROOF: Stage 1 INIT (0x24), Stage 2a n=0, Stage 2b-0 fallthrough (0x2c),
              Stage 2b-i FINDER (0x68) UNCHANGED, then the CHEAT region 0x68->0x428
              (old lines 2829-2966: WINUP/RECIP_WIDE/PREHEADER/CHEAT) REPLACED by a single
              MP of BIGNUM_MOD_68_TO_428 + POST-weaken to the guarded ~(b=0)==> POST.

   This file is a REFERENCE for the edit; the actual edit is applied to
   arm/proofs/bignum_mod.ml.  It presumes the whole dev chain (RELOAD_SESSION order,
   through negadd_small.ml + splice_68_428_dev.ml) is loaded above CORRECT.
   ============================================================================ *)

let BIGNUM_MOD_CORRECT = prove
 (`!k z n x m a b pc.
        nonoverlapping (word pc,0x438) (z,8 * val k) /\
        nonoverlapping (word pc,0x438) (x,8 * val n) /\
        nonoverlapping (word pc,0x438) (m,8 * val k) /\
        ALLPAIRS nonoverlapping
          [(z,8 * val k)] [(word pc,0x438); (x,8 * val n); (m,8 * val k)] /\
        ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0)
        ==> ensures arm
             (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
                  read PC s = word (pc + 0xc) /\
                  C_ARGUMENTS [k;z;n;x;m] s /\
                  bignum_from_memory (x,val n) s = a /\
                  bignum_from_memory (m,val k) s = b)
             (\s. read PC s = word(pc + 0x428) /\
                  (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
             (MAYCHANGE [PC; X0; X5; X6; X7; X8; X9; X10; X11; X12;
                         X13; X14; X15; X16; X17; X19; X20; X21; X22; X23; X24] ,,
              MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events] ,,
              MAYCHANGE [memory :> bignum(z,val k)])`,
  W64_GEN_TAC `k:num` THEN X_GEN_TAC `z:int64` THEN W64_GEN_TAC `n:num` THEN
  MAP_EVERY X_GEN_TAC [`x:int64`; `m:int64`; `a:num`; `b:num`; `pc:num`] THEN
  REWRITE_TAC[NONOVERLAPPING_CLAUSES; ALLPAIRS; ALL; C_ARGUMENTS; SOME_FLAGS] THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  BIGNUM_TERMRANGE_TAC `n:num` `a:num` THEN
  BIGNUM_TERMRANGE_TAC `k:num` `b:num` THEN
  (*** Stage 1: zeroing loop to pc+0x24 (BIGNUM_MOD_INIT) ***)
  ENSURES_SEQUENCE_TAC `pc + 0x24`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
        read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0` THEN
  CONJ_TAC THENL
   [MP_TAC(ISPECL [`word k:int64`; `z:int64`; `word n:int64`; `x:int64`;
                   `m:int64`; `a:num`; `b:num`; `pc:num`] BIGNUM_MOD_INIT) THEN
    ASM_REWRITE_TAC[NONOVERLAPPING_CLAUSES; ALLPAIRS; ALL; C_ARGUMENTS; SOME_FLAGS] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  (*** Stage 2a: n=0 early-out ***)
  ASM_CASES_TAC `n = 0` THENL
   [UNDISCH_THEN `n = 0` SUBST_ALL_TAC THEN
    SUBGOAL_THEN `a = 0` SUBST_ALL_TAC THENL
     [UNDISCH_TAC `a < 2 EXP (64 * 0)` THEN CONV_TAC NUM_REDUCE_CONV THEN ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[MOD_0] THEN ARM_SIM_TAC BIGNUM_MOD_EXEC (1--2);
    ALL_TAC] THEN
  (*** Stage 2b-0: fall through n<>0 test 0x24 -> 0x2c ***)
  ENSURES_SEQUENCE_TAC `pc + 0x2c`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
        read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0` THEN
  CONJ_TAC THENL
   [ARM_SIM_TAC BIGNUM_MOD_EXEC (1--2) THEN
    SUBGOAL_THEN `val(word_sub (word n) (word 0):int64) = n` SUBST1_TAC THENL
     [REWRITE_TAC[WORD_SUB_0] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[VAL_WORD_0] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (*** Stage 2b-i: FINDER 0x2c -> 0x68 (UNCHANGED from CI original) ***)
  ENSURES_SEQUENCE_TAC `pc + 0x68`
   `\s. read X0 s = word k /\ read X1 s = z /\ read X2 s = word n /\
        read X3 s = x /\ read X4 s = m /\ read X23 s = word 0 /\
        bignum_from_memory (x,n) s = a /\ bignum_from_memory (m,k) s = b /\
        bignum_from_memory (z,k) s = 0 /\ read X8 s = word k /\
        (read X11 s = word 0 /\ read X5 s = word 0 /\ read X6 s = word 0 /\
         (!j. j < k ==> bigdigit b j = 0)
         \/
         val(read X11 s) < k /\ ~(bigdigit b (val(read X11 s)) = 0) /\
         read X5 s = word(bigdigit b (val(read X11 s))) /\
         read X6 s = word(if val(read X11 s) = 0 then 0 else bigdigit b (val(read X11 s) - 1)) /\
         (!j. val(read X11 s) < j /\ j < k ==> bigdigit b j = 0))` THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`; `a:num`; `b:num`; `pc:num`]
      BIGNUM_MOD_FINDER) THEN
    REWRITE_TAC[SOME_FLAGS] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN NONOVERLAPPING_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  (*** Stages 2b-ii..6 (0x68 -> 0x428): the WHOLE former CHEAT region, via
       BIGNUM_MOD_68_TO_428 (= WINUP_D;;RECIP_WIDE;;PREHEADER;;1A4_TO_428 case-split on
       61<=bitsize b), POST-weakened to CORRECT's guarded ~(b=0)==> postcondition. ***)
  MP_TAC(SPECL [`k:num`; `z:int64`; `n:num`; `x:int64`; `m:int64`; `a:num`; `b:num`; `pc:num`]
    BIGNUM_MOD_68_TO_428) THEN
  ASM_REWRITE_TAC[SOME_FLAGS] THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [UNDISCH_TAC `k < 2 EXP 58` THEN ARITH_TAC;
      UNDISCH_TAC `~(n = 0)` THEN ARITH_TAC;
      NONOVERLAPPING_TAC; NONOVERLAPPING_TAC; NONOVERLAPPING_TAC;
      NONOVERLAPPING_TAC; NONOVERLAPPING_TAC];
    ALL_TAC] THEN
  DISCH_TAC THEN
  FIRST_X_ASSUM(fun dth ->
    if (try fst(dest_const(fst(strip_comb(concl dth)))) = "ensures" with _ -> false)
    then let mlq = rand(rator(concl dth)) in
         MATCH_MP_TAC ENSURES_POSTCONDITION_THM THEN EXISTS_TAC mlq THEN
         CONJ_TAC THENL
          [BETA_TAC THEN GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[];
           ACCEPT_TAC dth]
    else NO_TAC));;

