(* SUBROUTINE_CORRECT: same recipe as the CI original, matching strengthened precond
   (pc-x, pc-m, ~(b=0), n<2^58-1 added).  Proven 0-hyp warm this session. *)
let BIGNUM_MOD_SUBROUTINE_CORRECT = prove
 (`!k z n x m a b pc stackpointer returnaddress.
        aligned 16 stackpointer /\
        ~(val k = 0) /\ val k < 2 EXP 58 /\ val n < 2 EXP 58 - 1 /\ ~(b = 0) /\
        nonoverlapping (word pc,0x438) (z,8 * val k) /\
        nonoverlapping (word pc,0x438) (x,8 * val n) /\
        nonoverlapping (word pc,0x438) (m,8 * val k) /\
        nonoverlapping (word_sub stackpointer (word 48),48) (z,8 * val k) /\
        ALLPAIRS nonoverlapping
          [(z,8 * val k); (word_sub stackpointer (word 48),48)]
          [(word pc,0x438); (x,8 * val n); (m,8 * val k)]
        ==> ensures arm
             (\s. aligned_bytes_loaded s (word pc) bignum_mod_mc /\
                  read PC s = word pc /\
                  read SP s = stackpointer /\
                  read X30 s = returnaddress /\
                  C_ARGUMENTS [k;z;n;x;m] s /\
                  bignum_from_memory (x,val n) s = a /\
                  bignum_from_memory (m,val k) s = b)
             (\s. read PC s = returnaddress /\
                  (~(b = 0) ==> bignum_from_memory (z,val k) s = a MOD b))
             (MAYCHANGE_REGS_AND_FLAGS_PERMITTED_BY_ABI ,,
              MAYCHANGE [memory :> bignum(z,val k)] ,,
              MAYCHANGE [memory :> bytes(word_sub stackpointer (word 48),48)])`,
  ARM_ADD_RETURN_STACK_TAC BIGNUM_MOD_EXEC BIGNUM_MOD_CORRECT
    `[X19;X20;X21;X22;X23;X24]` 48);;

